'use client'

// ============================================================
// app/admin/question-feedback/page.tsx — Question report queue
// ============================================================
// PAGINATION, NOT INFINITE SCROLL. This is a work queue, not a feed: an admin
// needs to see how many reports are outstanding, work a page, and come back to
// the same place afterwards. Infinite scroll hides the total, loses position
// on navigate-back, and makes "have I handled everything?" unanswerable. The
// candidate-facing module list is the opposite case, which is why that one
// scrolls.
// ============================================================

import React, { useCallback, useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import {
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  ChevronUp,
  Flag,
  Loader2,
  RefreshCw,
  Search,
  Check,
  Ban,
  ArrowLeft,
} from 'lucide-react'
import { toast } from 'sonner'
import { useAuth } from '@/app/contexts/AuthContext'
import { LoadingScreen } from '@/components/ui/loading-screen'
import QuestionEditor from '@/app/components/admin/QuestionEditor'
import {
  FEEDBACK_REASONS,
  FEEDBACK_REASON_LABEL,
  type AdminFeedbackItem,
  type AdminFeedbackListResponse,
  type FeedbackReason,
  type FeedbackStatus,
} from '@/types/question-feedback'

const STATUS_TABS: { id: FeedbackStatus | 'all'; label: string }[] = [
  { id: 'open', label: 'Open' },
  { id: 'resolved', label: 'Resolved' },
  { id: 'dismissed', label: 'Dismissed' },
  { id: 'all', label: 'All' },
]

/** Reasons this question was flagged for, busiest first. */
function reasonBreakdown(item: AdminFeedbackItem): [FeedbackReason, number][] {
  return (Object.entries(item.reason_counts ?? {}) as [FeedbackReason, number][])
    .filter(([, n]) => n > 0)
    .sort((a, b) => b[1] - a[1])
}

function formatWhen(iso: string) {
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return '—'
  return d.toLocaleString('en-IN', {
    day: 'numeric',
    month: 'short',
    hour: 'numeric',
    minute: '2-digit',
  })
}

export default function QuestionFeedbackPage() {
  const router = useRouter()
  const { user, loading: authLoading } = useAuth()

  const [status, setStatus] = useState<FeedbackStatus | 'all'>('open')
  const [reason, setReason] = useState<string>('all')
  const [search, setSearch] = useState('')
  const [debouncedSearch, setDebouncedSearch] = useState('')
  const [page, setPage] = useState(1)

  const [data, setData] = useState<AdminFeedbackListResponse | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [expanded, setExpanded] = useState<string | null>(null)
  const [updating, setUpdating] = useState<string | null>(null)

  // Non-admins never see this page; the API refuses them regardless.
  useEffect(() => {
    if (!authLoading && user && user.role !== 'admin') router.replace('/dsc-sgt')
    if (!authLoading && !user) router.replace('/')
  }, [authLoading, user, router])

  useEffect(() => {
    const t = setTimeout(() => setDebouncedSearch(search.trim()), 350)
    return () => clearTimeout(t)
  }, [search])

  // Filters changing resets to page 1, adjusted during render so a stale page
  // number never reaches the request.
  const filterKey = `${status}|${reason}|${debouncedSearch}`
  const [lastFilter, setLastFilter] = useState(filterKey)
  if (lastFilter !== filterKey) {
    setLastFilter(filterKey)
    setPage(1)
  }

  const load = useCallback(async () => {
    try {
      const params = new URLSearchParams({ status, page: String(page), pageSize: '20' })
      if (reason !== 'all') params.set('reason', reason)
      if (debouncedSearch) params.set('search', debouncedSearch)

      const res = await fetch(`/api/admin/question-feedback?${params.toString()}`)
      const json = (await res.json()) as AdminFeedbackListResponse
      if (!res.ok || !json.success) {
        setError(json.error ?? 'Could not load reports')
        return
      }
      setError(null)
      setData(json)
    } catch {
      setError('Network error — please try again')
    } finally {
      setLoading(false)
    }
  }, [status, reason, debouncedSearch, page])

  useEffect(() => {
    void load()
  }, [load])

  const setItemStatus = async (item: AdminFeedbackItem, next: FeedbackStatus) => {
    setUpdating(item.id)
    try {
      const res = await fetch(`/api/admin/question-feedback/${item.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: next }),
      })
      const json = await res.json()
      if (!res.ok || !json.success) {
        toast.error('Could not update', { description: json.error })
        return
      }
      toast.success(next === 'resolved' ? 'Marked resolved' : next === 'dismissed' ? 'Dismissed' : 'Reopened')
      await load()
    } catch {
      toast.error('Network error — please try again')
    } finally {
      setUpdating(null)
    }
  }

  if (authLoading) return <LoadingScreen message="Checking access…" />
  if (!user || user.role !== 'admin') return null

  const items = data?.items ?? []
  const counts = data?.counts ?? { open: 0, resolved: 0, dismissed: 0 }
  const totalPages = data?.total_pages ?? 1

  return (
    <main className="mx-auto max-w-5xl px-4 py-8 sm:px-6 lg:px-8">
      {/* ── Header ── */}
      <div className="mb-6">
        <button
          onClick={() => router.push('/admin')}
          className="mb-4 inline-flex items-center gap-1.5 text-[11px] font-medium text-muted-foreground transition hover:text-foreground"
        >
          <ArrowLeft className="h-3.5 w-3.5" />
          Admin dashboard
        </button>

        <div className="flex flex-wrap items-end justify-between gap-4">
          <div>
            <p className="bloom-eyebrow">Content quality</p>
            <h1 className="mt-1.5 flex items-center gap-2.5 text-2xl font-medium text-foreground">
              <Flag className="h-5 w-5 text-primary" strokeWidth={1.7} />
              Question reports
            </h1>
            <p className="mt-2 max-w-lg text-xs leading-relaxed text-muted-foreground">
              One entry per question, however many candidates flagged it.
              Editing a question here updates the question bank, so the fix
              reaches both practice and every mock module using it.
            </p>
          </div>

          <button
            onClick={() => void load()}
            className="inline-flex items-center gap-2 rounded-full border border-border px-3.5 py-2 text-[11px] font-medium text-muted-foreground transition hover:text-foreground"
          >
            <RefreshCw className="h-3.5 w-3.5" />
            Refresh
          </button>
        </div>
      </div>

      {/* ── Filters ── */}
      <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-wrap items-center gap-1 rounded-full border border-border bg-muted/40 p-1">
          {STATUS_TABS.map((t) => (
            <button
              key={t.id}
              onClick={() => setStatus(t.id)}
              className={`rounded-full px-3.5 py-1.5 text-[11px] font-medium transition ${
                status === t.id ? 'bg-card text-foreground shadow-xs' : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              {t.label}
              {t.id !== 'all' && (
                <span className="ml-1.5 opacity-60">{counts[t.id as FeedbackStatus]}</span>
              )}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-2.5">
          <select
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            className="h-9 rounded-full border border-border bg-card px-3 text-[11px] text-foreground focus:outline-none"
          >
            <option value="all">All reasons</option>
            {FEEDBACK_REASONS.map((r) => (
              <option key={r.id} value={r.id}>
                {r.label}
              </option>
            ))}
          </select>

          <div className="relative">
            <Search className="absolute left-3.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground" />
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search question id…"
              className="h-9 w-48 rounded-full border border-border bg-card pl-9 pr-3 text-[11px] text-foreground placeholder:text-muted-foreground focus:outline-none"
            />
          </div>
        </div>
      </div>

      {/* ── States ── */}
      {loading && (
        <div className="flex flex-col items-center gap-3 py-20">
          <Loader2 className="h-6 w-6 animate-spin text-primary" />
          <p className="text-xs text-muted-foreground">Loading reports…</p>
        </div>
      )}

      {!loading && error && (
        <div className="flex flex-col items-center gap-3 py-20 text-center">
          <p className="text-xs text-destructive">{error}</p>
          <button
            onClick={() => void load()}
            className="rounded-full border border-border px-4 py-2 text-xs font-medium text-muted-foreground hover:text-foreground"
          >
            Try again
          </button>
        </div>
      )}

      {!loading && !error && items.length === 0 && (
        <div className="flex flex-col items-center gap-2 py-20 text-center">
          <Flag className="h-7 w-7 text-muted-foreground/40" strokeWidth={1.5} />
          <p className="text-sm font-medium text-foreground">Nothing here</p>
          <p className="text-xs text-muted-foreground">
            {status === 'open' ? 'No open reports — the queue is clear.' : 'No reports match these filters.'}
          </p>
        </div>
      )}

      {/* ── Queue ── */}
      {!loading && !error && items.length > 0 && (
        <div className="space-y-3">
          {items.map((item) => {
            const isOpen = expanded === item.id
            return (
              <article key={item.id} className="rounded-2xl border border-border bg-card">
                <div className="flex flex-wrap items-start gap-3 p-4">
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                      {/* How many people, and what they each said */}
                      <span
                        className={`rounded-full px-2.5 py-0.5 text-[11px] font-semibold ${
                          item.report_count >= 5
                            ? 'bg-destructive/15 text-destructive'
                            : item.report_count > 1
                              ? 'bg-amber-500/15 text-amber-700 dark:text-amber-300'
                              : 'bg-secondary text-secondary-foreground'
                        }`}
                      >
                        {item.report_count} report{item.report_count === 1 ? '' : 's'}
                      </span>

                      {reasonBreakdown(item).map(([reasonId, n]) => (
                        <span
                          key={reasonId}
                          className="rounded-full bg-muted px-2 py-0.5 text-[11px] font-medium text-muted-foreground"
                        >
                          {FEEDBACK_REASON_LABEL[reasonId] ?? reasonId}
                          {n > 1 ? ` ×${n}` : ''}
                        </span>
                      ))}

                      {item.subject_label && (
                        <span className="text-[11px] text-muted-foreground">
                          {item.subject_label}
                          {item.medium ? ` · ${item.medium}` : ''}
                        </span>
                      )}
                      {item.status !== 'open' && (
                        <span className="rounded-full bg-muted px-2 py-0.5 text-[11px] font-medium text-muted-foreground">
                          {item.status}
                        </span>
                      )}
                    </div>

                    <p className="mt-2 line-clamp-2 text-xs font-medium text-foreground">
                      {item.reported_question ?? item.question_uid}
                    </p>

                    {item.recent_reports.slice(0, 2).map(
                      (r) =>
                        r.details && (
                          <p
                            key={r.id}
                            className="mt-1.5 line-clamp-2 text-[11px] italic text-muted-foreground"
                          >
                            “{r.details}” — {r.reporter?.name ?? r.reporter?.email ?? 'Unknown'}
                          </p>
                        )
                    )}

                    <p className="mt-2 text-[11px] text-muted-foreground">
                      Last reported {item.last_reported_at ? formatWhen(item.last_reported_at) : '—'}{' '}
                      · <code>{item.question_uid}</code>
                    </p>
                  </div>

                  <div className="flex shrink-0 items-center gap-1.5">
                    {item.status !== 'resolved' && (
                      <button
                        onClick={() => void setItemStatus(item, 'resolved')}
                        disabled={updating === item.id}
                        title="Mark resolved"
                        className="rounded-full border border-emerald-500/30 p-2 text-emerald-600 transition hover:bg-emerald-500/10 disabled:opacity-50 dark:text-emerald-400"
                      >
                        <Check className="h-3.5 w-3.5" />
                      </button>
                    )}
                    {item.status !== 'dismissed' && (
                      <button
                        onClick={() => void setItemStatus(item, 'dismissed')}
                        disabled={updating === item.id}
                        title="Dismiss"
                        className="rounded-full border border-border p-2 text-muted-foreground transition hover:text-foreground disabled:opacity-50"
                      >
                        <Ban className="h-3.5 w-3.5" />
                      </button>
                    )}
                    {item.status !== 'open' && (
                      <button
                        onClick={() => void setItemStatus(item, 'open')}
                        disabled={updating === item.id}
                        className="rounded-full border border-border px-3 py-1.5 text-[11px] font-medium text-muted-foreground transition hover:text-foreground disabled:opacity-50"
                      >
                        Reopen
                      </button>
                    )}
                    <button
                      onClick={() => setExpanded(isOpen ? null : item.id)}
                      className="inline-flex items-center gap-1.5 rounded-full border border-border px-3 py-1.5 text-[11px] font-medium text-muted-foreground transition hover:text-foreground"
                    >
                      {isOpen ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
                      {isOpen ? 'Close' : 'Edit question'}
                    </button>
                  </div>
                </div>

                {isOpen && (
                  <div className="border-t border-border p-4">
                    <QuestionEditor questionUid={item.question_uid} onSaved={() => void load()} />
                  </div>
                )}
              </article>
            )
          })}
        </div>
      )}

      {/* ── Pagination ── */}
      {!loading && !error && totalPages > 1 && (
        <div className="mt-8 flex items-center justify-center gap-3">
          <button
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={page <= 1}
            className="inline-flex items-center gap-1 rounded-full border border-border px-3 py-2 text-[11px] font-medium text-muted-foreground transition hover:text-foreground disabled:cursor-not-allowed disabled:opacity-40"
          >
            <ChevronLeft className="h-3.5 w-3.5" /> Previous
          </button>
          <span className="text-[11px] text-muted-foreground">
            Page {page} of {totalPages} · {data?.total ?? 0} report
            {(data?.total ?? 0) === 1 ? '' : 's'}
          </span>
          <button
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            disabled={page >= totalPages}
            className="inline-flex items-center gap-1 rounded-full border border-border px-3 py-2 text-[11px] font-medium text-muted-foreground transition hover:text-foreground disabled:cursor-not-allowed disabled:opacity-40"
          >
            Next <ChevronRight className="h-3.5 w-3.5" />
          </button>
        </div>
      )}
    </main>
  )
}

// ============================================================
// app/api/admin/mock-tests/[id]/generate/route.ts
// POST /api/admin/mock-tests/[id]/generate
// ============================================================
// Generates 160 fixed questions for a draft mock test using the blueprint.
// Can be called multiple times (idempotent — replaces previous mapping).
// ONLY works on draft tests (not published ones).
// ============================================================

import { NextResponse } from 'next/server'
import { requireAdmin } from '@/lib/auth/session'
import { getMockTestById, generateAndStoreMockQuestions } from '@/lib/mock-tests/db'

export const POST = requireAdmin(async (
  _request: Request,
  { params }: { params: Promise<{ id: string }> },
  _auth: any
) => {
  try {
    const { id } = await params

    const test = await getMockTestById(id)
    if (!test) {
      return NextResponse.json({ success: false, error: 'Mock test not found' }, { status: 404 })
    }
    if (test.status === 'published') {
      return NextResponse.json(
        { success: false, error: 'Cannot regenerate questions for a published test. Archive or create a new version.' },
        { status: 400 }
      )
    }

    // The test's own medium decides which source tables are eligible, so an
    // English test can never be filled with Telugu-medium content.
    const { mappings, validation, warnings } = await generateAndStoreMockQuestions(
      test.id,
      test.blueprint_id,
      test.medium,
      test.module_number ?? 1
    )

    return NextResponse.json({
      success: true,
      generated_count: mappings.length,
      medium: test.medium,
      validation,
      warnings,
      section_breakdown: Object.entries(validation.section_counts).map(([sectionId, counts]) => ({
        section_id: sectionId,
        expected: counts.expected,
        got: counts.got,
        valid: counts.valid,
      })),
    })
  } catch (err: unknown) {
    console.error('[POST generate]', err)
    const message = err instanceof Error ? err.message : 'Generation failed'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
})

// ============================================================
// app/api/admin/mock-tests/[id]/preview/route.ts
// GET /api/admin/mock-tests/[id]/preview
// ============================================================
// Returns question distribution stats and validation result
// before publishing. Does NOT include correct answers.
// ============================================================

import { NextResponse } from 'next/server'
import { requireAdmin } from '@/lib/auth/session'
import { getMockTestById } from '@/lib/mock-tests/db'
import { supabaseAdmin } from '@/lib/supabase-admin'
import { getBlueprintById } from '@/lib/mock-tests/blueprints'
import { validateBlueprint } from '@/lib/mock-tests/validator'
import { resolveGenerationMedium } from '@/lib/mock-tests/generator'

export const GET = requireAdmin(async (
  _request: Request,
  { params }: { params: Promise<{ id: string }> },
  _auth: any
) => {
  try {
    const { id } = await params

    const test = await getMockTestById(id)
    if (!test) {
      return NextResponse.json({ success: false, error: 'Mock test not found' }, { status: 404 })
    }

    // Fetch mappings with question metadata for full validation
    const { data: mappings, error } = await supabaseAdmin
      .from('mock_test_questions')
      .select('id, mock_test_id, question_uid, question_id, question_table, question_number, section_id, section_name, marks, created_at')
      .eq('mock_test_id', id)
      .order('question_number', { ascending: true })

    if (error) {
      return NextResponse.json({ success: false, error: error.message }, { status: 500 })
    }

    const blueprint = getBlueprintById(test.blueprint_id)
    if (!blueprint) {
      return NextResponse.json({ success: false, error: 'Blueprint not found' }, { status: 500 })
    }

    const validation = validateBlueprint(blueprint, mappings || [], {
      medium: resolveGenerationMedium(test.medium),
      distributionAsWarning: true,
    })

    // Group by section for preview
    const sectionGroups: Record<
      string,
      { section_id: string; section_name: string; count: number; tables: string[]; question_uids: string[] }
    > = {}
    for (const m of mappings || []) {
      if (!sectionGroups[m.section_id]) {
        sectionGroups[m.section_id] = {
          section_id: m.section_id,
          section_name: m.section_name,
          count: 0,
          tables: [],
          question_uids: [],
        }
      }
      const group = sectionGroups[m.section_id]
      group.count++
      group.question_uids.push(m.question_uid ?? `${m.question_table}:${m.question_id}`)
      if (!group.tables.includes(m.question_table)) group.tables.push(m.question_table)
    }

    return NextResponse.json({
      success: true,
      test_id: id,
      test_title: test.title,
      status: test.status,
      medium: test.medium,
      module_number: test.module_number ?? null,
      series: test.series,
      total_mapped: mappings?.length || 0,
      blueprint_expects: blueprint.total_questions,
      validation,
      sections: Object.values(sectionGroups),
    })
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Internal server error'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
})

// ============================================================
// app/api/admin/mock-tests/[id]/publish/route.ts
// POST /api/admin/mock-tests/[id]/publish
// ============================================================
// Validates, warms Redis cache, and publishes a Grand Mock test.
// Steps:
//   1. Validate 160 questions and distribution
//   2. Batch-fetch question content
//   3. Warm Redis cache (client-safe payload + answer key)
//   4. Set status = 'published'
// ============================================================

import { NextResponse } from 'next/server'
import { requireAdmin } from '@/lib/auth/session'
import { getMockTestById, publishMockTest } from '@/lib/mock-tests/db'

export const POST = requireAdmin(async (
  _request: Request,
  { params }: { params: Promise<{ id: string }> },
  { user }: any
) => {
  try {
    const { id } = await params

    const test = await getMockTestById(id)
    if (!test) {
      return NextResponse.json({ success: false, error: 'Mock test not found' }, { status: 404 })
    }

    const { validation, cacheWarmed } = await publishMockTest(id, user.id)

    if (!validation.valid) {
      return NextResponse.json(
        {
          success: false,
          error: 'Validation failed — cannot publish',
          validation,
        },
        { status: 422 }
      )
    }

    return NextResponse.json({
      success: true,
      message: 'Mock test published successfully',
      cache_warmed: cacheWarmed,
      validation,
    })
  } catch (err: unknown) {
    console.error('[POST publish]', err)
    const message = err instanceof Error ? err.message : 'Publish failed'
    const status = message.includes('already published') ? 409 : 500
    return NextResponse.json({ success: false, error: message }, { status })
  }
})

// ============================================================
// app/api/admin/mock-tests/route.ts
// GET  /api/admin/mock-tests — List all mock tests (all statuses)
// POST /api/admin/mock-tests — Create a new mock test (draft)
// ============================================================

import { NextResponse } from 'next/server'
import { requireAdmin } from '@/lib/auth/session'
import { adminListMockTests, createMockTest } from '@/lib/mock-tests/db'
import { getAllBlueprints } from '@/lib/mock-tests/blueprints'

export const GET = requireAdmin(async (request: Request) => {
  try {
    const url = new URL(request.url)
    const page = Math.max(1, parseInt(url.searchParams.get('page') || '1', 10) || 1)
    const pageSize = parseInt(url.searchParams.get('pageSize') || '50', 10) || 50

    const { tests, total, page: currentPage, page_size } = await adminListMockTests({
      medium: url.searchParams.get('medium') || undefined,
      series: url.searchParams.get('series') || undefined,
      status: url.searchParams.get('status') || undefined,
      page,
      pageSize,
    })

    const blueprints = getAllBlueprints().map((b) => ({
      id: b.id,
      name: b.name,
      description: b.description,
      total_questions: b.total_questions,
      duration_minutes: b.duration_minutes,
      total_marks: b.total_marks,
      sections: b.sections.map((s) => ({
        id: s.id,
        name: s.name,
        total_questions: s.total_questions,
        tables: s.tables,
      })),
    }))

    return NextResponse.json({
      success: true,
      tests,
      blueprints,
      page: currentPage,
      page_size,
      total,
      total_pages: Math.max(1, Math.ceil(total / page_size)),
    })
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Internal server error'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
})

export const POST = requireAdmin(async (request: Request, _context: any, { user }: any) => {
  try {
    const body = await request.json()
    const { slug, title, description, category, medium, blueprint_id, is_free, module_number, series } = body

    if (!slug || !title || !blueprint_id) {
      return NextResponse.json(
        { success: false, error: 'slug, title, and blueprint_id are required' },
        { status: 400 }
      )
    }

    const test = await createMockTest(user.id, {
      slug,
      title,
      description,
      category: category || 'grand_mock',
      // A generated module must belong to exactly one medium, never 'bilingual'.
      medium: medium || 'english',
      blueprint_id,
      is_free: Boolean(is_free),
      module_number: module_number ?? null,
      series: series ?? undefined,
    })

    return NextResponse.json({ success: true, test }, { status: 201 })
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Failed to create mock test'
    const status = message.includes('duplicate') || message.includes('unique') ? 409 : 500
    return NextResponse.json({ success: false, error: message }, { status })
  }
})

// ============================================================
// app/api/admin/plans/route.ts — GET + PATCH /api/admin/plans
// ============================================================
// Admin-only endpoint to view and update subscription plan prices.
// Protected by requireAdmin (server-side role check via JWT + DB).
// Non-admin users always receive 403 ADMIN_REQUIRED.
// ============================================================

import { NextResponse } from 'next/server'
import { requireAdmin } from '@/lib/auth/session'
import { supabaseAdmin } from '@/lib/supabase-admin'
import { PLANS, PLAN_LIST, isPlanId, type Plan, type PlanId } from '@/lib/payments/plans'

// ---- Types -------------------------------------------------------

interface PlanOverrideRow {
  plan_id: string
  amount_paise: number
  original_amount_paise: number
  name: string | null
  period: string | null
  badge: string | null
  features: string[] | null
  updated_by: string | null
  updated_at: string
}

/** Merged plan: code defaults + DB overrides */
export interface AdminPlanView extends Plan {
  hasOverride: boolean
  updatedAt: string | null
}

// ---- Helpers -----------------------------------------------------

async function fetchOverrides(): Promise<Map<string, PlanOverrideRow>> {
  const { data, error } = await supabaseAdmin
    .from('plan_overrides')
    .select('*')

  if (error) {
    console.error('[AdminPlans] fetchOverrides error:', error)
    return new Map()
  }

  const map = new Map<string, PlanOverrideRow>()
  for (const row of (data ?? []) as PlanOverrideRow[]) {
    map.set(row.plan_id, row)
  }
  return map
}

function mergePlan(plan: Plan, override: PlanOverrideRow | undefined): AdminPlanView {
  if (!override) {
    return { ...plan, hasOverride: false, updatedAt: null }
  }
  return {
    ...plan,
    amountPaise: override.amount_paise,
    originalAmountPaise: override.original_amount_paise,
    name: override.name ?? plan.name,
    period: override.period ?? plan.period,
    badge: override.badge ?? plan.badge,
    features: (override.features as string[] | null) ?? plan.features,
    hasOverride: true,
    updatedAt: override.updated_at,
  }
}

// ---- GET /api/admin/plans ----------------------------------------
// Returns the merged plan list (defaults + any DB overrides).

export const GET = requireAdmin(async (_request, _ctx, _auth) => {
  const overrides = await fetchOverrides()

  const plans: AdminPlanView[] = PLAN_LIST.map((plan) =>
    mergePlan(plan, overrides.get(plan.id))
  )

  return NextResponse.json({ plans })
})

// ---- PATCH /api/admin/plans --------------------------------------
// Body: { planId, amountPaise, originalAmountPaise, name?, period?, badge?, features? }
// Upserts a row in plan_overrides.

export const PATCH = requireAdmin(async (request, _ctx, { user }) => {
  let body: Record<string, unknown>
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'INVALID_BODY' }, { status: 400 })
  }

  const { planId, amountPaise, originalAmountPaise, name, period, badge, features } = body

  if (!isPlanId(planId)) {
    return NextResponse.json({ error: 'INVALID_PLAN_ID' }, { status: 400 })
  }

  // Number.isInteger, not `typeof === 'number'`. NaN and Infinity are both
  // numbers, and `NaN < 100` is false, so the old check let them straight
  // through to the database — and a price of NaN is a broken checkout.
  // The ceiling is ₹1,00,000: a fat-fingered extra zero should be rejected,
  // not charged to a candidate.
  const MAX_AMOUNT_PAISE = 100_000_00

  if (
    typeof amountPaise !== 'number' ||
    !Number.isInteger(amountPaise) ||
    amountPaise < 100 ||
    amountPaise > MAX_AMOUNT_PAISE
  ) {
    return NextResponse.json(
      {
        error: 'INVALID_AMOUNT',
        message: `amountPaise must be a whole number between 100 (₹1) and ${MAX_AMOUNT_PAISE} (₹1,00,000)`,
      },
      { status: 400 }
    )
  }

  if (
    typeof originalAmountPaise !== 'number' ||
    !Number.isInteger(originalAmountPaise) ||
    originalAmountPaise < 100 ||
    originalAmountPaise > MAX_AMOUNT_PAISE
  ) {
    return NextResponse.json(
      {
        error: 'INVALID_ORIGINAL_AMOUNT',
        message: `originalAmountPaise must be a whole number between 100 and ${MAX_AMOUNT_PAISE}`,
      },
      { status: 400 }
    )
  }

  if (amountPaise > originalAmountPaise) {
    return NextResponse.json(
      { error: 'PRICE_EXCEEDS_ORIGINAL', message: 'Selling price cannot exceed original price' },
      { status: 400 }
    )
  }

  // Validate features if provided
  if (features !== undefined && features !== null) {
    if (
      !Array.isArray(features) ||
      (features as unknown[]).some((f) => typeof f !== 'string')
    ) {
      return NextResponse.json(
        { error: 'INVALID_FEATURES', message: 'features must be an array of strings' },
        { status: 400 }
      )
    }
  }

  const upsertData: Record<string, unknown> = {
    plan_id: planId,
    amount_paise: amountPaise,
    original_amount_paise: originalAmountPaise,
    updated_by: user.id,
    updated_at: new Date().toISOString(),
  }

  if (typeof name === 'string' && name.trim()) upsertData.name = name.trim()
  if (typeof period === 'string' && period.trim()) upsertData.period = period.trim()
  if (typeof badge === 'string') upsertData.badge = badge.trim() || null
  if (Array.isArray(features)) upsertData.features = features

  const { data, error } = await supabaseAdmin
    .from('plan_overrides')
    .upsert(upsertData, { onConflict: 'plan_id' })
    .select('*')
    .single()

  if (error) {
    console.error('[AdminPlans] upsert error:', error)
    return NextResponse.json({ error: 'DB_ERROR' }, { status: 500 })
  }

  const planDefault = PLANS[planId as PlanId]
  const merged = mergePlan(planDefault, data as PlanOverrideRow)

  console.info('[AdminPlans] Plan override saved:', { planId, amountPaise, by: user.id })

  return NextResponse.json({ success: true, plan: merged })
})

// ---- DELETE /api/admin/plans -------------------------------------
// Resets a plan back to code defaults by removing its override row.

export const DELETE = requireAdmin(async (request, _ctx, _auth) => {
  let body: Record<string, unknown>
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'INVALID_BODY' }, { status: 400 })
  }

  const { planId } = body

  if (!isPlanId(planId)) {
    return NextResponse.json({ error: 'INVALID_PLAN_ID' }, { status: 400 })
  }

  const { error } = await supabaseAdmin
    .from('plan_overrides')
    .delete()
    .eq('plan_id', planId)

  if (error) {
    console.error('[AdminPlans] delete error:', error)
    return NextResponse.json({ error: 'DB_ERROR' }, { status: 500 })
  }

  return NextResponse.json({ success: true, planId, resetToDefault: true })
})

// ============================================================
// app/api/auth/devices/[deviceId]/route.ts
// DELETE /api/auth/devices/:deviceId
// ============================================================
// Revoke the active session for a specific device.
// Does NOT delete device history.
// ============================================================

import { requireAuth } from '@/lib/auth/session'
import { findActiveSessionByDevice, revokeSession, logSecurityEvent } from '@/lib/auth/db'
import { getHashedIp } from '@/lib/auth/ip'
import { handleAuthError, AuthError } from '@/lib/auth/errors'

export const DELETE = requireAuth(async (request, context, { user }) => {
  try {
    const { deviceId } = await context.params as { deviceId: string }

    if (!deviceId) {
      return Response.json({ error: 'deviceId is required' }, { status: 400 })
    }

    const ipHash = getHashedIp(request)

    // Find the active session for this device
    const session = await findActiveSessionByDevice(user.id, deviceId)
    if (!session) {
      return Response.json({ error: 'DEVICE_NOT_FOUND' }, { status: 404 })
    }

    // Revoke it
    await revokeSession(session.id, 'DEVICE_REVOKED')

    // Log security event
    await logSecurityEvent({
      userId: user.id,
      eventType: 'DEVICE_REVOKED',
      deviceId,
      ipHash,
    })

    return Response.json({ success: true })
  } catch (err) {
    return handleAuthError(err)
  }
})

// ============================================================
// app/api/auth/google/route.ts — POST /api/auth/google
// ============================================================
// Full login flow:
// 1. Rate limit check
// 2. Verify Google ID token server-side
// 3. Get trusted client IP → HMAC hash
// 4. Find/create user
// 5. DB: revoke old session → create new session (atomic)
// 6. Issue access token + refresh token
// 7. Web: set HttpOnly cookies | Mobile: return JSON
// 8. After the response: upsert device, write the audit entry
//
// Everything on the critical path is a network round trip, so the ordering
// above is load-bearing: anything the browser does not need before it is
// signed in has been moved out of it.
// ============================================================

import { NextResponse, after } from 'next/server'
import { createHash } from 'crypto'
import { verifyGoogleIdToken } from '@/lib/auth/google'
import { findOrCreateUser, upsertDevice, revokeActiveSession, createSession, logSecurityEvent } from '@/lib/auth/db'
import { getHashedIp } from '@/lib/auth/ip'
import { signAccessToken, generateOpaqueToken, hashRefreshToken } from '@/lib/auth/crypto'
import { setAuthCookies, setOnboardingCookie, getAuthNonceFromCookies, clearAuthNonceCookie } from '@/lib/auth/cookies'
import { checkRateLimit } from '@/lib/auth/rate-limit'
import { handleAuthError, AuthError } from '@/lib/auth/errors'
import { toPublicUser } from '@/lib/auth/types'
import type { Platform, DeviceInfo } from '@/lib/auth/types'
import { supabaseAdmin } from '@/lib/supabase-admin'

/**
 * Convert a Google numeric ID to a deterministic UUID.
 * Used as fallback when Supabase Google provider is not yet enabled.
 * The same Google ID always produces the same UUID.
 */
function googleIdToUuid(googleId: string): string {
  const h = createHash('sha256').update(`dsc-platform:google:${googleId}`).digest('hex')
  return [
    h.slice(0, 8),
    h.slice(8, 12),
    '4' + h.slice(13, 16),
    ((parseInt(h.slice(16, 18), 16) & 0x3f) | 0x80).toString(16).padStart(2, '0') + h.slice(18, 20),
    h.slice(20, 32),
  ].join('-')
}

const ALLOWED_PLATFORMS: Platform[] = ['WEB', 'ANDROID', 'IOS']

/**
 * Does nothing, on purpose.
 *
 * A cold serverless function costs about a second before a single line of the
 * handler below runs, and the landing page knows a sign-in is coming long
 * before the credential arrives. GET and POST of one route file ship in the
 * same bundle, so touching this boots the instance that POST will land on.
 * It reads nothing, writes nothing, and is not rate limited because there is
 * nothing here to abuse.
 */
export function GET(): Response {
  // A one-byte body rather than a 204: fetch() treats an empty no-content
  // response as aborted, which puts a red line in the network panel for a
  // request that did exactly what it was meant to.
  return new Response('ok', {
    status: 200,
    headers: { 'Cache-Control': 'no-store', 'Content-Type': 'text/plain' },
  })
}

export async function POST(request: Request): Promise<Response> {
  try {
    // ---- Parse and validate body ------------------------------------
    let body: unknown
    try {
      body = await request.json()
    } catch {
      return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
    }

    const { idToken, deviceId, platform, userAgent } = body as Record<string, unknown>

    if (typeof idToken !== 'string' || !idToken) {
      return Response.json({ error: 'idToken is required' }, { status: 400 })
    }

    // Single-use nonce issued by GET /api/auth/nonce. Enforced for EVERY
    // platform on purpose: gating it on `platform === 'WEB'` would let an
    // attacker skip the check simply by claiming to be a mobile client.
    const expectedNonce = getAuthNonceFromCookies(request)
    if (!expectedNonce) {
      return Response.json(
        { error: 'AUTH_NONCE_REQUIRED', message: 'Start sign-in again' },
        { status: 400 }
      )
    }
    if (typeof deviceId !== 'string' || !deviceId) {
      return Response.json({ error: 'deviceId is required' }, { status: 400 })
    }
    if (!ALLOWED_PLATFORMS.includes(platform as Platform)) {
      return Response.json(
        { error: `platform must be one of: ${ALLOWED_PLATFORMS.join(', ')}` },
        { status: 400 }
      )
    }

    // ---- Rate limiting -------------------------------------------
    const ipHash = getHashedIp(request)
    const rateKey = `auth:google:${ipHash}`
    const rateResult = await checkRateLimit(rateKey, 'google')
    if (!rateResult.allowed) {
      return Response.json(
        { error: 'RATE_LIMITED', retryAfter: rateResult.retryAfter },
        { status: 429 }
      )
    }

    // ---- Verify Google ID token (server-side) --------------------
    const googleProfile = await verifyGoogleIdToken(idToken, expectedNonce)

    // ---- Find or create user in our custom users table ----------
    // signInWithIdToken gives us a stable supabase_uid, but it is a second
    // full verification of a token this route has already verified itself,
    // and Supabase Auth calls out to Google to do it. Only a first-ever
    // sign-in needs the value, so it is passed as a thunk and never runs for
    // a returning user.
    const user = await findOrCreateUser(googleProfile, async () => {
      const { data, error } = await supabaseAdmin.auth.signInWithIdToken({
        provider: 'google',
        token: idToken,
      })
      if (error || !data.user) {
        // Fallback: Supabase Google provider not yet enabled.
        // Derive a deterministic UUID from the Google ID so it fits the UUID column.
        console.warn('[Auth] Supabase signInWithIdToken failed, deriving UUID from google_id:', error?.message)
        return googleIdToUuid(googleProfile.googleId)
      }
      return data.user.id
    })

    // ---- Device info -------------------------------------------
    const deviceInfo: DeviceInfo = {
      deviceId: deviceId as string,
      platform: platform as Platform,
      userAgent: typeof userAgent === 'string' ? userAgent : (request.headers.get('user-agent') ?? 'unknown'),
    }

    // ---- Generate tokens BEFORE transaction -------------------------
    // (so we have the hash to store)
    const refreshToken = generateOpaqueToken()
    const refreshTokenHash = hashRefreshToken(refreshToken)

    // ---- Atomic DB transaction: revoke old → create new session ----
    // Supabase JS doesn't support multi-statement transactions directly,
    // so we call our RPC or execute steps sequentially with proper error handling.
    // The partial unique index (sessions_one_active_per_user) at DB level
    // guarantees only one ACTIVE session exists even under concurrent logins.

    await revokeActiveSession(user.id, 'NEW_DEVICE_LOGIN')
    const session = await createSession(
      user.id,
      deviceInfo,
      ipHash,
      refreshTokenHash,
      user.session_version
    )

    // ---- Bookkeeping, after the response ------------------------
    // Neither the device row nor the audit entry is read back before the user
    // is signed in, and sessions.device_id carries no foreign key to devices,
    // so making the browser wait on two more writes bought nothing. They still
    // run on the same invocation — `after` defers them past the response
    // rather than dropping them.
    after(async () => {
      await upsertDevice(user.id, deviceInfo, ipHash)
      await logSecurityEvent({
        userId: user.id,
        eventType: 'NEW_DEVICE_LOGIN',
        deviceId: deviceInfo.deviceId,
        ipHash,
        metadata: {
          platform: deviceInfo.platform,
          isNewUser: user.created_at === user.updated_at,
        },
      })
    })

    // ---- Sign access token -------------------------------------
    const accessToken = await signAccessToken({
      sub: user.id,
      sid: session.id,
      sv: user.session_version,
    })

    // ---- Return tokens -----------------------------------------
    const publicUser = toPublicUser(user)

    if ((platform as Platform) === 'WEB') {
      // Web: set HttpOnly cookies, don't return tokens in body
      const response = NextResponse.json({ user: publicUser, sessionId: session.id })
      setAuthCookies(response, { accessToken, refreshToken })
      // Burn the nonce: one sign-in per issued value.
      clearAuthNonceCookie(response)
      // Set onboarding cookie if already completed (returning user)
      if (user.onboarding_completed) {
        setOnboardingCookie(response)
      }
      return response
    } else {
      // Mobile: return tokens in JSON body; client stores in secure storage
      const response = NextResponse.json({
        accessToken,
        refreshToken,
        user: publicUser,
        sessionId: session.id,
      })
      clearAuthNonceCookie(response)
      return response
    }
  } catch (err) {
    return handleAuthError(err)
  }
}

// ============================================================
// app/api/auth/refresh/route.ts — POST /api/auth/refresh
// ============================================================
// Refresh token rotation:
// 1. Read refresh token (cookie for web, body for mobile)
// 2. Hash → find session by hash
// 3. If not found → REFRESH_TOKEN_REUSE_DETECTED
// 4. If found + ACTIVE → rotate: generate new refresh token
// 5. Issue new access token
// 6. Return new tokens
// ============================================================

import { NextResponse } from 'next/server'
import {
  findSessionByRefreshTokenHash,
  rotateRefreshToken,
  revokeSession,
  logSecurityEvent,
  findSessionByPreviousRefreshTokenHash,
  revokeSessionFamily,
} from '@/lib/auth/db'
import { getHashedIp } from '@/lib/auth/ip'
import { signAccessToken, generateOpaqueToken, hashRefreshToken } from '@/lib/auth/crypto'
import { setAuthCookies, getRefreshTokenFromCookies } from '@/lib/auth/cookies'
import { checkRateLimit } from '@/lib/auth/rate-limit'
import { handleAuthError, AuthError } from '@/lib/auth/errors'

/**
 * How long after a rotation the replaced token is still accepted.
 *
 * A client that retries after a network timeout legitimately re-sends the token
 * it already used. Without a leeway window that looks identical to token theft,
 * and the containment response (revoke everything) would log real users out on
 * a flaky connection. Theft is almost always attempted long after the victim's
 * last rotation, so a short window costs very little detection.
 */
const REFRESH_REUSE_LEEWAY_MS = 10_000

/**
 * Build the token response. Web gets HttpOnly cookies; mobile gets JSON,
 * distinguished by whether the refresh token arrived in a cookie.
 */
async function buildRefreshResponse(
  request: Request,
  session: { user_id: string; user?: { onboarding_completed?: boolean } },
  accessToken: string,
  refreshToken: string
): Promise<Response> {
  const isMobile = !getRefreshTokenFromCookies(request)

  if (isMobile) {
    return Response.json({ accessToken, refreshToken })
  }

  const response = NextResponse.json({ success: true })
  setAuthCookies(response, { accessToken, refreshToken })
  if (session.user?.onboarding_completed) {
    const { setOnboardingCookie } = await import('@/lib/auth/cookies')
    setOnboardingCookie(response)
  }
  return response
}

export async function POST(request: Request): Promise<Response> {
  try {
    // ---- Rate limiting -----------------------------------------
    const ipHash = getHashedIp(request)
    const rateResult = await checkRateLimit(`auth:refresh:${ipHash}`, 'refresh')
    if (!rateResult.allowed) {
      return Response.json(
        { error: 'RATE_LIMITED', retryAfter: rateResult.retryAfter },
        { status: 429 }
      )
    }

    // ---- Extract refresh token ---------------------------------
    // Web: from HttpOnly cookie (scoped to /api/auth/refresh)
    // Mobile: from JSON request body
    let rawRefreshToken: string | null = getRefreshTokenFromCookies(request)

    if (!rawRefreshToken) {
      // Mobile path
      try {
        const body = await request.json()
        rawRefreshToken = body?.refreshToken ?? null
      } catch {
        // Body parsing failed — token must be in cookie
      }
    }

    if (!rawRefreshToken) {
      throw new AuthError('UNAUTHORIZED', 401, 'No refresh token provided')
    }

    // ---- Hash the presented token and look up session ----------
    const tokenHash = hashRefreshToken(rawRefreshToken)
    const sessionWithUser = await findSessionByRefreshTokenHash(tokenHash)

    if (!sessionWithUser) {
      // The token matches no CURRENT session hash. Before giving up, check the
      // previous-generation hash: a hit means this token was already rotated
      // away, which is the signature of refresh-token theft (two parties hold
      // tokens from the same chain, and the slower one arrives stale).
      const rotatedAway = await findSessionByPreviousRefreshTokenHash(tokenHash)

      if (rotatedAway) {
        // LEEWAY: a client that retries after a network timeout legitimately
        // re-sends the token it already used. Treating that as theft would log
        // real users out. Anything within the window is accepted as a benign
        // retry of the rotation that just happened; anything older is theft.
        const rotatedAt = rotatedAway.rotated_at ? new Date(rotatedAway.rotated_at).getTime() : 0
        const withinLeeway =
          rotatedAt > 0 && Date.now() - rotatedAt <= REFRESH_REUSE_LEEWAY_MS

        if (withinLeeway && rotatedAway.status === 'ACTIVE') {
          const retryToken = generateOpaqueToken()
          const retryHash = hashRefreshToken(retryToken)
          await rotateRefreshToken(rotatedAway.id, retryHash, tokenHash)

          const retryAccessToken = await signAccessToken({
            sub: rotatedAway.user_id,
            sid: rotatedAway.id,
            sv: rotatedAway.session_version,
          })

          await logSecurityEvent({
            userId: rotatedAway.user_id,
            eventType: 'REFRESH',
            deviceId: rotatedAway.device_id,
            ipHash,
            metadata: { reason: 'rotation_retry_within_leeway' },
          })

          return buildRefreshResponse(request, rotatedAway, retryAccessToken, retryToken)
        }

        // Outside the leeway window: we cannot tell whether the victim or the
        // attacker is calling, so revoke the whole family and invalidate
        // outstanding access tokens. Both are forced to re-authenticate; the
        // thief loses the access they gained.
        await revokeSessionFamily(rotatedAway.user_id, 'refresh_token_reuse_detected')
        await logSecurityEvent({
          userId: rotatedAway.user_id,
          eventType: 'REFRESH_TOKEN_REUSE_DETECTED',
          deviceId: rotatedAway.device_id,
          ipHash,
          metadata: { reason: 'rotated_token_reuse', action: 'session_family_revoked' },
        })
        throw new AuthError('REFRESH_TOKEN_REUSE_DETECTED', 401, 'Refresh token reuse detected')
      }

      // Genuinely unknown token (never valid, or older than one rotation).
      await logSecurityEvent({
        userId: null,
        eventType: 'REFRESH_TOKEN_REUSE_DETECTED',
        ipHash,
        metadata: { reason: 'token_not_found' },
      })
      throw new AuthError('REFRESH_TOKEN_REUSE_DETECTED', 401, 'Refresh token not valid')
    }

    // sessionWithUser has shape: DbSession & { user: DbUser }
    const { user: _user, ...session } = sessionWithUser as { user: import('@/lib/auth/types').DbUser } & import('@/lib/auth/types').DbSession
    const user = (sessionWithUser as unknown as { user: import('@/lib/auth/types').DbUser }).user

    // ---- Check session status ----------------------------------
    if (session.status === 'REVOKED') {
      // The token hash matches a REVOKED session — this is a reuse detection case!
      // A legitimate client would never present a token for a revoked session.
      // Revoke the family again and bump session_version, so any access token
      // still outstanding for this user dies too.
      await revokeSessionFamily(session.user_id, 'revoked_session_token_reuse')
      await logSecurityEvent({
        userId: session.user_id,
        eventType: 'REFRESH_TOKEN_REUSE_DETECTED',
        deviceId: session.device_id,
        ipHash,
        metadata: { reason: 'revoked_session_token_reuse' },
      })
      throw new AuthError('REFRESH_TOKEN_REUSE_DETECTED', 401, 'Refresh token reuse detected')
    }

    if (session.status === 'EXPIRED' || new Date(session.expires_at) < new Date()) {
      throw new AuthError('SESSION_EXPIRED', 401, 'Session has expired')
    }

    // ---- Rotate refresh token (mandatory) ----------------------
    const newRefreshToken = generateOpaqueToken()
    const newTokenHash = hashRefreshToken(newRefreshToken)
    await rotateRefreshToken(session.id, newTokenHash, tokenHash)

    // ---- Issue new access token --------------------------------
    const newAccessToken = await signAccessToken({
      sub: session.user_id,
      sid: session.id,
      sv: session.session_version,
    })

    // ---- Log refresh event -------------------------------------
    await logSecurityEvent({
      userId: session.user_id,
      eventType: 'REFRESH',
      deviceId: session.device_id,
      ipHash,
    })

    // ---- Return new tokens -------------------------------------
    return buildRefreshResponse(
      request,
      { user_id: session.user_id, user },
      newAccessToken,
      newRefreshToken
    )
  } catch (err) {
    return handleAuthError(err)
  }
}

// ============================================================
// app/api/dsc-sgt/practice/weak-topics/route.ts
// ============================================================

import { NextResponse } from 'next/server'
import { getOptionalAuth } from '@/lib/auth/session'
import { supabaseAdmin } from '@/lib/supabase-admin'
import type { WeakAreaRecommendation } from '@/types/practice'

export async function GET(request: Request) {
  try {
    const auth = await getOptionalAuth(request)
    const userId = auth?.user?.id || null

    if (!userId) {
      // Default sample recommendations if unauthenticated/new user
      const sampleRecommendations: WeakAreaRecommendation[] = [
        {
          subject: 'English',
          topic: 'Tenses',
          subtopic: 'Present & Past Perfect',
          total_attempted: 25,
          accuracy_pct: 52,
          incorrect_count: 12,
          recommended_question_count: 20,
          action_label: 'Practice Tenses (52% Accuracy)',
        },
        {
          subject: 'English',
          topic: 'Articles & Prepositions',
          subtopic: 'Prepositions of Place & Time',
          total_attempted: 18,
          accuracy_pct: 60,
          incorrect_count: 7,
          recommended_question_count: 15,
          action_label: 'Practice Prepositions (60% Accuracy)',
        },
      ]

      return NextResponse.json({
        success: true,
        recommendations: sampleRecommendations,
      })
    }

    const { data, error } = await supabaseAdmin
      .from('question_progress')
      .select('*')
      .eq('user_id', userId)

    const recommendations: WeakAreaRecommendation[] = []

    if (!error && data) {
      const topicMap: Record<string, { subject: string; topic: string; correct: number; total: number; incorrect: number }> = {}

      data.forEach((row: any) => {
        const key = `${row.subject}__${row.topic}`
        if (!topicMap[key]) {
          topicMap[key] = {
            subject: row.subject,
            topic: row.topic,
            correct: 0,
            total: 0,
            incorrect: 0,
          }
        }
        topicMap[key].correct += row.correct_count || 0
        topicMap[key].total += row.attempt_count || 0
        topicMap[key].incorrect += row.incorrect_count || 0
      })

      Object.values(topicMap).forEach((st) => {
        const acc = st.total > 0 ? Math.round((st.correct / st.total) * 100) : 0
        if (st.total >= 3 && acc < 65) {
          recommendations.push({
            subject: st.subject,
            topic: st.topic,
            total_attempted: st.total,
            accuracy_pct: acc,
            incorrect_count: st.incorrect,
            recommended_question_count: Math.min(25, Math.max(10, st.incorrect * 3)),
            action_label: `Practice ${st.topic} (${acc}%)`,
          })
        }
      })
    }

    return NextResponse.json({
      success: true,
      recommendations,
    })
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Failed to calculate weak topics'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
}

// ============================================================
// app/api/payments/coupons/route.ts — POST /api/payments/coupons
// ============================================================
// Validates a coupon code and returns the discounted amount for a
// plan. Purely informational for the UI — the order endpoint
// re-validates the coupon itself and never trusts this result.
//
// Prices are resolved from plan_overrides (DB) first so that
// coupon discounts apply to the same price the admin set.
// ============================================================

import { NextResponse } from 'next/server'
import { requireAuth } from '@/lib/auth/session'
import { checkRateLimit } from '@/lib/auth/rate-limit'
import { findCoupon, normalizeCouponCode } from '@/lib/payments/coupons'
import { PLAN_LIST, applyDiscount, type Plan } from '@/lib/payments/plans'
import { supabaseAdmin } from '@/lib/supabase-admin'

interface PlanOverrideRow {
  plan_id: string
  amount_paise: number
}

/** Resolve effective plan prices from DB overrides (falls back to code defaults). */
async function getEffectivePrices(): Promise<Record<string, number>> {
  const prices: Record<string, number> = {}
  for (const plan of PLAN_LIST) {
    prices[plan.id] = plan.amountPaise
  }

  try {
    const { data } = await supabaseAdmin
      .from('plan_overrides')
      .select('plan_id, amount_paise')

    for (const row of (data ?? []) as PlanOverrideRow[]) {
      if (row.plan_id in prices) {
        prices[row.plan_id] = row.amount_paise
      }
    }
  } catch {
    // Silently fall back to code defaults
  }

  return prices
}

export const POST = requireAuth(async (request, _ctx, { user }) => {
  const limit = await checkRateLimit(`coupon:${user.id}`, 'coupon')
  if (!limit.allowed) {
    return NextResponse.json(
      { error: 'RATE_LIMITED', retryAfter: limit.retryAfter },
      { status: 429, headers: { 'Retry-After': String(limit.retryAfter ?? 60) } }
    )
  }

  let body: { code?: unknown }
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'INVALID_BODY' }, { status: 400 })
  }

  const code = normalizeCouponCode(body.code)
  if (!code) {
    return NextResponse.json({ error: 'INVALID_BODY' }, { status: 400 })
  }

  const coupon = findCoupon(code)
  if (!coupon) {
    return NextResponse.json({ valid: false, code })
  }

  // Resolve effective (admin-overridden) base prices, then apply discount
  const basePrices = await getEffectivePrices()
  const prices: Record<string, number> = {}
  for (const plan of PLAN_LIST) {
    prices[plan.id] = applyDiscount(basePrices[plan.id] ?? plan.amountPaise, coupon.discountPercent)
  }

  return NextResponse.json({
    valid: true,
    code: coupon.code,
    discountPercent: coupon.discountPercent,
    prices,
  })
})

// ============================================================
// app/api/payments/plans/route.ts — GET /api/payments/plans
// ============================================================
// Returns the effective subscription plan list for the premium
// modal. Merges admin-editable DB overrides with code defaults.
//
// This is the single source of truth for prices shown to users.
// If an admin changes a price via /api/admin/plans, the next
// call to this endpoint reflects it immediately — no redeploy.
//
// Requires authentication (any logged-in user).
// ============================================================

import { NextResponse } from 'next/server'
import { requireAuth } from '@/lib/auth/session'
import { supabaseAdmin } from '@/lib/supabase-admin'
import { PLAN_LIST, type Plan } from '@/lib/payments/plans'

interface PlanOverrideRow {
  plan_id: string
  amount_paise: number
  original_amount_paise: number
  name: string | null
  period: string | null
  badge: string | null
  features: string[] | null
}

async function getEffectivePlans(): Promise<Plan[]> {
  try {
    const { data, error } = await supabaseAdmin
      .from('plan_overrides')
      .select('plan_id, amount_paise, original_amount_paise, name, period, badge, features')

    if (error || !data) return PLAN_LIST

    const overrideMap = new Map<string, PlanOverrideRow>()
    for (const row of data as PlanOverrideRow[]) {
      overrideMap.set(row.plan_id, row)
    }

    return PLAN_LIST.map((plan): Plan => {
      const override = overrideMap.get(plan.id)
      if (!override) return plan
      return {
        ...plan,
        amountPaise: override.amount_paise,
        originalAmountPaise: override.original_amount_paise,
        name: override.name ?? plan.name,
        period: override.period ?? plan.period,
        badge: override.badge ?? plan.badge,
        features: (override.features as string[] | null) ?? plan.features,
      }
    })
  } catch {
    // Never fail the UI due to a DB override lookup error
    return PLAN_LIST
  }
}

export const GET = requireAuth(async (_request, _ctx, _auth) => {
  const plans = await getEffectivePlans()
  return NextResponse.json({ plans })
})

'use client'

// ============================================================
// app/components/admin/MockModuleGenerator.tsx
// ============================================================
// Admin flow for the predefined module series:
//
//   Select Medium → Select Blueprint → choose module range
//     → Dry Run (validate + review coverage, writes nothing)
//     → Generate & Publish (writes, validates each module, warms Redis)
//
// The dry run exists so the coverage / repetition report can be reviewed
// BEFORE anything is committed. Nothing is published unless it validates.
// ============================================================

import React, { useCallback, useEffect, useState } from 'react'
import {
  Layers,
  Loader2,
  Play,
  RefreshCw,
  AlertTriangle,
  CheckCircle2,
  BarChart3,
  Rocket,
} from 'lucide-react'

interface SectionCoverage {
  section_id: string
  section_name: string
  questions_per_module: number
  slots: number
  eligible_pool: number
  unique_used: number
  repeated_assignments: number
  coverage_pct: number
  min_usage: number
  max_usage: number
}

interface GenerationReport {
  series: string
  medium: string
  blueprint_id: string
  modules_generated: number
  module_from: number
  module_to: number
  total_slots: number
  unique_questions_used: number
  repeated_assignments: number
  eligible_pool_size: number
  coverage_pct: number
  per_section: SectionCoverage[]
  warnings: string[]
}

interface BlueprintOption {
  id: string
  name: string
  total_questions: number
  total_marks: number
  duration_minutes: number
}

interface UsageStat {
  medium: string
  tracked_questions: number
  total_assignments: number
  max_usage: number
  histogram: Record<string, number>
}

type Medium = 'english' | 'telugu'

export default function MockModuleGenerator() {
  const [medium, setMedium] = useState<Medium>('english')
  const [blueprintId, setBlueprintId] = useState('ap_dsc_sgt_official')
  const [blueprints, setBlueprints] = useState<BlueprintOption[]>([])
  const [series, setSeries] = useState('grand_mock_v1')
  const [moduleFrom, setModuleFrom] = useState(1)
  const [moduleTo, setModuleTo] = useState(100)

  const [running, setRunning] = useState<'dry' | 'write' | null>(null)
  const [report, setReport] = useState<GenerationReport | null>(null)
  const [wasDryRun, setWasDryRun] = useState(true)
  const [message, setMessage] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)

  const [publishedCounts, setPublishedCounts] = useState<Record<string, number>>({})
  const [usageStats, setUsageStats] = useState<UsageStat[]>([])

  // ---- Load blueprints + current state ----------------------------

  const loadContext = useCallback(async () => {
    try {
      const [listRes, reportsRes] = await Promise.all([
        fetch('/api/admin/mock-tests?pageSize=1'),
        fetch('/api/admin/mock-tests/reports?limit=1'),
      ])
      const listJson = await listRes.json()
      const reportsJson = await reportsRes.json()

      if (listJson.success && Array.isArray(listJson.blueprints)) {
        setBlueprints(listJson.blueprints)
      }
      if (reportsJson.success) {
        setPublishedCounts(reportsJson.published_module_counts ?? {})
        setUsageStats(reportsJson.usage_stats ?? [])
      }
    } catch {
      // Non-fatal — the panel still works without the summary.
    }
  }, [])

  useEffect(() => {
    void loadContext()
  }, [loadContext])

  // ---- Run generation --------------------------------------------

  const run = async (dryRun: boolean) => {
    setRunning(dryRun ? 'dry' : 'write')
    setError(null)
    setMessage(null)
    if (dryRun) setReport(null)

    try {
      const res = await fetch('/api/admin/mock-tests/generate-series', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          medium,
          blueprintId,
          series,
          moduleFrom,
          moduleTo,
          dryRun,
          publish: true,
        }),
      })
      const json = await res.json()

      if (!res.ok || !json.success) {
        setError(json.error || 'Generation failed')
        if (json.report) setReport(json.report)
        return
      }

      setReport(json.report ?? null)
      setWasDryRun(dryRun)

      if (dryRun) {
        setMessage(`Dry run complete — ${json.modules_planned} modules planned. Nothing was written.`)
      } else {
        setMessage(
          `Wrote ${json.modules_written} modules` +
            (json.modules_failed ? `, ${json.modules_failed} failed` : '') +
            `. Redis cache warmed at publish.`
        )
        void loadContext()
      }
    } catch {
      setError('Network error while generating modules')
    } finally {
      setRunning(null)
    }
  }

  const moduleCount = Math.max(0, moduleTo - moduleFrom + 1)
  const uniqueRate =
    report && report.total_slots > 0
      ? ((report.unique_questions_used / report.total_slots) * 100).toFixed(1)
      : null

  return (
    <div className="rounded-3xl border border-border bg-card p-5 shadow-sm sm:p-6">
      <div className="mb-5 flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <Layers className="h-5 w-5 text-primary" />
          <h2 className="text-base font-black text-foreground">Generate Mock Modules</h2>
        </div>
        <div className="flex items-center gap-3 text-[11px] text-muted-foreground">
          <span>
            Published — English:{' '}
            <strong className="text-foreground">{publishedCounts.english ?? 0}</strong>
          </span>
          <span>
            Telugu: <strong className="text-foreground">{publishedCounts.telugu ?? 0}</strong>
          </span>
          <button
            onClick={() => void loadContext()}
            className="inline-flex items-center gap-1 rounded-lg border border-border px-2 py-1 hover:bg-accent"
          >
            <RefreshCw className="h-3 w-3" /> Refresh
          </button>
        </div>
      </div>

      {/* ── Controls ── */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-5">
        <div>
          <label className="mb-1 block text-[11px] font-bold uppercase tracking-wide text-muted-foreground">
            Medium
          </label>
          <div className="flex gap-1 rounded-xl border border-border bg-muted/30 p-1">
            {(['english', 'telugu'] as Medium[]).map((m) => (
              <button
                key={m}
                onClick={() => setMedium(m)}
                className={`flex-1 rounded-lg px-2 py-1.5 text-[11px] font-bold capitalize transition ${
                  medium === m
                    ? 'bg-primary text-primary-foreground'
                    : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                {m}
              </button>
            ))}
          </div>
        </div>

        <div>
          <label className="mb-1 block text-[11px] font-bold uppercase tracking-wide text-muted-foreground">
            Blueprint
          </label>
          <select
            value={blueprintId}
            onChange={(e) => setBlueprintId(e.target.value)}
            className="h-9 w-full rounded-xl border border-border bg-card px-2 text-[11px] text-foreground focus:border-primary focus:outline-none"
          >
            {blueprints.length === 0 && <option value={blueprintId}>{blueprintId}</option>}
            {blueprints.map((b) => (
              <option key={b.id} value={b.id}>
                {b.name} ({b.total_questions}Q)
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className="mb-1 block text-[11px] font-bold uppercase tracking-wide text-muted-foreground">
            Series
          </label>
          <input
            value={series}
            onChange={(e) => setSeries(e.target.value)}
            className="h-9 w-full rounded-xl border border-border bg-card px-2 text-[11px] text-foreground focus:border-primary focus:outline-none"
          />
        </div>

        <div>
          <label className="mb-1 block text-[11px] font-bold uppercase tracking-wide text-muted-foreground">
            Module from
          </label>
          <input
            type="number"
            min={1}
            value={moduleFrom}
            onChange={(e) => setModuleFrom(Math.max(1, Number(e.target.value) || 1))}
            className="h-9 w-full rounded-xl border border-border bg-card px-2 text-[11px] text-foreground focus:border-primary focus:outline-none"
          />
        </div>

        <div>
          <label className="mb-1 block text-[11px] font-bold uppercase tracking-wide text-muted-foreground">
            Module to
          </label>
          <input
            type="number"
            min={1}
            value={moduleTo}
            onChange={(e) => setModuleTo(Math.max(1, Number(e.target.value) || 1))}
            className="h-9 w-full rounded-xl border border-border bg-card px-2 text-[11px] text-foreground focus:border-primary focus:outline-none"
          />
        </div>
      </div>

      {/* ── Actions ── */}
      <div className="mt-4 flex flex-wrap items-center gap-3">
        <button
          onClick={() => void run(true)}
          disabled={running !== null}
          className="inline-flex items-center gap-2 rounded-xl border border-border px-4 py-2 text-xs font-bold text-foreground hover:bg-accent disabled:opacity-50"
        >
          {running === 'dry' ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <BarChart3 className="h-3.5 w-3.5" />
          )}
          Dry Run &amp; Review ({moduleCount} modules)
        </button>

        <button
          onClick={() => void run(false)}
          disabled={running !== null}
          className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2 text-xs font-bold text-white hover:bg-primary disabled:opacity-50"
        >
          {running === 'write' ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <Rocket className="h-3.5 w-3.5" />
          )}
          Generate, Validate &amp; Publish
        </button>

        <span className="text-[11px] text-muted-foreground">
          A dry run writes nothing. Publishing validates each module and warms its Redis cache.
        </span>
      </div>

      {/* ── Messages ── */}
      {error && (
        <div className="mt-4 flex items-start gap-2 rounded-xl border border-destructive/40 bg-destructive/10 px-3 py-2 text-xs text-destructive">
          <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
          <span>{error}</span>
        </div>
      )}
      {message && (
        <div className="mt-4 flex items-start gap-2 rounded-xl border border-emerald-500/40 bg-emerald-500/10 px-3 py-2 text-xs text-emerald-700 dark:text-emerald-400">
          <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0" />
          <span>{message}</span>
        </div>
      )}

      {/* ── Coverage report ── */}
      {report && (
        <div className="mt-5 rounded-2xl border border-border bg-muted/20 p-4">
          <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
            <h3 className="text-xs font-black uppercase tracking-wide text-foreground">
              Coverage Report {wasDryRun && <span className="text-muted-foreground">(dry run)</span>}
            </h3>
            <span className="text-[11px] text-muted-foreground">
              {report.medium} · modules {report.module_from}–{report.module_to}
            </span>
          </div>

          <div className="grid grid-cols-2 gap-3 sm:grid-cols-5">
            {[
              { label: 'Modules', value: report.modules_generated },
              { label: 'Question slots', value: report.total_slots.toLocaleString() },
              { label: 'Unique questions', value: report.unique_questions_used.toLocaleString() },
              { label: 'Repeated assignments', value: report.repeated_assignments.toLocaleString() },
              { label: 'Slots filled uniquely', value: uniqueRate ? `${uniqueRate}%` : '—' },
            ].map((m) => (
              <div key={m.label} className="rounded-xl border border-border bg-card p-3 text-center">
                <p className="text-[11px] text-muted-foreground">{m.label}</p>
                <p className="text-sm font-black text-foreground">{m.value}</p>
              </div>
            ))}
          </div>

          <div className="mt-4 overflow-x-auto">
            <table className="w-full min-w-[640px] text-left text-[11px]">
              <thead>
                <tr className="text-muted-foreground">
                  <th className="py-1.5 pr-3 font-semibold">Section</th>
                  <th className="py-1.5 pr-3 text-right font-semibold">Q/mod</th>
                  <th className="py-1.5 pr-3 text-right font-semibold">Slots</th>
                  <th className="py-1.5 pr-3 text-right font-semibold">Pool</th>
                  <th className="py-1.5 pr-3 text-right font-semibold">Unique</th>
                  <th className="py-1.5 pr-3 text-right font-semibold">Repeats</th>
                  <th className="py-1.5 pr-3 text-right font-semibold">Pool cover</th>
                  <th className="py-1.5 text-right font-semibold">Max uses</th>
                </tr>
              </thead>
              <tbody>
                {report.per_section.map((s) => (
                  <tr key={s.section_id} className="border-t border-border/60">
                    <td className="py-1.5 pr-3 font-semibold text-foreground">{s.section_name}</td>
                    <td className="py-1.5 pr-3 text-right">{s.questions_per_module}</td>
                    <td className="py-1.5 pr-3 text-right">{s.slots}</td>
                    <td className="py-1.5 pr-3 text-right">{s.eligible_pool}</td>
                    <td className="py-1.5 pr-3 text-right font-bold text-emerald-600 dark:text-emerald-400">
                      {s.unique_used}
                    </td>
                    <td
                      className={`py-1.5 pr-3 text-right font-bold ${
                        s.repeated_assignments > 0 ? 'text-amber-600 dark:text-amber-400' : ''
                      }`}
                    >
                      {s.repeated_assignments}
                    </td>
                    <td className="py-1.5 pr-3 text-right">{s.coverage_pct}%</td>
                    <td className="py-1.5 text-right">{s.max_usage}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {report.warnings.length > 0 && (
            <details className="mt-4">
              <summary className="cursor-pointer text-[11px] font-bold text-amber-600 dark:text-amber-400">
                {[...new Set(report.warnings)].length} warning(s) — pools too small for full
                uniqueness
              </summary>
              <ul className="mt-2 space-y-1 text-[11px] text-muted-foreground">
                {[...new Set(report.warnings)].slice(0, 30).map((w, i) => (
                  <li key={i} className="flex gap-1.5">
                    <span className="text-amber-500">•</span>
                    <span>{w}</span>
                  </li>
                ))}
              </ul>
            </details>
          )}
        </div>
      )}

      {/* ── Live usage tracking ── */}
      {usageStats.length > 0 && (
        <div className="mt-5 grid gap-3 sm:grid-cols-2">
          {usageStats.map((u) => (
            <div key={u.medium} className="rounded-2xl border border-border bg-card p-3">
              <p className="mb-1 text-[11px] font-black uppercase tracking-wide text-foreground">
                {u.medium} — question usage
              </p>
              <p className="text-[11px] text-muted-foreground">
                {u.tracked_questions.toLocaleString()} questions tracked ·{' '}
                {u.total_assignments.toLocaleString()} assignments · max {u.max_usage} uses
              </p>
              <div className="mt-2 flex flex-wrap gap-1.5">
                {Object.entries(u.histogram)
                  .sort(([a], [b]) => a.localeCompare(b, undefined, { numeric: true }))
                  .map(([uses, count]) => (
                    <span
                      key={uses}
                      className="rounded-md border border-border bg-muted/40 px-1.5 py-0.5 text-[11px] text-muted-foreground"
                    >
                      {uses} use{uses === '1' ? '' : 's'}:{' '}
                      <strong className="text-foreground">{count}</strong>
                    </span>
                  ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

// ============================================================
// app/components/admin/QuestionEditor.tsx
// ============================================================
// Edits one question in place. The question bank is the single source of
// truth for both practice and mock tests, so saving here reaches both — see
// app/api/admin/questions/[uid]/route.ts for how the mock cache is cleared.
// ============================================================
'use client'

import React, { useCallback, useEffect, useState } from 'react'
import { Loader2, Save, RotateCcw, AlertTriangle } from 'lucide-react'
import { toast } from 'sonner'
import type { EditableQuestion } from '@/types/question-feedback'

const OPTIONS = ['A', 'B', 'C', 'D'] as const

interface QuestionEditorProps {
  questionUid: string
  /** Called after a successful save so the queue can refresh. */
  onSaved?: () => void
}

type Draft = Pick<
  EditableQuestion,
  | 'question'
  | 'option_a'
  | 'option_b'
  | 'option_c'
  | 'option_d'
  | 'correct_answer'
  | 'explanation'
  | 'difficulty'
  | 'topic'
>

function toDraft(q: EditableQuestion): Draft {
  return {
    question: q.question ?? '',
    option_a: q.option_a ?? '',
    option_b: q.option_b ?? '',
    option_c: q.option_c ?? '',
    option_d: q.option_d ?? '',
    correct_answer: (q.correct_answer ?? 'A').toUpperCase(),
    explanation: q.explanation ?? '',
    difficulty: q.difficulty ?? '',
    topic: q.topic ?? '',
  }
}

export default function QuestionEditor({ questionUid, onSaved }: QuestionEditorProps) {
  const [question, setQuestion] = useState<EditableQuestion | null>(null)
  const [modules, setModules] = useState<{ id: string; title: string; module_number: number | null }[]>([])
  const [draft, setDraft] = useState<Draft | null>(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const load = useCallback(async () => {
    try {
      const res = await fetch(`/api/admin/questions/${encodeURIComponent(questionUid)}`)
      const json = await res.json()
      if (!res.ok || !json.success) {
        setError(json.error ?? 'Could not load this question')
        setLoading(false)
        return
      }
      setQuestion(json.question)
      setDraft(toDraft(json.question))
      setModules(json.used_in_modules ?? [])
      setError(null)
      setLoading(false)
    } catch {
      setError('Network error — please try again')
      setLoading(false)
    }
  }, [questionUid])

  useEffect(() => {
    void load()
  }, [load])

  const set = <K extends keyof Draft>(key: K, value: Draft[K]) =>
    setDraft((d) => (d ? { ...d, [key]: value } : d))

  const dirty =
    question != null && draft != null && JSON.stringify(draft) !== JSON.stringify(toDraft(question))

  const save = async () => {
    if (!draft || !dirty) return
    setSaving(true)
    try {
      const res = await fetch(`/api/admin/questions/${encodeURIComponent(questionUid)}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(draft),
      })
      const json = await res.json()

      if (!res.ok || !json.success) {
        toast.error('Could not save', { description: json.error })
        return
      }

      setQuestion(json.question)
      setDraft(toDraft(json.question))
      toast.success('Question updated', {
        description:
          json.invalidated_modules > 0
            ? `Live in practice, and refreshed in ${json.invalidated_modules} mock module${json.invalidated_modules === 1 ? '' : 's'}.`
            : 'Live in practice. Not used by any mock module yet.',
      })
      onSaved?.()
    } catch {
      toast.error('Network error — please try again')
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-8 text-xs text-muted-foreground">
        <Loader2 className="h-4 w-4 animate-spin text-primary" />
        Loading question…
      </div>
    )
  }

  if (error || !draft || !question) {
    return (
      <div className="flex items-start gap-2 rounded-xl border border-destructive/30 bg-destructive/5 p-3 text-xs text-destructive">
        <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0" />
        <span>{error ?? 'Question unavailable'}</span>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {/* Where this question is in use */}
      <div className="flex flex-wrap items-center gap-2 text-[11px] text-muted-foreground">
        <code className="rounded bg-muted px-1.5 py-0.5">{question.question_uid}</code>
        {question.subject && <span>· {question.subject}</span>}
        <span>
          · Used in {modules.length} mock module{modules.length === 1 ? '' : 's'}
        </span>
      </div>

      {/* Question text */}
      <label className="block">
        <span className="text-[11px] font-semibold text-foreground">Question</span>
        <textarea
          value={draft.question}
          onChange={(e) => set('question', e.target.value)}
          rows={3}
          className="mt-1 w-full resize-y rounded-xl border border-border bg-background px-3 py-2 text-xs text-foreground focus:border-ring/60 focus:outline-none focus:ring-2 focus:ring-ring/15"
        />
      </label>

      {/* Options + answer key */}
      <div className="space-y-2">
        <span className="text-[11px] font-semibold text-foreground">
          Options — select the correct one
        </span>
        {OPTIONS.map((letter) => {
          const key = `option_${letter.toLowerCase()}` as keyof Draft
          const isCorrect = draft.correct_answer === letter
          return (
            <div key={letter} className="flex items-start gap-2">
              <button
                type="button"
                onClick={() => set('correct_answer', letter)}
                aria-pressed={isCorrect}
                title={`Mark ${letter} correct`}
                className={`mt-1 flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-[11px] font-bold transition ${
                  isCorrect
                    ? 'bg-emerald-600 text-white'
                    : 'bg-muted text-muted-foreground hover:bg-accent'
                }`}
              >
                {letter}
              </button>
              <textarea
                value={String(draft[key] ?? '')}
                onChange={(e) => set(key, e.target.value as Draft[typeof key])}
                rows={1}
                className="w-full resize-y rounded-xl border border-border bg-background px-3 py-1.5 text-xs text-foreground focus:border-ring/60 focus:outline-none focus:ring-2 focus:ring-ring/15"
              />
            </div>
          )
        })}
      </div>

      {/* Explanation */}
      <label className="block">
        <span className="text-[11px] font-semibold text-foreground">Explanation</span>
        <textarea
          value={draft.explanation ?? ''}
          onChange={(e) => set('explanation', e.target.value)}
          rows={2}
          className="mt-1 w-full resize-y rounded-xl border border-border bg-background px-3 py-2 text-xs text-foreground focus:border-ring/60 focus:outline-none focus:ring-2 focus:ring-ring/15"
        />
      </label>

      <div className="grid gap-3 sm:grid-cols-2">
        <label className="block">
          <span className="text-[11px] font-semibold text-foreground">Topic</span>
          <input
            value={draft.topic ?? ''}
            onChange={(e) => set('topic', e.target.value)}
            className="mt-1 h-9 w-full rounded-xl border border-border bg-background px-3 text-xs text-foreground focus:border-ring/60 focus:outline-none focus:ring-2 focus:ring-ring/15"
          />
        </label>
        <label className="block">
          <span className="text-[11px] font-semibold text-foreground">Difficulty</span>
          <input
            value={draft.difficulty ?? ''}
            onChange={(e) => set('difficulty', e.target.value)}
            className="mt-1 h-9 w-full rounded-xl border border-border bg-background px-3 text-xs text-foreground focus:border-ring/60 focus:outline-none focus:ring-2 focus:ring-ring/15"
          />
        </label>
      </div>

      <div className="flex items-center justify-end gap-2 border-t border-border pt-3">
        {dirty && (
          <button
            type="button"
            onClick={() => setDraft(toDraft(question))}
            className="inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 text-[11px] font-medium text-muted-foreground hover:text-foreground"
          >
            <RotateCcw className="h-3 w-3" />
            Discard
          </button>
        )}
        <button
          type="button"
          onClick={() => void save()}
          disabled={!dirty || saving}
          className="bloom-pill bloom-pill-dark px-4 py-2 text-[11px] disabled:cursor-not-allowed disabled:opacity-45"
        >
          {saving ? <Loader2 className="h-3 w-3 animate-spin" /> : <Save className="h-3 w-3" />}
          <span>{saving ? 'Saving…' : 'Save question'}</span>
        </button>
      </div>
    </div>
  )
}

