// ============================================================
// app/components/dsc-sgt/practice/PracticeExam.tsx
// ============================================================
// Mobile-Optimized, High-Clarity DSC Exam & Practice Orchestrator
// ============================================================

import React, { useState, useEffect } from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { useHideBottomNav } from '@/app/components/dsc-sgt/DscBottomNav'
import type { PracticeSession, UserAnswerRecord } from '@/types/practice'
import {
  ExamHeader,
  ExamProgressBar,
  QuestionCard,
  OptionList,
  ExplanationCard,
  QuestionMatrixNavigator,
  ExamBottomNav,
  SubmitModal,
  ExitModal,
} from './exam'

interface PracticeExamProps {
  session: PracticeSession
  isPremium?: boolean
  onAnswerQuestion: (
    questionId: string,
    selectedAnswer: 'A' | 'B' | 'C' | 'D' | null,
    timeTakenSeconds: number,
    markedForReview: boolean
  ) => Promise<{ is_correct: boolean; correct_answer: string; explanation: string | null } | void>
  onSubmitSession: (totalTimeSeconds: number) => void
  onExitSession: (elapsedSeconds?: number) => void
  isSubmitting?: boolean
}

export default function PracticeExam({
  session,
  isPremium = false,
  onAnswerQuestion,
  onSubmitSession,
  onExitSession,
  isSubmitting = false,
}: PracticeExamProps) {
  // A running session owns the bottom of the screen — it has its own next/
  // previous bar. Stacking the app's tab bar under that buries the controls
  // and offers an exit that skips the session's own handling.
  useHideBottomNav()

  const [currentIndex, setCurrentIndex] = useState<number>(0)
  const [userAnswers, setUserAnswers] = useState<Record<string, UserAnswerRecord>>(
    session.user_answers || {}
  )
  const [markedIds, setMarkedIds] = useState<Set<string>>(new Set())
  const [elapsedSeconds, setElapsedSeconds] = useState<number>(session.time_spent_seconds || 0)
  const [questionStartTime, setQuestionStartTime] = useState<number>(Date.now())
  const [showSubmitModal, setShowSubmitModal] = useState<boolean>(false)
  const [showExitModal, setShowExitModal] = useState<boolean>(false)
  const [showMobileNavigator, setShowMobileNavigator] = useState<boolean>(false)

  // Local instant feedback data map
  const [instantFeedbackData, setInstantFeedbackData] = useState<
    Record<string, { is_correct: boolean; correct_answer: string; explanation: string | null }>
  >({})

  const isInstant = session.feedback_mode === 'instant'
  const questions = session.questions || []
  const currentQ = questions[currentIndex] || questions[0]
  const currentQId = currentQ?.question_id || currentQ?.id || `q-${currentIndex}`

  // ── Live Stopwatch / Timer ──────────────────────────────────
  useEffect(() => {
    const interval = setInterval(() => {
      setElapsedSeconds((prev) => prev + 1)
    }, 1000)
    return () => clearInterval(interval)
  }, [])

  // Reset per-question stopwatch
  useEffect(() => {
    setQuestionStartTime(Date.now())
  }, [currentIndex])

  // ── Handle Option Click ─────────────────────────────────────
  const handleSelectOption = async (optKey: 'A' | 'B' | 'C' | 'D') => {
    if (!currentQ) return

    const timeSpent = Math.max(1, Math.round((Date.now() - questionStartTime) / 1000))
    const isMarked = markedIds.has(currentQId)

    // In Instant Feedback mode, once answered, lock option
    if (isInstant && userAnswers[currentQId]?.selected_answer) {
      return
    }

    const updatedRecord: UserAnswerRecord = {
      question_id: currentQId,
      selected_answer: optKey,
      time_taken_seconds: timeSpent,
      marked_for_review: isMarked,
    }

    setUserAnswers((prev) => ({
      ...prev,
      [currentQId]: updatedRecord,
    }))

    // Server-side validation
    const res = await onAnswerQuestion(currentQId, optKey, timeSpent, isMarked)
    if (res) {
      setInstantFeedbackData((prev) => ({
        ...prev,
        [currentQId]: res,
      }))
    }
  }

  // ── Toggle Flag / Mark For Review ───────────────────────────
  const toggleMarkForReview = () => {
    setMarkedIds((prev) => {
      const next = new Set(prev)
      if (next.has(currentQId)) next.delete(currentQId)
      else next.add(currentQId)
      return next
    })
  }

  const totalQuestions = questions.length
  const answeredCount = Object.values(userAnswers).filter((a) => a.selected_answer).length
  const progressPct = totalQuestions > 0 ? Math.round(((currentIndex + 1) / totalQuestions) * 100) : 0

  const currentAnswer = userAnswers[currentQId]?.selected_answer
  const currentFeedback = instantFeedbackData[currentQId] || (
    currentQ.correct_answer ? {
      is_correct: (currentQ.correct_answer || '').toUpperCase() === currentAnswer,
      correct_answer: currentQ.correct_answer,
      explanation: currentQ.explanation || null,
    } : null
  )

  return (
    <div className="space-y-4 sm:space-y-6 max-w-5xl mx-auto pb-24 sm:pb-8">
      {/* ── Top Header Navigation Bar ─────────────────────────── */}
      <ExamHeader
        subject={session.subject}
        medium={session.medium}
        currentIndex={currentIndex}
        totalQuestions={totalQuestions}
        elapsedSeconds={elapsedSeconds}
        onShowExitModal={() => setShowExitModal(true)}
        onShowSubmitModal={() => setShowSubmitModal(true)}
      />

      {/* Progress Bar */}
      <ExamProgressBar progressPct={progressPct} />

      {/* ── Main Layout (Question Card + Desktop Navigator) ──── */}
      <div className="grid gap-6 lg:grid-cols-4">
        {/* Left: Question Solver Card */}
        <div className="lg:col-span-3 flex flex-col justify-between rounded-3xl border border-border/80 bg-card p-5 sm:p-7 shadow-xs">
          <div>
            <QuestionCard
              currentQ={currentQ}
              currentIndex={currentIndex}
              isMarked={markedIds.has(currentQId)}
              onToggleMarkForReview={toggleMarkForReview}
            />

            <OptionList
              currentQ={currentQ}
              currentAnswer={currentAnswer}
              isInstant={isInstant}
              currentFeedback={currentFeedback}
              onSelectOption={handleSelectOption}
            />

            <ExplanationCard
              isInstant={isInstant}
              currentAnswer={currentAnswer}
              currentFeedback={currentFeedback}
            />
          </div>

          {/* Desktop/Tablet Bottom Control Bar */}
          <div className="hidden sm:flex items-center justify-between border-t border-border/60 pt-5 mt-6">
            <button
              type="button"
              onClick={() => setCurrentIndex((i) => Math.max(0, i - 1))}
              disabled={currentIndex === 0}
              className="inline-flex items-center gap-1 rounded-xl border border-border bg-card px-4 py-2 text-xs font-bold text-foreground hover:bg-accent disabled:opacity-30 cursor-pointer"
            >
              <ChevronLeft className="h-4 w-4" /> Previous
            </button>

            <span className="text-xs text-muted-foreground font-semibold">
              Question {currentIndex + 1} of {totalQuestions}
            </span>

            <button
              type="button"
              onClick={() => {
                if (currentIndex < totalQuestions - 1) {
                  setCurrentIndex((i) => i + 1)
                } else {
                  setShowSubmitModal(true)
                }
              }}
              className="inline-flex items-center gap-1 rounded-xl bg-primary px-5 py-2 text-xs font-bold text-primary-foreground hover:bg-primary/90 cursor-pointer shadow-xs"
            >
              <span>{currentIndex === totalQuestions - 1 ? 'Finish Practice' : 'Next'}</span>
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>
        </div>

        {/* Right: Question Matrix Navigator (Desktop) */}
        <QuestionMatrixNavigator
          questions={questions}
          currentIndex={currentIndex}
          userAnswers={userAnswers}
          markedIds={markedIds}
          onSelectIndex={setCurrentIndex}
        />
      </div>

      {/* ── Fixed Mobile Bottom Navigation Bar ────────────────── */}
      <ExamBottomNav
        currentIndex={currentIndex}
        totalQuestions={totalQuestions}
        onPrev={() => setCurrentIndex((i) => Math.max(0, i - 1))}
        onNext={() => {
          if (currentIndex < totalQuestions - 1) {
            setCurrentIndex((i) => i + 1)
          } else {
            setShowSubmitModal(true)
          }
        }}
        onOpenMobileNavigator={() => setShowMobileNavigator(true)}
      />

      {/* ── Mobile Question Navigator Bottom Sheet ────────────── */}
      {showMobileNavigator && (
        <QuestionMatrixNavigator
          questions={questions}
          currentIndex={currentIndex}
          userAnswers={userAnswers}
          markedIds={markedIds}
          isMobileModal={true}
          onSelectIndex={setCurrentIndex}
          onCloseMobileModal={() => setShowMobileNavigator(false)}
        />
      )}

      {/* ── Submit Modal ──────────────────────────────────────── */}
      <SubmitModal
        show={showSubmitModal}
        answeredCount={answeredCount}
        totalQuestions={totalQuestions}
        isSubmitting={isSubmitting}
        onClose={() => setShowSubmitModal(false)}
        onConfirm={() => {
          setShowSubmitModal(false)
          onSubmitSession(elapsedSeconds)
        }}
      />

      {/* ── Abandon / Exit Modal ──────────────────────────────── */}
      <ExitModal
        show={showExitModal}
        isPremium={isPremium}
        onClose={() => setShowExitModal(false)}
        onConfirm={() => {
          setShowExitModal(false)
          onExitSession(elapsedSeconds)
        }}
      />
    </div>
  )
}

'use client'

// ============================================================
// app/components/dsc-sgt/practice/PracticeSetup.tsx
// ============================================================
// Ultra-Friendly, Mobile-First DSC Practice Setup Orchestrator
// Modularly composed with specialized subcomponents.
// ============================================================

import React, { useState, useEffect, useCallback } from 'react'
import { GraduationCap, History, Crown, Lock, Sparkles } from 'lucide-react'
import { useAuth } from '@/app/contexts/AuthContext'
import { usePremium } from '@/app/components/dsc-sgt/PremiumContext'
import { resolvePreferredMedium, storeMedium } from '@/lib/medium-preference'
import type {
  PracticeMedium,
  PracticeMode,
  PracticeFilterState,
  DynamicFilterOptions,
  WeakAreaRecommendation,
} from '@/types/practice'
import {
  MediumSelector,
  SubjectSelector,
  TopicSelector,
  QuestionCountSelector,
  PracticeModeSelector,
  AdvancedFilters,
  WeakAreaBanner,
  SetupBottomBar,
} from './setup'

interface PracticeSetupProps {
  onStartSession: (filter: PracticeFilterState) => void
  onQuickRetry: (topic?: string, subject?: string) => void
  onViewHistory: () => void
  isLoading?: boolean
}

export default function PracticeSetup({
  onStartSession,
  onQuickRetry,
  onViewHistory,
  isLoading = false,
}: PracticeSetupProps) {
  const { user } = useAuth()
  const { isPremium, openModal } = usePremium()

  // ── Practice Quota State ────────────────────────────────────
  const [quota, setQuota] = useState<{
    loading: boolean
    canPractice: boolean
    completedSessions: number
    allowedSessions: number | string
    maxQuestions: number
    reason: string | null
  }>({
    loading: true,
    canPractice: true,
    completedSessions: 0,
    allowedSessions: 1,
    maxQuestions: 25,
    reason: null,
  })

  const fetchQuota = useCallback(async () => {
    try {
      const res = await fetch('/api/dsc-sgt/practice/quota')
      const data = await res.json()
      if (data.success) {
        setQuota({
          loading: false,
          canPractice: data.canPractice,
          completedSessions: data.completedSessions,
          allowedSessions: data.allowedSessions,
          maxQuestions: data.maxQuestions,
          reason: data.reason,
        })
      }
    } catch {
      setQuota((prev) => ({ ...prev, loading: false }))
    }
  }, [])

  useEffect(() => {
    fetchQuota()
  }, [fetchQuota])

  // ── Core State ──────────────────────────────────────────────
  const [medium, setMedium] = useState<PracticeMedium>('english')
  const [subject, setSubject] = useState<string>('English')
  const [hasUserSelectedMedium, setHasUserSelectedMedium] = useState<boolean>(false)
  const [topicMode, setTopicMode] = useState<'all' | 'custom'>('all')
  const [selectedTopics, setSelectedTopics] = useState<string[]>([])
  const [selectedSubtopics, setSelectedSubtopics] = useState<string[]>([])
  const [questionCount, setQuestionCount] = useState<number>(25)
  const [practiceMode, setPracticeMode] = useState<PracticeMode>('balanced')
  const [instantFeedback, setInstantFeedback] = useState<boolean>(true)

  // ── Advanced Optional Filters ───────────────────────────────
  const [showAdvanced, setShowAdvanced] = useState<boolean>(false)
  const [selectedClasses, setSelectedClasses] = useState<string[]>(['All'])
  const [selectedDifficulties, setSelectedDifficulties] = useState<string[]>(['All'])
  const [hasTimer, setHasTimer] = useState<boolean>(false)
  const [timerMinutes, setTimerMinutes] = useState<number>(25)

  // ── Dynamic Metadata from Server ────────────────────────────
  const [dynamicOptions, setDynamicOptions] = useState<DynamicFilterOptions | null>(null)
  const [weakRecommendations, setWeakRecommendations] = useState<WeakAreaRecommendation[]>([])

  // Fetch dynamic filters from backend
  const fetchFilterMetadata = useCallback(async () => {
    try {
      const params = new URLSearchParams({
        medium,
        subject,
      })
      if (topicMode === 'custom' && selectedTopics.length > 0) {
        params.set('topics', selectedTopics.join(','))
      }
      if (!selectedClasses.includes('All') && selectedClasses.length > 0) {
        params.set('class_levels', selectedClasses.join(','))
      }
      if (!selectedDifficulties.includes('All') && selectedDifficulties.length > 0) {
        params.set('difficulty', selectedDifficulties.join(','))
      }

      const res = await fetch(`/api/dsc-sgt/practice/filters?${params.toString()}`)
      const json = await res.json()
      if (json.success && json.data) {
        setDynamicOptions(json.data)
      }
    } catch (err) {
      console.error('Failed to fetch dynamic filters:', err)
    }
  }, [medium, subject, topicMode, selectedTopics, selectedClasses, selectedDifficulties])

  // Fetch weak recommendations on mount
  useEffect(() => {
    fetch('/api/dsc-sgt/practice/weak-topics')
      .then((res) => res.json())
      .then((data) => {
        if (data.success && data.recommendations) {
          setWeakRecommendations(data.recommendations)
        }
      })
      .catch(() => {})
  }, [])

  useEffect(() => {
    fetchFilterMetadata()
  }, [fetchFilterMetadata])

  // ── Automatically open collected Medium Tab (from user profile or localStorage) ──
  useEffect(() => {
    if (hasUserSelectedMedium) return

    // Profile first, then the last manual switch — the same order the mock
    // tests tabs use. See lib/medium-preference.ts.
    const targetMedium = resolvePreferredMedium(user?.educationMedium)

    if (targetMedium && targetMedium !== medium) {
      setMedium(targetMedium)
      setSubject(targetMedium === 'english' ? 'English' : 'Telugu')
      setSelectedTopics([])
      setTopicMode('all')
    }
  }, [user?.educationMedium, hasUserSelectedMedium, medium])

  const handleSelectMedium = (m: PracticeMedium) => {
    setHasUserSelectedMedium(true)
    setMedium(m)
    setSubject(m === 'english' ? 'English' : 'Telugu')
    setSelectedTopics([])
    setTopicMode('all')
    storeMedium(m)
  }

  // Ensure free users stay in All Topics mode
  useEffect(() => {
    if (!isPremium && topicMode === 'custom') {
      setTopicMode('all')
      setSelectedTopics([])
    }
  }, [isPremium, topicMode])

  // Toggle specific topic
  const toggleTopic = (topicName: string) => {
    if (!isPremium) {
      openModal('practice_topic_selection')
      return
    }
    setSelectedTopics((prev) => {
      if (prev.includes(topicName)) {
        const next = prev.filter((t) => t !== topicName)
        if (next.length === 0) setTopicMode('all')
        return next
      } else {
        return [...prev, topicName]
      }
    })
  }

  // Matching questions available
  const totalAvailable = dynamicOptions?.total_matching_questions ?? 25
  const rawQuestionCount = Math.min(
    questionCount,
    totalAvailable > 0 ? totalAvailable : questionCount
  )
  const finalQuestionCount = !isPremium ? Math.min(25, rawQuestionCount) : rawQuestionCount

  // Start practice handler
  const handleStart = () => {
    if (!quota.canPractice && !isPremium) {
      openModal('practice_limit_start_blocked')
      return
    }

    if (!isPremium && topicMode === 'custom') {
      openModal('practice_topic_selection')
      return
    }

    const filterState: PracticeFilterState = {
      medium,
      subject,
      class_levels: selectedClasses,
      topics: !isPremium || topicMode === 'all' || selectedTopics.length === 0 ? ['All'] : selectedTopics,
      subtopics: selectedSubtopics.length > 0 ? selectedSubtopics : ['All'],
      difficulty: selectedDifficulties,
      question_count: Math.max(5, finalQuestionCount),
      mode: practiceMode,
      feedback_mode: instantFeedback ? 'instant' : 'end',
      has_timer: hasTimer,
      duration_minutes: hasTimer ? timerMinutes : 0,
    }
    onStartSession(filterState)
  }


  return (
