'use client'

// ============================================================
// app/contexts/AuthContext.tsx — Auth state management
// ============================================================

import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
} from 'react'
import type { PublicUser, LearningGoal, EducationMedium } from '@/lib/auth/types'
import { clearActiveExam } from '@/lib/active-exam'

// ---- Context types ---------------------------------------------

interface AuthState {
  user: PublicUser | null
  loading: boolean
}

interface AuthContextValue extends AuthState {
  refreshUser: () => Promise<void>
  /** Replace the cached user with a fresh copy returned by a server call (no refetch). */
  updateUser: (user: PublicUser) => void
  logout: () => Promise<void>
  logoutAll: () => Promise<void>
  completeOnboarding: (data: {
    learningGoals: LearningGoal[]
    educationMedium: EducationMedium
  }) => Promise<boolean>
}

// ---- Context ---------------------------------------------------

const AuthContext = createContext<AuthContextValue | null>(null)

// ---- Provider --------------------------------------------------

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<PublicUser | null>(null)
  const [loading, setLoading] = useState(true)
  const handlingRevocation = useRef(false)

  /**
   * Handle session revocation: clear state and redirect to login.
   * Only redirects if we are on a protected page. NEVER reloads if already at '/'.
   */
  const handleRevocation = useCallback(() => {
    if (handlingRevocation.current) return
    handlingRevocation.current = true
    clearActiveExam()
    setUser(null)
    setLoading(false)

    // Only redirect if NOT already on root landing page
    if (typeof window !== 'undefined' && window.location.pathname !== '/') {
      setTimeout(() => {
        window.location.href = '/'
      }, 50)
    }
  }, [])

  /**
   * Fetch the current user from the backend.
   * Returns null (no redirect) if not authenticated.
   */
  const fetchUser = useCallback(async (): Promise<void> => {
    try {
      const res = await fetch('/api/auth/me', { credentials: 'include' })

      if (res.ok) {
        const data = await res.json()
        setUser(data)
        handlingRevocation.current = false
        return
      }

      if (res.status === 401) {
        const data = await res.json().catch(() => ({}))
        if (
          data.error === 'SESSION_REVOKED' ||
          data.error === 'SESSION_EXPIRED' ||
          data.error === 'REFRESH_TOKEN_REUSE_DETECTED'
        ) {
          handleRevocation()
          return
        }
        // UNAUTHORIZED = simply not logged in
        setUser(null)
        return
      }

      setUser(null)
    } catch {
      // Network error — don't clear user state, it might be transient
    } finally {
      setLoading(false)
    }
  }, [handleRevocation])

  // Load user on mount
  useEffect(() => {
    fetchUser()
  }, [fetchUser])

  // ---- Auth actions ------------------------------------------

  const logout = useCallback(async () => {
    try {
      await fetch('/api/auth/logout', { method: 'POST', credentials: 'include' })
    } finally {
      clearActiveExam()
      setUser(null)
      if (typeof window !== 'undefined' && window.location.pathname !== '/') {
        window.location.href = '/'
      }
    }
  }, [])

  const logoutAll = useCallback(async () => {
    try {
      await fetch('/api/auth/logout-all', { method: 'POST', credentials: 'include' })
    } finally {
      clearActiveExam()
      setUser(null)
      if (typeof window !== 'undefined' && window.location.pathname !== '/') {
        window.location.href = '/'
      }
    }
  }, [])

  const refreshUser = useCallback(async () => {
    setLoading(true)
    await fetchUser()
  }, [fetchUser])

  const updateUser = useCallback((next: PublicUser) => {
    setUser(next)
  }, [])

  /**
   * Submit onboarding data and update user state.
   * Returns true on success, false on failure.
   */
  const completeOnboarding = useCallback(async (data: {
    learningGoals: LearningGoal[]
    educationMedium: EducationMedium
  }): Promise<boolean> => {
    try {
      const res = await fetch('/api/auth/onboarding', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(data),
      })

      if (res.ok) {
        const result = await res.json()
        if (result.user) {
          setUser(result.user)
        }
        return true
      }

      return false
    } catch {
      return false
    }
  }, [])

  return (
    <AuthContext.Provider value={{ user, loading, refreshUser, updateUser, logout, logoutAll, completeOnboarding }}>
      {children}
    </AuthContext.Provider>
  )
}

// ---- Hook ------------------------------------------------------

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext)
  if (!ctx) {
    throw new Error('useAuth() must be used inside <AuthProvider>')
  }
  return ctx
}

'use client'

import React, { useState, useEffect, useCallback, useRef, Suspense, useSyncExternalStore } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import {
  ArrowLeft,
  PauseCircle,
  Play,
  Maximize,
  Minimize,
  Timer,
  CheckCircle2,
  Bookmark,
  ChevronLeft,
  ChevronRight,
  Send,
  RotateCcw,
  AlertCircle,
  Loader2,
  HelpCircle,
  X,
  RefreshCw,
} from 'lucide-react'
import { toast } from 'sonner'
import QuestionFeedbackButton from '@/app/components/dsc-sgt/QuestionFeedbackButton'
import type { ClientSafeMockQuestion, SelectedOption } from '@/types/mock-tests'

// ── Constants ─────────────────────────────────────────────────────

// Autosave answer every N seconds after change
const AUTOSAVE_DEBOUNCE_MS = 1500

// Questions are delivered in chunks: the first chunk renders immediately and
// the rest stream in behind it, so the candidate can start on Q1 without
// waiting for all 160. Each chunk is ONE request served from a single Redis
// read — never one request per question.
const QUESTIONS_CHUNK_SIZE = 50

// ── Timer Component ──────────────────────────────────────────────

function CountdownTimer({
  totalSeconds,
  timeSpentSeconds,
  onExpire,
}: {
  totalSeconds: number
  timeSpentSeconds: number
  onExpire: () => void
}) {
  const [remaining, setRemaining] = useState(totalSeconds - timeSpentSeconds)
  const hasExpiredRef = useRef(false)

  useEffect(() => {
    if (remaining <= 0 && !hasExpiredRef.current) {
      hasExpiredRef.current = true
      onExpire()
      return
    }
    const interval = setInterval(() => {
      setRemaining((r) => {
        if (r <= 1) {
          clearInterval(interval)
          if (!hasExpiredRef.current) {
            hasExpiredRef.current = true
            onExpire()
          }
          return 0
        }
        return r - 1
      })
    }, 1000)
    return () => clearInterval(interval)
  }, [])

  const hours = Math.floor(remaining / 3600)
  const mins = Math.floor((remaining % 3600) / 60)
  const secs = remaining % 60
  const timeStr = `${hours.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`

  const isUrgent = remaining < 600  // < 10 minutes

  return (
    <div
      className={`inline-flex items-center gap-2 rounded-xl border px-3 py-1.5 text-xs font-mono font-bold tabular-nums ${
        isUrgent
          ? 'border-red-500/40 bg-red-500/10 text-red-500 animate-pulse'
          : 'border-border bg-muted/40 text-foreground'
      }`}
    >
      <Timer className="h-3.5 w-3.5 shrink-0" />
      {timeStr}
    </div>
  )
}

// ── Section Navigator ─────────────────────────────────────────────

interface SectionNav {
  id: string
  name: string
  start: number  // question_number start (1-indexed)
  count: number
}

function buildSectionNav(questions: ClientSafeMockQuestion[]): SectionNav[] {
  const sections: SectionNav[] = []
  const seen = new Map<string, SectionNav>()
  for (const q of [...questions].sort((a, b) => a.question_number - b.question_number)) {
    if (!seen.has(q.section_id)) {
      const nav: SectionNav = { id: q.section_id, name: q.section_name, start: q.question_number, count: 0 }
      seen.set(q.section_id, nav)
      sections.push(nav)
    }
    seen.get(q.section_id)!.count++
  }
  return sections
}

