// ── First-run hint for the question palette ───────────────────────
// On a phone the palette lives behind one small button, and nothing about a
// number in a box says "all 160 questions are in here". Desktop needs none of
// this — the palette is a permanent sidebar from sm up.
//
// Read through useSyncExternalStore rather than an effect so the server
// renders the "already seen" answer and the client renders the real one, with
// no hydration mismatch and no flash of a hint that is about to disappear.

const PALETTE_HINT_KEY = 'mock_exam_palette_hint_seen'
const hintListeners = new Set<() => void>()

function subscribeHint(onChange: () => void): () => void {
  hintListeners.add(onChange)
  window.addEventListener('storage', onChange)
  return () => {
    hintListeners.delete(onChange)
    window.removeEventListener('storage', onChange)
  }
}

function hintSnapshot(): string {
  try {
    return window.localStorage.getItem(PALETTE_HINT_KEY) ?? ''
  } catch {
    // Storage blocked — treat it as seen rather than showing the hint every
    // single time the exam is opened.
    return 'seen'
  }
}

function dismissHint(): void {
  try {
    window.localStorage.setItem(PALETTE_HINT_KEY, 'seen')
  } catch {
    // Nothing to do; the hint simply reappears next time.
  }
  for (const listener of hintListeners) listener()
}

// ── Question Grid ─────────────────────────────────────────────────

function QuestionGrid({
  questions,
  currentQNumber,
  answers,
  visited,
  marked,
  onJump,
}: {
  questions: ClientSafeMockQuestion[]
  currentQNumber: number
  answers: Record<string, SelectedOption>
  visited: Set<number>
  marked: Set<number>
  onJump: (qNumber: number) => void
}) {
  const sorted = [...questions].sort((a, b) => a.question_number - b.question_number)
  const sections = buildSectionNav(sorted)

  // A wall of 160 numbered tiles is not something anyone reads mid-exam. The
  // real questions are "what have I not done yet" and "what did I flag", so
  // those are one tap, and the full grid stays for the rare jump to a number.
  const [filter, setFilter] = useState<'all' | 'unanswered' | 'marked' | 'answered'>('all')

  const counts = {
    all: sorted.length,
    unanswered: sorted.filter((q) => !answers[q.question_uid]).length,
    marked: sorted.filter((q) => marked.has(q.question_number)).length,
    answered: sorted.filter((q) => answers[q.question_uid]).length,
  }

  const matchesFilter = (q: ClientSafeMockQuestion) => {
    if (filter === 'unanswered') return !answers[q.question_uid]
    if (filter === 'answered') return Boolean(answers[q.question_uid])
    if (filter === 'marked') return marked.has(q.question_number)
    return true
  }

  const FILTERS = [
    { id: 'all' as const, label: 'All' },
    { id: 'unanswered' as const, label: 'Not done' },
    { id: 'marked' as const, label: 'Flagged' },
    { id: 'answered' as const, label: 'Done' },
  ]

  return (
    <div className="flex flex-col gap-4">
      {/* Filters */}
      <div className="flex flex-wrap gap-1.5">
        {FILTERS.map((f) => (
          <button
            key={f.id}
            onClick={() => setFilter(f.id)}
            aria-pressed={filter === f.id}
            className={`rounded-full border px-3 py-1.5 text-[11px] font-semibold transition ${
              filter === f.id
                ? 'border-primary bg-primary text-primary-foreground'
                : 'border-border text-muted-foreground hover:text-foreground'
            }`}
          >
            {f.label} {counts[f.id]}
          </button>
        ))}
      </div>

      {/* Questions grouped by section */}
      {sections.map((section) => {
        const sectionQs = sorted.filter((q) => q.section_id === section.id && matchesFilter(q))
        if (sectionQs.length === 0) return null
        return (
          <div key={section.id}>
            <p className="mb-1.5 text-[11px] font-bold text-muted-foreground uppercase tracking-wide truncate">
              {section.name} ({sectionQs.length})
            </p>
            <div className="flex flex-wrap gap-1.5">
              {sectionQs.map((q) => {
                const isCurrent = q.question_number === currentQNumber
                const hasAnswer = !!answers[q.question_uid]
                const isMarked = marked.has(q.question_number)
                const isVisited = visited.has(q.question_number)

                let cls = 'bg-muted/60 border border-border text-muted-foreground'
                if (isCurrent) cls = 'bg-primary text-primary-foreground shadow-md scale-110'
                else if (isMarked && hasAnswer) cls = 'bg-amber-500 text-white'
                else if (isMarked) cls = 'bg-amber-500/70 text-white'
                else if (hasAnswer) cls = 'bg-emerald-600 text-white'
                else if (isVisited) cls = 'bg-muted-foreground/30 text-foreground'

                return (
                  <button
                    key={q.question_number}
                    onClick={() => onJump(q.question_number)}
                    className={`h-7 w-7 rounded-md text-[11px] font-bold transition-all ${cls}`}
                    title={`Q${q.question_number}`}
                  >
                    {q.question_number}
                  </button>
                )
              })}
            </div>
          </div>
        )
      })}
    </div>
  )
}

// ── Main Exam Component ───────────────────────────────────────────

function MockExamContent() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const testId = searchParams.get('testId')
  const attemptId = searchParams.get('attemptId')

  // ── State ─────────────────────────────────────────────────────

  const [questions, setQuestions] = useState<ClientSafeMockQuestion[]>([])
  const [loadingQ, setLoadingQ] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [currentQNumber, setCurrentQNumber] = useState(1)
  const [answers, setAnswers] = useState<Record<string, SelectedOption>>({})
  const [marked, setMarked] = useState<Set<number>>(new Set())
  const [visited, setVisited] = useState<Set<number>>(new Set([1]))
  const [showSidebar, setShowSidebar] = useState(false)
  const [testMeta, setTestMeta] = useState<{
    duration_seconds: number
    time_spent_seconds: number
    title: string
    medium?: string
  } | null>(null)
  const [showConfirm, setShowConfirm] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [showLeave, setShowLeave] = useState(false)
  // Captured when the dialog opens rather than read during render:
  // getTotalTimeSpent() reads a ref, and a ref must not be touched while
  // rendering. It is a frozen figure anyway — the clock the candidate is
  // being shown is the one at the moment they asked to leave.
  const [leaveRemaining, setLeaveRemaining] = useState(0)
  const [leaving, setLeaving] = useState(false)

  // Total questions in the module, from the API — used to show chunk progress
  // while the later chunks are still streaming in.
  const [totalQuestions, setTotalQuestions] = useState(0)

  // Saved answers from a resumed attempt, keyed by question_uid. Kept in a ref
  // so background chunks can apply the ones that belong to them.
  const savedAnswersRef = useRef<Record<string, { selected_option: SelectedOption; marked_for_review: boolean }>>({})

  // Track per-question time (for analytics, not for scoring)
  const questionStartRef = useRef<number>(Date.now())
  const questionTimes = useRef<Record<string, number>>({})
  const pendingSavesRef = useRef<Record<string, ReturnType<typeof setTimeout>>>({})

  // ── Question Navigation ───────────────────────────────────────

  const sorted = [...questions].sort((a, b) => a.question_number - b.question_number)
  const currentQ = sorted.find((q) => q.question_number === currentQNumber) || sorted[0]
  const currentIdx = sorted.findIndex((q) => q.question_number === currentQNumber)

  // ── Load Questions + Attempt State ───────────────────────────

  useEffect(() => {
    if (!testId || !attemptId) {
      setLoadError('Missing test or attempt ID. Please start the test from the Mock Tests page.')
      setLoadingQ(false)
      return
    }

    let cancelled = false

    const load = async () => {
      setLoadingQ(true)
      setLoadError(null)
      try {
        // First chunk + attempt state + test info in parallel.
        const [qRes, attemptRes, testRes] = await Promise.all([
          fetch(`/api/dsc-sgt/mock-tests/${testId}/questions?start=1&limit=${QUESTIONS_CHUNK_SIZE}`),
          fetch(`/api/dsc-sgt/mock-tests/attempts/${attemptId}`),
          fetch(`/api/dsc-sgt/mock-tests/${testId}`),
        ])

        const [qData, attemptData, testData] = await Promise.all([
          qRes.json(),
          attemptRes.json(),
          testRes.json(),
        ])

        if (!qData.success || !qData.questions?.length) {
          setLoadError(qData.error || 'Questions not available. Contact support.')
          return
        }

        if (!attemptData.success) {
          setLoadError(attemptData.error || 'Could not load attempt. Please restart.')
          return
        }

        setQuestions(qData.questions)
        setTotalQuestions(qData.total ?? qData.questions.length)

        const attempt = attemptData.attempt
        const testInfo = testData?.test
        setTestMeta({
          duration_seconds: attempt.duration_seconds,
          time_spent_seconds: attempt.time_spent_seconds,
          title: testInfo?.title || 'AP DSC SGT Mock Test',
          medium: testInfo?.medium || 'telugu',
        })

        // Restore saved answers
        const savedAnswers: Record<string, SelectedOption> = {}
        const savedMarked = new Set<number>()
        const savedVisited = new Set<number>([1])

        const existingAnswers = attempt.existing_answers as Record<
          string,
          { selected_option: SelectedOption; marked_for_review: boolean }
        >
        savedAnswersRef.current = existingAnswers ?? {}

        const allQs: ClientSafeMockQuestion[] = qData.questions
        if (existingAnswers) {
          for (const q of allQs) {
            const saved = existingAnswers[q.question_uid]
            if (saved) {
              if (saved.selected_option) savedAnswers[q.question_uid] = saved.selected_option
              if (saved.marked_for_review) savedMarked.add(q.question_number)
              savedVisited.add(q.question_number)
            }
          }
        }

        setAnswers(savedAnswers)
        setMarked(savedMarked)
        setVisited(savedVisited)

        // The exam is usable now. Stream the remaining chunks in the
        // background and merge them as they arrive.
        setLoadingQ(false)
        void loadRemainingChunks(qData.next_start as number | null, qData.has_more as boolean)
      } catch {
        setLoadError('Failed to load exam. Please check your connection and try again.')
        setLoadingQ(false)
      }
    }

    /**
     * Fetch chunks 2..N sequentially (Q51-100, Q101-160, ...).
     * Sequential rather than parallel so a slow connection is not hit with
     * several simultaneous requests while the candidate is already answering.
     */
    const loadRemainingChunks = async (nextStart: number | null, hasMore: boolean) => {
      let start = nextStart
      let more = hasMore

      while (more && start != null && !cancelled) {
        try {
          const res = await fetch(
            `/api/dsc-sgt/mock-tests/${testId}/questions?start=${start}&limit=${QUESTIONS_CHUNK_SIZE}`
          )
          const data = await res.json()
          if (!data.success || !data.questions?.length) break
          if (cancelled) return

          const incoming = data.questions as ClientSafeMockQuestion[]

          setQuestions((prev) => {
            const byUid = new Map(prev.map((q) => [q.question_uid, q]))
            for (const q of incoming) byUid.set(q.question_uid, q)
            return [...byUid.values()].sort((a, b) => a.question_number - b.question_number)
          })

          // Apply any saved answers belonging to this chunk.
          const saved = savedAnswersRef.current
          if (saved) {
            const newAnswers: Record<string, SelectedOption> = {}
            const newMarked: number[] = []
            for (const q of incoming) {
              const entry = saved[q.question_uid]
              if (!entry) continue
              if (entry.selected_option) newAnswers[q.question_uid] = entry.selected_option
              if (entry.marked_for_review) newMarked.push(q.question_number)
            }
            if (Object.keys(newAnswers).length > 0) {
              setAnswers((prev) => ({ ...prev, ...newAnswers }))
            }
            if (newMarked.length > 0) {
              setMarked((prev) => new Set([...prev, ...newMarked]))
            }
          }

          start = data.next_start as number | null
          more = Boolean(data.has_more)
        } catch {
          // A failed background chunk is not fatal: the candidate keeps the
          // questions already loaded, and navigating re-renders what exists.
          break
        }
      }
    }

    load()

    return () => {
      cancelled = true
    }
  }, [testId, attemptId])

  // ── Answer Persistence (Debounced) ───────────────────────────

  const persistAnswer = useCallback((
    qId: string,
    qNumber: number,
    option: SelectedOption,
    isMarked: boolean
  ) => {
    if (!attemptId) return

    // Clear pending save for this question
    if (pendingSavesRef.current[qId]) {
      clearTimeout(pendingSavesRef.current[qId])
    }

    pendingSavesRef.current[qId] = setTimeout(async () => {
      try {
        await fetch(`/api/dsc-sgt/mock-tests/attempts/${attemptId}/answer`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            questionId: qId,
            questionNumber: qNumber,
            selectedOption: option,
            markedForReview: isMarked,
            timeTakenSeconds: Math.round((questionTimes.current[qId] || 0) / 1000),
          }),
        })
      } catch {
        // Silently fail — answer saved locally already
      }
    }, AUTOSAVE_DEBOUNCE_MS)
  }, [attemptId])

  // ── Navigation Handlers ───────────────────────────────────────

  const markVisited = useCallback((qNumber: number) => {
    setVisited((prev) => {
      if (prev.has(qNumber)) return prev
      const next = new Set(prev)
      next.add(qNumber)
      return next
    })
  }, [])

  const handleQuestionTransition = useCallback((nextQNumber: number) => {
    if (!currentQ) return
    // Record time spent on current question
    const elapsed = Date.now() - questionStartRef.current
    questionTimes.current[currentQ.question_uid] =
      (questionTimes.current[currentQ.question_uid] || 0) + elapsed
    questionStartRef.current = Date.now()
    setCurrentQNumber(nextQNumber)
    markVisited(nextQNumber)
  }, [currentQ, markVisited])

  const handleSelectOption = useCallback((key: SelectedOption) => {
    if (!currentQ) return
    setAnswers((prev) => {
      const next = { ...prev, [currentQ.question_uid]: key }
      persistAnswer(currentQ.question_uid, currentQ.question_number, key, marked.has(currentQ.question_number))
      return next
    })
  }, [currentQ, marked, persistAnswer])

  const handleClearResponse = useCallback(() => {
    if (!currentQ) return
    setAnswers((prev) => {
      const next = { ...prev }
      delete next[currentQ.question_uid]
      persistAnswer(currentQ.question_uid, currentQ.question_number, null, marked.has(currentQ.question_number))
      return next
    })
  }, [currentQ, marked, persistAnswer])

  const handleMarkReview = useCallback(() => {
    if (!currentQ) return
    const isNowMarked = !marked.has(currentQ.question_number)
    setMarked((prev) => {
      const next = new Set(prev)
      isNowMarked ? next.add(currentQ.question_number) : next.delete(currentQ.question_number)
      return next
    })
    persistAnswer(currentQ.question_uid, currentQ.question_number, answers[currentQ.question_uid] || null, isNowMarked)

    // Navigate to next question
    if (currentIdx < sorted.length - 1) {
      handleQuestionTransition(sorted[currentIdx + 1].question_number)
    }
  }, [currentQ, currentIdx, sorted, marked, answers, persistAnswer, handleQuestionTransition])

  const handleNext = useCallback(() => {
    if (currentIdx < sorted.length - 1) {
      handleQuestionTransition(sorted[currentIdx + 1].question_number)
    }
  }, [currentIdx, sorted, handleQuestionTransition])

  const handlePrev = useCallback(() => {
    if (currentIdx > 0) {
      handleQuestionTransition(sorted[currentIdx - 1].question_number)
    }
  }, [currentIdx, sorted, handleQuestionTransition])

  const handleJump = useCallback((qNumber: number) => {
    handleQuestionTransition(qNumber)
    setShowSidebar(false)
  }, [handleQuestionTransition])

  // ── Timer expiry ──────────────────────────────────────────────

  const handleTimerExpire = useCallback(() => {
    toast.error('⏰ Time is up! Submitting your exam automatically.', { duration: 5000 })
    setTimeout(() => handleSubmit(true), 1500)
  }, [])

  // ── Submission ────────────────────────────────────────────────

  const getTotalTimeSpent = useCallback(() => {
    if (!testMeta) return 0
    return Math.min(
      testMeta.duration_seconds,
      testMeta.time_spent_seconds + Math.round((Date.now() - questionStartRef.current) / 1000)
    )
  }, [testMeta])

  const handleSubmit = useCallback(async (auto = false) => {
    if (submitting) return
    setSubmitting(true)

    const toastId = 'exam-submit'
    toast.loading('Submitting and scoring your exam…', { id: toastId })

    try {
      const res = await fetch(`/api/dsc-sgt/mock-tests/attempts/${attemptId}/submit`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ totalTimeSpentSeconds: getTotalTimeSpent() }),
      })
      const data = await res.json()

      if (!res.ok || !data.success) {
        if (res.status === 409) {
          toast.success('Redirecting to your result…', { id: toastId })
          router.replace(`/dsc-sgt/mock-result?attemptId=${attemptId}`)
          return
        }
        throw new Error(data.error || 'Submission failed')
      }

      toast.success('Exam submitted! Loading your result…', { id: toastId })
      router.replace(`/dsc-sgt/mock-result?attemptId=${attemptId}`)
    } catch (err: any) {
      toast.error(err.message || 'Submission failed. Please try again.', { id: toastId })
      setSubmitting(false)
    }
  }, [attemptId, submitting, getTotalTimeSpent, router])

  const openLeaveDialog = useCallback(() => {
    setLeaveRemaining(Math.max(0, (testMeta?.duration_seconds ?? 0) - getTotalTimeSpent()))
    setShowLeave(true)
  }, [testMeta, getTotalTimeSpent])


  // ── Leaving the exam ────────────────────────────────────────────
  // Back is intercepted rather than blocked. A sentinel entry is pushed on
  // top of the exam so the first Back pops that instead of the route, which
  // gives us somewhere to ask the question; the entry is pushed again if the
  // candidate decides to stay, so a second Back asks again rather than
  // escaping.
  useEffect(() => {
    if (typeof window === 'undefined') return
    window.history.pushState({ examGuard: true }, '')

    const onPopState = () => {
      openLeaveDialog()
      window.history.pushState({ examGuard: true }, '')
    }

    window.addEventListener('popstate', onPopState)
    return () => window.removeEventListener('popstate', onPopState)
  }, [openLeaveDialog])

  // A tab close or reload cannot be intercepted, only warned about.
  useEffect(() => {
    const onBeforeUnload = (e: BeforeUnloadEvent) => {
      e.preventDefault()
      e.returnValue = ''
    }
    window.addEventListener('beforeunload', onBeforeUnload)
    return () => window.removeEventListener('beforeunload', onBeforeUnload)
  }, [])

  // ── Fullscreen ──────────────────────────────────────────────────
  // Worth having for a 150-minute paper: it removes the browser chrome, and
  // on a phone that is a third of the screen back. Tracked from the
  // fullscreenchange event rather than from the click, because Escape and the
  // system gesture also leave it and the button must not lie about the state.
  const [isFullscreen, setIsFullscreen] = useState(false)

  const hintSeen = useSyncExternalStore(subscribeHint, hintSnapshot, () => 'seen')
  const showPaletteHint = hintSeen === ''

  useEffect(() => {
    const sync = () => setIsFullscreen(Boolean(document.fullscreenElement))
    document.addEventListener('fullscreenchange', sync)
    return () => document.removeEventListener('fullscreenchange', sync)
  }, [])

  const toggleFullscreen = useCallback(async () => {
    try {
      if (document.fullscreenElement) await document.exitFullscreen()
      else await document.documentElement.requestFullscreen()
    } catch {
      // iOS Safari refuses this outside a video element. Nothing to do but
      // leave the button inert rather than show an error mid-exam.
    }
  }, [])

  const handlePause = useCallback(async () => {
    if (leaving) return
    setLeaving(true)
    try {
      // The elapsed figure only exists in this page — the server runs no clock
      // for an attempt — so it is sent here and clamped there.
      await fetch(`/api/dsc-sgt/mock-tests/attempts/${attemptId}/pause`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ totalTimeSpentSeconds: getTotalTimeSpent() }),
      })
    } catch {
      // Going back matters more than the last few seconds of bookkeeping; the
      // attempt stays in_progress either way and is picked up on return.
    } finally {
      setLeaving(false)
      setShowLeave(false)
      router.replace('/dsc-sgt/mock-tests')
    }
  }, [attemptId, leaving, router, getTotalTimeSpent])

  // ── Derived stats ─────────────────────────────────────────────

  const answeredCount = Object.keys(answers).length
  const markedCount = marked.size
  const unansweredCount = questions.length - answeredCount

  const sections = buildSectionNav(sorted)
  const currentSectionName = currentQ?.section_name || ''

  // ── Loading & Error States ────────────────────────────────────

  if (loadingQ) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <div className="flex flex-col items-center gap-3 text-center">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
          <p className="text-sm font-medium text-muted-foreground">Loading exam questions…</p>
          <p className="text-[11px] text-muted-foreground/60">Fetching from cache — this is fast.</p>
        </div>
      </div>
    )
  }

  if (loadError || !questions.length || !currentQ) {
    return (
      <div className="flex min-h-screen items-center justify-center px-4">
        <div className="flex flex-col items-center gap-4 text-center max-w-sm">
          <AlertCircle className="h-10 w-10 text-destructive" />
          <p className="text-sm font-bold text-foreground">Could not load exam</p>
          <p className="text-xs text-muted-foreground">{loadError}</p>
          <button
            onClick={() => router.push('/dsc-sgt/mock-tests')}
            className="mt-2 inline-flex items-center gap-2 rounded-xl border border-border px-4 py-2 text-xs font-semibold text-muted-foreground hover:bg-accent"
          >
            <RefreshCw className="h-4 w-4" /> Back to Mock Tests
          </button>
        </div>
      </div>
    )
  }

  const currentAnswer = answers[currentQ.question_uid]
  const isMarked = marked.has(currentQ.question_number)

  // ── Render ────────────────────────────────────────────────────

  return (
    <div className="flex h-screen flex-col overflow-hidden bg-background">

      {/* ══ Topbar ══ */}
      <header className="flex h-14 shrink-0 items-center justify-between border-b border-border bg-card px-3 sm:px-6 gap-3 z-20">
        <div className="flex min-w-0 items-center gap-2">
          {/* The visible counterpart of Back, so leaving is not a gesture the
              candidate has to guess at. */}
          <button
            onClick={openLeaveDialog}
            aria-label="Pause exam"
            className="-ml-1 flex h-8 w-8 shrink-0 items-center justify-center rounded-xl text-muted-foreground transition hover:bg-accent hover:text-foreground"
          >
            <ArrowLeft className="h-4 w-4" />
          </button>
          {/* The module title used to sit here and was the widest thing in the
              bar — on a phone it truncated to "గ్రాండ్ మాక్ టెస్ట్ — మా…",
              which identifies nothing. A candidate already knows which test
              they opened; what they need from this bar is the time left. */}
          <div className="h-2 w-2 shrink-0 rounded-full bg-red-500 animate-pulse" />
          <span className="shrink-0 text-xs font-bold text-muted-foreground">
            Q{currentQ.question_number}
            <span className="text-muted-foreground/60"> / {questions.length}</span>
          </span>
        </div>

        {/* Status chips — desktop only */}
        <div className="hidden sm:flex items-center gap-2 text-[11px]">
          <span className="rounded-md border border-emerald-500/30 bg-emerald-500/10 px-2 py-0.5 font-bold text-emerald-600 dark:text-emerald-400">
            ✓ {answeredCount}
          </span>
          <span className="rounded-md border border-amber-500/30 bg-amber-500/10 px-2 py-0.5 font-bold text-amber-500">
            ⚑ {markedCount}
          </span>
          <span className="rounded-md border border-red-500/30 bg-red-500/10 px-2 py-0.5 font-bold text-red-500">
            ✗ {unansweredCount}
          </span>
        </div>

        <div className="flex items-center gap-2">
          {testMeta && (
            <CountdownTimer
              totalSeconds={testMeta.duration_seconds}
              timeSpentSeconds={testMeta.time_spent_seconds}
              onExpire={handleTimerExpire}
            />
          )}
          {/* Hidden where the API is unavailable rather than shown broken. */}
          <button
            onClick={toggleFullscreen}
            aria-label={isFullscreen ? 'Exit full screen' : 'Full screen'}
            className="hidden h-8 w-8 items-center justify-center rounded-xl border border-border bg-muted/60 text-muted-foreground transition hover:text-foreground [@supports(display:flex)]:inline-flex"
          >
            {isFullscreen ? <Minimize className="h-3.5 w-3.5" /> : <Maximize className="h-3.5 w-3.5" />}
          </button>
          <button
            id="mock-exam-submit-btn"
            onClick={() => setShowConfirm(true)}
            disabled={submitting}
            className="inline-flex items-center gap-1.5 rounded-xl bg-primary px-3 py-1.5 text-[11px] font-bold text-white hover:bg-primary/90 disabled:opacity-50"
          >
            <Send className="h-3 w-3" />
            <span className="hidden sm:inline">Submit</span>
          </button>
          {/* Mobile sidebar toggle */}
          <div className="relative sm:hidden">
            <button
              onClick={() => {
                setShowSidebar(true)
                dismissHint()
              }}
              aria-label={`Question ${currentQNumber} of ${questions.length} — open the question list`}
              className={`inline-flex h-8 w-8 items-center justify-center rounded-xl border bg-muted/60 ${
                showPaletteHint ? 'border-primary ring-2 ring-primary/30' : 'border-border'
              }`}
            >
              <span className="text-[11px] font-black">{currentQNumber}</span>
            </button>

            {showPaletteHint && (
              <div
                role="status"
                className="absolute right-0 top-full z-30 mt-2 w-56 rounded-2xl border border-border bg-popover p-3 text-left shadow-xl animate-in fade-in-50 slide-in-from-top-1"
              >
                {/* Arrow, pointing back at the button. */}
                <span className="absolute -top-1.5 right-3 h-3 w-3 rotate-45 border-l border-t border-border bg-popover" />
                <p className="relative text-[11px] font-semibold text-foreground">
                  All {questions.length} questions are here
                </p>
                <p className="relative mt-1 text-[11px] leading-relaxed text-muted-foreground">
                  Tap this to jump to any question, or to see what you have not
                  answered yet.
                </p>
                <button
                  onClick={dismissHint}
                  className="relative mt-2 w-full rounded-xl bg-primary py-1.5 text-[11px] font-semibold text-primary-foreground"
                >
                  Got it
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      {/* ══ Main Body: Question + Sidebar ══ */}
      <div className="flex flex-1 overflow-hidden">

        {/* ── Left: Question Area ── */}
        <div className="flex flex-1 flex-col overflow-y-auto p-4 sm:p-6 gap-4">

          {/* Question header */}
          <div className="flex items-start justify-between gap-3 flex-wrap">
            <div className="flex items-center gap-2 flex-wrap">
              <span className="rounded-lg border border-border bg-muted/50 px-2.5 py-1 text-[11px] font-bold text-muted-foreground">
                {currentSectionName}
              </span>
              <span className="text-xs font-black text-foreground">Q {currentQ.question_number}</span>
              <span className="text-[11px] text-muted-foreground">
                / {totalQuestions || questions.length}
              </span>
              {totalQuestions > 0 && questions.length < totalQuestions && (
                <span
                  className="inline-flex items-center gap-1 rounded-md bg-muted/60 px-2 py-0.5 text-[11px] font-semibold text-muted-foreground"
                  title="Later questions are still loading in the background"
                >
                  <Loader2 className="h-3 w-3 animate-spin" />
                  {questions.length}/{totalQuestions} loaded
                </span>
              )}
              {currentQ.difficulty && (
                <span className={`rounded-md px-2 py-0.5 text-[11px] font-bold ${
                  currentQ.difficulty.toLowerCase() === 'easy' ? 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400' :
                  currentQ.difficulty.toLowerCase() === 'hard' ? 'bg-red-500/10 text-red-500' :
                  'bg-secondary text-primary'
                }`}>
                  {currentQ.difficulty}
                </span>
              )}
            </div>
            <div className="flex items-center gap-2.5">
              <span className="text-[11px] text-muted-foreground font-medium">
                {currentQ.marks} mark{currentQ.marks !== 1 ? 's' : ''}
              </span>

              {/* Report a problem with this question */}
              <QuestionFeedbackButton
                questionUid={currentQ.question_uid}
                source="mock_exam"
                mockTestId={testId}
                questionText={currentQ.question}
              />
            </div>
          </div>

          {/* Question text */}
          <div className="rounded-2xl border border-border/80 bg-card p-4 sm:p-6 shadow-sm">
            <p className="text-sm sm:text-[15px] font-semibold leading-relaxed text-foreground whitespace-pre-wrap">
              {currentQ.question}
            </p>
          </div>

          {/* Options */}
          <div className="grid gap-3">
            {(['A', 'B', 'C', 'D'] as const).map((key) => {
              const optionText = currentQ[`option_${key.toLowerCase()}` as keyof ClientSafeMockQuestion] as string
              const isSelected = currentAnswer === key

              return (
                <button
                  key={key}
                  id={`mock-option-${key}`}
                  onClick={() => handleSelectOption(key)}
                  className={`flex w-full items-start gap-3 rounded-2xl border p-3.5 text-left text-xs transition-all ${
                    isSelected
                      ? 'border-primary/70 bg-primary/10 ring-1 ring-primary/30'
                      : 'border-border/70 bg-card hover:border-primary/40 hover:bg-accent/50'
                  }`}
                >
                  <span className={`mt-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-lg text-[11px] font-black transition ${
                    isSelected ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'
                  }`}>
                    {key}
                  </span>
                  <span className="flex-1 font-medium text-foreground leading-snug">
                    {optionText}
                  </span>
                  {isSelected && <CheckCircle2 className="h-4 w-4 shrink-0 text-primary mt-0.5" />}
                </button>
              )
            })}
          </div>

          {/* Action Row */}
          <div className="flex flex-wrap items-center justify-between gap-3 pb-6">
            <div className="flex items-center gap-2">
              <button
                onClick={handleMarkReview}
                className={`inline-flex items-center gap-1.5 rounded-xl border px-3 py-2 text-xs font-semibold transition ${
                  isMarked
                    ? 'border-amber-500/60 bg-amber-500/10 text-amber-500'
                    : 'border-border text-muted-foreground hover:border-amber-400 hover:text-amber-500'
                }`}
              >
                <Bookmark className={`h-3.5 w-3.5 ${isMarked ? 'fill-amber-500' : ''}`} />
                {isMarked ? 'Marked' : 'Mark & Next'}
              </button>
              {currentAnswer && (
                <button
                  onClick={handleClearResponse}
                  className="inline-flex items-center gap-1 rounded-xl border border-border px-3 py-2 text-xs font-semibold text-muted-foreground hover:text-destructive hover:border-destructive/40"
                >
                  <RotateCcw className="h-3.5 w-3.5" />
                  Clear
                </button>
              )}
            </div>

            <div className="flex items-center gap-2">
              <button
                onClick={handlePrev}
                disabled={currentIdx === 0}
                className="inline-flex items-center gap-1.5 rounded-xl border border-border px-3 py-2 text-xs font-semibold text-muted-foreground hover:bg-accent disabled:opacity-40"
              >
                <ChevronLeft className="h-3.5 w-3.5" /> Previous
              </button>
              {currentIdx < sorted.length - 1 ? (
                <button
                  onClick={handleNext}
                  className="inline-flex items-center gap-1.5 rounded-xl bg-primary/10 border border-primary/30 px-3 py-2 text-xs font-bold text-primary hover:bg-primary/20"
                >
                  Next <ChevronRight className="h-3.5 w-3.5" />
                </button>
              ) : (
                <button
                  onClick={() => setShowConfirm(true)}
                  className="inline-flex items-center gap-1.5 rounded-xl bg-primary px-3 py-2 text-xs font-bold text-white hover:bg-primary/90"
                >
                  Submit <Send className="h-3.5 w-3.5" />
                </button>
              )}
            </div>
          </div>
        </div>

        {/* ── Right Sidebar: Question Grid ── */}
        <>
          {/* Desktop sidebar */}
          <aside className="hidden sm:flex w-64 shrink-0 flex-col border-l border-border bg-card/80 overflow-y-auto p-4">
            <div className="flex items-center gap-1.5 mb-3">
              <HelpCircle className="h-3.5 w-3.5 text-muted-foreground" />
              <span className="text-[11px] font-bold text-muted-foreground uppercase tracking-wide">
                Question Palette
              </span>
            </div>
            <QuestionGrid
              questions={sorted}
              currentQNumber={currentQNumber}
              answers={answers}
              visited={visited}
              marked={marked}
              onJump={handleJump}
            />
          </aside>

          {/* Mobile sidebar overlay */}
          {showSidebar && (
            <div className="fixed inset-0 z-40 bg-black/60 backdrop-blur-sm" onClick={() => setShowSidebar(false)}>
              <div
                className="absolute right-0 top-0 flex h-full w-72 flex-col border-l border-border bg-card overflow-y-auto p-4"
                onClick={(e) => e.stopPropagation()}
              >
                <div className="mb-3 flex items-center justify-between">
                  <span className="text-xs font-bold text-muted-foreground uppercase tracking-wide">Question Palette</span>
                  <button onClick={() => setShowSidebar(false)} className="text-muted-foreground hover:text-foreground">
                    <X className="h-4 w-4" />
                  </button>
                </div>
                <QuestionGrid
                  questions={sorted}
                  currentQNumber={currentQNumber}
                  answers={answers}
                  visited={visited}
                  marked={marked}
                  onJump={handleJump}
                />
              </div>
            </div>
          )}
        </>
      </div>

      {/* ══ Leave Modal ══ */}
      {showLeave && (
        <LeaveExamModal
          answered={answeredCount}
          unanswered={unansweredCount}
          remainingLabel={formatRemaining(leaveRemaining)}
          onPause={handlePause}
          onCancel={() => setShowLeave(false)}
          busy={leaving}
        />
      )}

      {/* ══ Confirmation Modal ══ */}
      {showConfirm && (
        <SubmitConfirmModal
          totalQuestions={questions.length}
          answered={answeredCount}
          markedCount={markedCount}
          unanswered={unansweredCount}
          onConfirm={() => handleSubmit(false)}
          onCancel={() => setShowConfirm(false)}
          submitting={submitting}
        />
      )}
    </div>
  )
}

export default function MockExamPage() {
  return (
    <Suspense
      fallback={
        <div className="flex min-h-screen items-center justify-center">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
      }
    >
      <MockExamContent />
    </Suspense>
  )
}

'use client'

import React, { useState, useEffect, Suspense } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import {
  Trophy,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Clock,
  Award,
  BarChart3,
  BookOpen,
  ChevronDown,
  ChevronUp,
  Loader2,
  AlertCircle,
  RotateCcw,
  Target,
  ArrowRight,
  Pencil,
} from 'lucide-react'
import { COPY_GUARD_CLASS, copyGuardProps } from '@/app/components/dsc-sgt/CopyGuard'
import QuestionFeedbackButton from '@/app/components/dsc-sgt/QuestionFeedbackButton'
import type { MockTestResultSummary, SectionScore, QuestionReviewItem } from '@/types/mock-tests'

function ScoreGauge({ percentage }: { percentage: number }) {
  const clr =
    percentage >= 70 ? 'text-emerald-500' :
    percentage >= 50 ? 'text-amber-500' :
    'text-red-500'
  return (
    <div className="relative inline-flex items-center justify-center">
      <svg className="h-32 w-32 -rotate-90" viewBox="0 0 80 80">
        <circle cx="40" cy="40" r="34" fill="none" stroke="currentColor" strokeWidth="6" className="text-muted/30" />
        <circle
          cx="40" cy="40" r="34" fill="none" strokeWidth="6"
          strokeDasharray={`${(percentage / 100) * 213.6} 213.6`}
          strokeLinecap="round"
          className={clr}
          stroke="currentColor"
        />
      </svg>
      <div className="absolute flex flex-col items-center">
        <span className={`text-2xl font-black ${clr}`}>{percentage.toFixed(1)}%</span>
        <span className="text-[11px] text-muted-foreground font-medium">Score</span>
      </div>
    </div>
  )
}

function QuestionReviewCard({
  item,
  mockTestId,
}: {
  item: QuestionReviewItem
  mockTestId: string | null
}) {
  const [open, setOpen] = useState(false)

  const statusIcon = item.is_skipped
    ? <HelpCircle className="h-4 w-4 text-muted-foreground" />
    : item.is_correct
    ? <CheckCircle2 className="h-4 w-4 text-emerald-500" />
    : <XCircle className="h-4 w-4 text-red-500" />

  const borderColor = item.is_skipped
    ? 'border-border'
    : item.is_correct
    ? 'border-emerald-500/30'
    : 'border-red-500/30'

  return (
    <div className={`rounded-2xl border bg-card ${borderColor}`}>
      <button
        onClick={() => setOpen((v) => !v)}
        className="flex w-full items-center justify-between gap-3 p-3.5 text-left"
      >
        <div className="flex items-center gap-2.5 min-w-0">
          {statusIcon}
          <span className="text-[11px] font-bold text-muted-foreground shrink-0">Q{item.question_number}</span>
          <span className="text-xs text-foreground line-clamp-1 font-medium">{item.question}</span>
        </div>
        <div className="flex items-center gap-2 shrink-0">
          {!item.is_skipped && (
            <span className={`text-[11px] font-bold ${item.is_correct ? 'text-emerald-500' : 'text-red-500'}`}>
              {item.is_correct ? `+${item.marks}` : '0'}
            </span>
          )}
          {open ? <ChevronUp className="h-3.5 w-3.5 text-muted-foreground" /> : <ChevronDown className="h-3.5 w-3.5 text-muted-foreground" />}
        </div>
      </button>

      {open && (
        <div className="border-t border-border/60 px-4 py-3.5 text-xs space-y-3">
          {/* The result itself is frozen at submit time, so an edit can never
              change the mark. It can change the wording, and a candidate who
              remembers the old question deserves to know why it reads
              differently. */}
          {item.edited_since_attempt && (
            <p className="flex items-start gap-2 rounded-xl bg-amber-500/10 px-3 py-2 text-[11px] text-amber-700 dark:text-amber-300">
              <Pencil className="mt-0.5 h-3 w-3 shrink-0" />
              <span>
                ఈ ప్రశ్న మీరు పరీక్ష రాసిన తర్వాత సవరించబడింది. మీ మార్కులు మారవు.
                <span className="block opacity-80">
                  This question was updated after your attempt. Your score is unchanged.
                </span>
              </span>
            </p>
          )}
          <p className="font-semibold text-foreground leading-relaxed">{item.question}</p>
          <div className="grid gap-1.5">
            {(['A', 'B', 'C', 'D'] as const).map((key) => {
              const optionText = item[`option_${key.toLowerCase()}` as keyof QuestionReviewItem] as string
              const isUser = item.user_answer === key
              const isCorrect = item.correct_answer === key

              return (
                <div
                  key={key}
                  className={`flex items-start gap-2.5 rounded-xl px-3 py-2 ${
                    isCorrect
                      ? 'bg-emerald-500/10 border border-emerald-500/30'
                      : isUser && !isCorrect
                      ? 'bg-red-500/10 border border-red-500/30'
                      : 'border border-transparent'
                  }`}
                >
                  <span className={`mt-0.5 h-5 w-5 shrink-0 flex items-center justify-center rounded-md text-[11px] font-black ${
                    isCorrect ? 'bg-emerald-500 text-white' :
                    isUser && !isCorrect ? 'bg-red-500 text-white' :
                    'bg-muted text-muted-foreground'
                  }`}>
                    {key}
                  </span>
                  <span className="text-foreground leading-snug">{optionText}</span>
                  {isCorrect && <CheckCircle2 className="ml-auto h-3.5 w-3.5 shrink-0 text-emerald-500" />}
                  {isUser && !isCorrect && <XCircle className="ml-auto h-3.5 w-3.5 shrink-0 text-red-500" />}
                </div>
              )
            })}
          </div>

          {item.explanation && (
            <div className="rounded-xl border border-primary/20 bg-secondary p-3">
              <p className="font-bold text-primary mb-1 text-[11px] uppercase tracking-wide">Explanation</p>
              <p className="text-foreground leading-relaxed">{item.explanation}</p>
            </div>
          )}

          <div className="flex items-center gap-3 text-[11px] text-muted-foreground">
            <span>{item.section_name}</span>
            {item.topic && <><span>·</span><span>{item.topic}</span></>}
            {item.difficulty && <><span>·</span><span>{item.difficulty}</span></>}
            <span>·</span>
            <span>{item.time_taken_seconds}s</span>

            {/* Spotted a problem with this question? */}
            <QuestionFeedbackButton
              className="ml-auto"
              questionUid={item.question_uid}
              source="mock_result"
              mockTestId={mockTestId}
              questionText={item.question}
            />
          </div>
        </div>
      )}
    </div>
  )
}

function MockResultContent() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const attemptId = searchParams.get('attemptId')

  const [result, setResult] = useState<MockTestResultSummary | null>(null)
  const [nextModule, setNextModule] = useState<{
    id: string
    slug: string
    title: string
    module_number: number
    progress_status?: string
  } | null>(null)
  const [startingNext, setStartingNext] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [reviewFilter, setReviewFilter] = useState<'all' | 'correct' | 'incorrect' | 'skipped'>('all')
  const [reviewSection, setReviewSection] = useState<string>('all')

  useEffect(() => {
    if (!attemptId) {
      setError('No attempt ID provided.')
      setLoading(false)
      return
    }


    const load = async () => {
      try {
        const res = await fetch(`/api/dsc-sgt/mock-tests/attempts/${attemptId}/result`)
        const data = await res.json()
        if (!res.ok || !data.success) {
          setError(data.error || 'Could not load result.')
          return
        }
        setResult(data.result)

        // Resolve the next module in this series so the completion screen can
        // offer [ Next Module ] directly.
        if (data.result?.mock_test_id) {
          try {
            const nextRes = await fetch(`/api/dsc-sgt/mock-tests/${data.result.mock_test_id}/next`)
            const nextData = await nextRes.json()
            if (nextData.success) setNextModule(nextData.next_module ?? null)
          } catch {
            // Non-fatal: the result still renders without the next-module CTA.
          }
        }
      } catch {
        setError('Network error — please refresh and try again.')
      } finally {
        setLoading(false)
      }
    }

    load()
  }, [attemptId])

  /**
   * Start the next module in the series.
   *
   * Premium gating is enforced server-side by the start endpoint, so a locked
   * module simply sends the user back to the module list where the upgrade
   * prompt lives.
   */
  const startNextModule = async () => {
    if (!nextModule || startingNext) return
    setStartingNext(true)
    try {
      const res = await fetch(`/api/dsc-sgt/mock-tests/${nextModule.id}/start`, { method: 'POST' })
      const data = await res.json()

      if (!res.ok || !data.success) {
        router.push('/dsc-sgt/mock-tests')
        return
      }

      router.push(`/dsc-sgt/mock-exam?testId=${nextModule.id}&attemptId=${data.attempt_id}`)
    } catch {
      router.push('/dsc-sgt/mock-tests')
    } finally {
      setStartingNext(false)
    }
  }

  if (loading) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <div className="flex flex-col items-center gap-3">
          <Loader2 className="h-7 w-7 animate-spin text-primary" />
          <p className="text-xs text-muted-foreground">Loading your result…</p>
        </div>
      </div>
    )
  }

  if (error || !result) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center px-4">
        <div className="flex flex-col items-center gap-4 text-center">
          <AlertCircle className="h-10 w-10 text-destructive" />
          <p className="text-sm font-bold">Result unavailable</p>
          <p className="text-xs text-muted-foreground">{error}</p>
          <button onClick={() => router.push('/dsc-sgt/mock-tests')} className="text-xs text-primary hover:underline">
            ← Back to Mock Tests
          </button>
        </div>
      </div>
    )
  }

  const totalSections = result.section_scores || []

  const filteredReview = (result.questions_review || []).filter((q) => {
    const matchSection = reviewSection === 'all' || q.section_id === reviewSection
    const matchFilter =
      reviewFilter === 'all' ? true :
      reviewFilter === 'correct' ? q.is_correct :
      reviewFilter === 'incorrect' ? (!q.is_correct && !q.is_skipped) :
      q.is_skipped
    return matchSection && matchFilter
  })

  const uniqueSections = [...new Set((result.questions_review || []).map((q) => q.section_id))]

  const hrs = Math.floor(result.total_time_seconds / 3600)
  const mins = Math.floor((result.total_time_seconds % 3600) / 60)
  const secs = result.total_time_seconds % 60
  const timeStr = hrs > 0
    ? `${hrs}h ${mins}m ${secs}s`
    : `${mins}m ${secs}s`

  return (
    <main
      className={`mx-auto max-w-5xl px-4 py-8 sm:px-6 lg:px-8 space-y-6 ${COPY_GUARD_CLASS}`}
      {...copyGuardProps}
    >

      {/* ── Module completion state ── */}
      <div className="flex items-center justify-center gap-2 rounded-3xl border border-emerald-500/40 bg-emerald-500/10 px-5 py-3 text-center">
        <CheckCircle2 className="h-5 w-5 shrink-0 text-emerald-500" />
        <span className="text-sm font-black uppercase tracking-wide text-emerald-700 dark:text-emerald-400">
          Module Completed
        </span>
      </div>

      {/* ── Result Header ── */}
      <div className="rounded-3xl border border-border bg-card p-6 sm:p-8 shadow-sm text-center">
        <div className="flex justify-center">
          <ScoreGauge percentage={result.percentage} />
        </div>

        <h1 className="mt-4 text-xl sm:text-2xl font-black text-foreground">
          Exam Result — {result.test_title}
        </h1>
        <p className="mt-1 text-xs text-muted-foreground">AP DSC SGT Grand Mock · Server-Scored Result</p>

        {/* Core Metrics */}
        <div className="mt-6 grid grid-cols-2 gap-3 sm:grid-cols-4">
          <div className="rounded-2xl border border-border bg-muted/30 p-4 text-center">
            <p className="text-[11px] text-muted-foreground mb-1">Score</p>
            <p className="text-2xl font-black text-foreground">{result.score}</p>
            <p className="text-[11px] text-muted-foreground">/ {result.total_marks} Marks</p>
          </div>
          <div className="rounded-2xl border border-emerald-500/30 bg-emerald-500/5 p-4 text-center">
            <p className="text-[11px] text-muted-foreground mb-1">Correct</p>
            <p className="text-2xl font-black text-emerald-500">{result.correct_count}</p>
            <p className="text-[11px] text-muted-foreground">of {result.total_questions}</p>
          </div>
          <div className="rounded-2xl border border-red-500/30 bg-red-500/5 p-4 text-center">
            <p className="text-[11px] text-muted-foreground mb-1">Incorrect</p>
            <p className="text-2xl font-black text-red-500">{result.incorrect_count}</p>
            <p className="text-[11px] text-muted-foreground">Attempted wrong</p>
          </div>
          <div className="rounded-2xl border border-amber-500/30 bg-amber-500/5 p-4 text-center">
            <p className="text-[11px] text-muted-foreground mb-1">Unattempted</p>
            <p className="text-2xl font-black text-amber-500">{result.unanswered_count}</p>
            <p className="text-[11px] text-muted-foreground">Skipped</p>
          </div>
        </div>

        {/* Rank & Time */}
        <div className="mt-4 flex flex-wrap items-center justify-center gap-4 text-xs text-muted-foreground">
          <span className="flex items-center gap-1.5">
            <Clock className="h-3.5 w-3.5" /> Time: {timeStr}
          </span>
          <span className="flex items-center gap-1.5">
            <Target className="h-3.5 w-3.5" /> Avg/Q: {result.avg_time_per_question_seconds}s
          </span>
          {result.rank && (
            <span className="flex items-center gap-1.5 font-bold text-amber-500">
              <Trophy className="h-3.5 w-3.5" /> Rank #{result.rank}
              {result.percentile && <span className="text-muted-foreground font-normal">({result.percentile}%ile)</span>}
            </span>
          )}
        </div>

        {/* CTA buttons */}
        <div className="mt-6 flex flex-wrap items-center justify-center gap-3">
          {nextModule ? (
            <button
              onClick={() => void startNextModule()}
              disabled={startingNext}
              className="inline-flex items-center gap-2 rounded-2xl bg-primary px-5 py-2.5 text-xs font-bold text-white shadow-sm hover:bg-primary disabled:opacity-60"
            >
              {startingNext ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <>
                  Next Module — Module {String(nextModule.module_number).padStart(2, '0')}
                  <ArrowRight className="h-3.5 w-3.5" />
                </>
              )}
            </button>
          ) : null}
          <button
            onClick={() => router.push('/dsc-sgt/mock-tests')}
            className="inline-flex items-center gap-2 rounded-2xl border border-border px-5 py-2.5 text-xs font-bold text-foreground hover:bg-accent"
          >
            <RotateCcw className="h-3.5 w-3.5" /> All Modules
          </button>
          <button
            onClick={() => router.push(`/dsc-sgt/mock-tests/${result.mock_test_id}/leaderboard`)}
            className="inline-flex items-center gap-2 rounded-2xl border border-amber-500/40 bg-amber-500/10 px-5 py-2.5 text-xs font-bold text-amber-600 dark:text-amber-400 hover:border-amber-500"
          >
            <Award className="h-3.5 w-3.5" /> View Leaderboard
          </button>
        </div>
      </div>

      {/* ── Section-wise Analysis ── */}
      {totalSections.length > 0 && (
        <div className="rounded-3xl border border-border bg-card p-5 sm:p-6 shadow-sm">
          <div className="flex items-center gap-2 mb-4">
            <BarChart3 className="h-4 w-4 text-primary" />
            <h2 className="text-sm font-black text-foreground">Section-wise Performance</h2>
          </div>
          <div className="space-y-3">
            {totalSections.map((s: SectionScore) => {
              const sectionPct = s.total_marks > 0 ? (s.score / s.total_marks) * 100 : 0
              return (
                <div key={s.section_id}>
                  <div className="flex items-center justify-between text-xs mb-1">
                    <span className="font-semibold text-foreground">{s.section_name}</span>
                    <span className="font-bold text-muted-foreground">
                      {s.score} / {s.total_marks} ({sectionPct.toFixed(1)}%)
                    </span>
                  </div>
                  <div className="relative h-2.5 rounded-full bg-muted overflow-hidden">
                    <div
                      className={`h-full rounded-full transition-all duration-500 ${
                        sectionPct >= 70 ? 'bg-emerald-500' :
                        sectionPct >= 50 ? 'bg-amber-500' :
                        'bg-red-500'
                      }`}
                      style={{ width: `${sectionPct}%` }}
                    />
                  </div>
                  <div className="flex items-center gap-3 mt-1 text-[11px] text-muted-foreground">
                    <span className="text-emerald-500">✓ {s.correct}</span>
                    <span className="text-red-500">✗ {s.incorrect}</span>
                    <span>{s.total - s.correct - s.incorrect} skipped</span>
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      )}

      {/* ── Question Review ── */}
      {result.questions_review && result.questions_review.length > 0 && (
        <div className="rounded-3xl border border-border bg-card p-5 sm:p-6 shadow-sm">
          <div className="flex items-center gap-2 mb-4">
            <BookOpen className="h-4 w-4 text-primary" />
            <h2 className="text-sm font-black text-foreground">Detailed Question Review</h2>
          </div>

          {/* Filters */}
          <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between mb-4">
            <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-none">
              {([
                { value: 'all', label: `All (${result.questions_review.length})` },
                { value: 'correct', label: `Correct (${result.correct_count})` },
                { value: 'incorrect', label: `Wrong (${result.incorrect_count})` },
                { value: 'skipped', label: `Skipped (${result.unanswered_count})` },
              ] as const).map((f) => (
                <button
                  key={f.value}
                  onClick={() => setReviewFilter(f.value)}
                  className={`shrink-0 rounded-full border px-3 py-1 text-[11px] font-bold transition ${
                    reviewFilter === f.value
                      ? 'border-primary bg-primary text-primary-foreground'
                      : 'border-border text-muted-foreground hover:text-foreground'
                  }`}
                >
                  {f.label}
                </button>
              ))}
            </div>
            <select
              value={reviewSection}
              onChange={(e) => setReviewSection(e.target.value)}
              className="rounded-xl border border-border bg-card px-3 py-1.5 text-xs text-foreground focus:border-primary focus:outline-none"
            >
              <option value="all">All Sections</option>
              {uniqueSections.map((sid) => {
                const first = result.questions_review.find((q) => q.section_id === sid)
                return (
                  <option key={sid} value={sid}>{first?.section_name || sid}</option>
                )
              })}
            </select>
          </div>

          {/* Question list */}
          <div className="space-y-2">
            {filteredReview.length === 0 ? (
              <p className="py-8 text-center text-xs text-muted-foreground">No questions match this filter.</p>
            ) : (
              filteredReview.map((item) => (
                <QuestionReviewCard
                  key={item.question_uid}
                  item={item}
                  mockTestId={result.mock_test_id ?? null}
                />
              ))
            )}
          </div>
        </div>
      )}

    </main>
  )
}

export default function MockResultPage() {
  return (
    <Suspense
      fallback={
        <div className="flex min-h-screen items-center justify-center">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
      }
    >
      <MockResultContent />
    </Suspense>
  )
}

'use client'

// ============================================================
// app/dsc-sgt/mock-tests/page.tsx — SGT Mock Test Modules
// ============================================================
// Two independent pagination concepts meet here:
//
//   MODULE PAGINATION  (this page)  Module 1-20, 21-40, 41-60, ...
//   QUESTION PAGINATION (exam page) Q1-50, Q51-100, Q101-160
//
// The module list is driven entirely by the API. Nothing here caps how many
// modules can exist — add modules in the database and they appear.
// ============================================================

import React, { useState, useEffect, useCallback, useRef } from 'react'
import { useRouter } from 'next/navigation'
import {
  FileCheck2,
  Lock,
  Play,
  Crown,
  Search,
  CheckCircle2,
  RotateCcw,
  Trophy,
  Loader2,
  RefreshCw,
  Languages,
  Globe,
  Award,
  ListChecks,
} from 'lucide-react'
import { usePremium } from '@/app/components/dsc-sgt/PremiumContext'
import { useAuth } from '@/app/contexts/AuthContext'
import { resolvePreferredMedium, storeMedium } from '@/lib/medium-preference'
import { toast } from 'sonner'
import type {
  MockTestListItem,
  MockTestListResponse,
  ExamMediumKey,
  ModuleProgressStatus,
} from '@/types/mock-tests'

// Previous Year Paper and Subject Mock were removed from the product (and from
// the database), leaving a single category. A filter row whose only options are
// "All" and the one category that exists is two buttons doing the same thing,
// so the row is gone and the list simply shows every published module.
// To reintroduce categories, filter on the `category` query param the list API
// still supports.

/** Modules fetched per batch as the list scrolls. */
const MODULES_PER_BATCH = 18

interface ListMeta {
  total: number
  totalPages: number
  mediumCounts: Record<ExamMediumKey, number>
  /** Highest module submitted; the next rung of the ladder is this + 1. */
  highestCompleted: number
}

/**
 * The title carries a trailing medium in brackets — "… (తెలుగు మాధ్యమం)" or
 * "… (English Medium)" — which the badge beside it already shows. On a phone
 * that repeat pushes the title onto an extra line, so it is dropped for
 * display. The stored title is untouched.
 */
const displayTitle = (title: string) =>
  title.replace(/\s*[（(]\s*(?:[^)）]*?(?:మాధ్యమం|Medium)[^)）]*?)\s*[)）]\s*$/u, '').trim() || title

/** "Module 07" — the module a locked one is waiting on. */
const moduleName = (n: number) => `Module ${String(n).padStart(2, '0')}`

export default function MockTestsPage() {
  const router = useRouter()
  const { isPremium, openModal } = usePremium()
  const { user, loading: authLoading } = useAuth()

  const [medium, setMedium] = useState<ExamMediumKey>('telugu')
  const [mediumResolved, setMediumResolved] = useState(false)
  const [search, setSearch] = useState('')
  const [debouncedSearch, setDebouncedSearch] = useState('')

  // Modules accumulate as the reader scrolls rather than being replaced.
  const [tests, setTests] = useState<MockTestListItem[]>([])
  const [meta, setMeta] = useState<ListMeta | null>(null)
  const [page, setPage] = useState(1)
  const [loading, setLoading] = useState(true)
  const [loadingMore, setLoadingMore] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Identifies the active query. A response whose key no longer matches
  // belongs to a medium or search the reader has already moved on from, and
  // appending it would interleave two different lists.
  const queryKey = `${medium}|${debouncedSearch}`
  const activeQuery = useRef(queryKey)

  // Debounce the search box so typing does not fire a request per keystroke.
  useEffect(() => {
    const t = setTimeout(() => setDebouncedSearch(search.trim()), 350)
    return () => clearTimeout(t)
  }, [search])

  const fetchBatch = useCallback(
    async (targetPage: number, key: string) => {
      const isFirst = targetPage === 1
      // The first batch is already in its loading state — set either by the
      // initial render or by the reset below. Setting it again here would be a
      // synchronous state write inside the effect that triggers this fetch.
      if (!isFirst) {
        setLoadingMore(true)
        setError(null)
      }

      try {
        const params = new URLSearchParams({
          medium,
          page: String(targetPage),
          pageSize: String(MODULES_PER_BATCH),
        })
        if (debouncedSearch) params.set('search', debouncedSearch)

        const res = await fetch(`/api/dsc-sgt/mock-tests?${params.toString()}`)
        const json = (await res.json()) as MockTestListResponse & { error?: string }

        if (activeQuery.current !== key) return

        if (!json.success) {
          setError(json.error || 'Failed to load modules')
          return
        }

        setTests((prev) => (isFirst ? json.tests : [...prev, ...json.tests]))
        setMeta({
          total: json.total,
          totalPages: json.total_pages,
          mediumCounts: json.medium_counts,
          highestCompleted: json.highest_completed_module ?? 0,
        })
      } catch {
        if (activeQuery.current !== key) return
        setError('Network error — please try again')
      } finally {
        if (activeQuery.current === key) {
          setLoading(false)
          setLoadingMore(false)
        }
      }
    },
    [medium, debouncedSearch]
  )

  // Medium or search changed: drop what is on screen and start again at page
  // 1. Adjusting during render rather than in an effect means the stale list
  // never paints for a frame on the way out.
  const [lastQuery, setLastQuery] = useState(queryKey)
  if (lastQuery !== queryKey) {
    setLastQuery(queryKey)
    setTests([])
    setPage(1)
    setError(null)
    setLoading(true)
  }

  // Fetching is the side effect, so that part stays in an effect.
  useEffect(() => {
    activeQuery.current = queryKey
    void fetchBatch(1, queryKey)
  }, [queryKey, fetchBatch])

  const totalModules = meta?.total ?? 0
  const mediumCounts = meta?.mediumCounts ?? { english: 0, telugu: 0 }
  const hasMore = meta ? page < meta.totalPages : false

  const loadNextBatch = useCallback(() => {
    if (!hasMore || loading || loadingMore) return
    const next = page + 1
    setPage(next)
    void fetchBatch(next, activeQuery.current)
  }, [hasMore, loading, loadingMore, page, fetchBatch])

  // Infinite scroll: a sentinel below the grid pulls the next batch in early
  // enough (400px) that the reader does not meet a spinner.
  const sentinelRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const el = sentinelRef.current
    if (!el || !hasMore || loading || loadingMore) return

    const io = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) loadNextBatch()
      },
      { rootMargin: '400px' }
    )
    io.observe(el)
    return () => io.disconnect()
    // tests.length is a dependency on purpose: re-attaching after each batch
    // re-fires the initial callback, so a sentinel that is still on screen
    // (tall viewport, short batch) pulls the next batch instead of stalling
    // until the reader scrolls again.
  }, [hasMore, loading, loadingMore, tests.length, loadNextBatch])

  // Open the tab for the medium the candidate registered with. Adjusted during
  // render so the right tab is what first paints, and applied only once so a
  // tab they pick themselves is never snapped back.
  //
  // Gated on `!authLoading`: while the profile is still arriving,
  // user?.educationMedium is undefined, and resolving then would let a stored
  // fallback win over the medium they actually registered with.
  if (!mediumResolved && !authLoading) {
    setMediumResolved(true)
    const preferred = resolvePreferredMedium(user?.educationMedium)
    if (preferred && preferred !== medium) setMedium(preferred)
  }

  const switchMedium = (next: ExamMediumKey) => {
    if (next === medium) return
    setMediumResolved(true)
    setMedium(next)
    // Remember the switch so the next visit opens the same way.
    storeMedium(next)
  }

  const handleStartTest = async (test: MockTestListItem) => {
    if (!test.is_free && !isPremium) {
      openModal(`mock_test_${test.id}`)
      return
    }

    // Series gate — modules open one at a time.
    if (test.is_sequence_locked && test.progress_status !== 'completed') {
      toast.info(`${moduleName(nextModule)} is next`, {
        description:
          test.module_number != null
            ? `Submit ${moduleName(test.module_number - 1)} to unlock this module.`
            : 'Work through the series in order to unlock this module.',
        duration: 4000,
      })
      return
    }

    // Already completed — go straight to the result.
    if (test.progress_status === 'completed' && test.user_attempt) {
      router.push(`/dsc-sgt/mock-result?attemptId=${test.user_attempt.attempt_id}`)
      return
    }

    toast.loading(`Loading ${test.title}…`, { id: 'mock-start' })
    try {
      const res = await fetch(`/api/dsc-sgt/mock-tests/${test.id}/start`, { method: 'POST' })
      const json = await res.json()

      if (!res.ok || !json.success) {
        if (json.error === 'PREMIUM_REQUIRED') {
          toast.dismiss('mock-start')
          openModal(`mock_test_${test.id}`)
          return
        }
        if (json.error === 'SEQUENCE_LOCKED') {
          // The list was stale — refresh so the gate shows correctly.
          toast.info('Locked for now', {
            id: 'mock-start',
            description: json.message,
          })
          void fetchBatch(1, activeQuery.current)
          setPage(1)
          return
        }
        toast.error(json.error || 'Failed to start test', { id: 'mock-start' })
        return
      }

      toast.success('Launching exam environment…', { id: 'mock-start' })
      router.push(`/dsc-sgt/mock-exam?testId=${test.id}&attemptId=${json.attempt_id}`)
    } catch {
      toast.error('Network error — please try again', { id: 'mock-start' })
    }
  }

