        <div className="flex flex-col items-center justify-center gap-4 py-24">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
          <p className="text-sm text-muted-foreground">Loading modules…</p>
        </div>
      )}

      {/* ── Error ── */}
      {!loading && error && (
        <div className="flex flex-col items-center justify-center gap-4 py-24 text-center">
          <p className="text-sm text-destructive">{error}</p>
          <button
            onClick={() => {
              setTests([])
              setPage(1)
              setError(null)
              setLoading(true)
              void fetchBatch(1, activeQuery.current)
            }}
            className="inline-flex items-center gap-2 rounded-xl border border-border px-4 py-2 text-xs font-semibold text-muted-foreground hover:bg-accent"
          >
            <RefreshCw className="h-4 w-4" /> Try Again
          </button>
        </div>
      )}

      {/* ── Empty ── */}
      {!loading && !error && tests.length === 0 && (
        <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
          <FileCheck2 className="h-10 w-10 text-muted-foreground/40" />
          <p className="text-sm font-medium text-muted-foreground">
            {debouncedSearch
              ? 'No modules match your search.'
              : 'No published modules for this medium yet.'}
          </p>
          {debouncedSearch && (
            <button
              onClick={() => {
                setSearch('')
                setPage(1)
              }}
              className="text-xs text-primary hover:underline"
            >
              Reset filters
            </button>
          )}
        </div>
      )}

      {/* ── Module Cards ── */}
      {!loading && !error && tests.length > 0 && (
        <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
          {tests.map((test) => {
            const status = test.progress_status
            const isCompleted = status === 'completed'
            const isInProgress = status === 'in_progress'

            // Two independent gates. Pro is checked first so each candidate is
            // shown the one that actually blocks them next: a free reader sees
            // the upgrade path, a subscriber sees the series gate.
            const isLocked = !test.is_free && !isPremium
            const isSeriesLocked = !isLocked && test.is_sequence_locked && !isCompleted

            return (
              <div
                key={test.id}
                className={`group relative flex flex-col justify-between rounded-3xl border p-5 transition-all duration-200 ${
                  isLocked
                    ? 'border-border/70 bg-card/60 hover:border-amber-500/40'
                    : isSeriesLocked
                      ? 'border-border/70 bg-card/60'
                      : isCompleted
                        ? 'border-emerald-500/40 bg-card shadow-sm hover:shadow-md'
                        : 'border-border/80 bg-card shadow-sm hover:-translate-y-0.5 hover:border-primary/50 hover:shadow-md'
                }`}
              >
                <div>
                  <div className="flex flex-wrap items-center justify-between gap-2">
                    <div className="flex flex-wrap items-center gap-1.5">
                      <span className="rounded-md border border-primary/30 bg-secondary px-2 py-0.5 text-[11px] font-black text-primary">
                        {moduleLabel(test)}
                      </span>
                      {mediumBadge(test.medium)}
                    </div>

                    <div className="flex items-center gap-1.5">
                      {test.is_free ? (
                        <span className="inline-flex items-center gap-1 rounded-full border border-emerald-500/30 bg-emerald-500/10 px-2.5 py-0.5 text-[11px] font-bold text-emerald-600 dark:text-emerald-400">
                          <CheckCircle2 className="h-3 w-3 text-emerald-500" /> Free
                        </span>
                      ) : isPremium ? (
                        <span className="inline-flex items-center gap-1 rounded-full border border-amber-500/30 bg-amber-500/10 px-2.5 py-0.5 text-[11px] font-bold text-amber-500">
                          <Crown className="h-3 w-3 fill-amber-500" /> Pro
                        </span>
                      ) : (
                        <span className="inline-flex items-center gap-1 rounded-full border border-amber-500/30 bg-amber-500/10 px-2.5 py-0.5 text-[11px] font-bold text-amber-500">
                          <Lock className="h-3 w-3" /> Pro
                        </span>
                      )}
                    </div>
                  </div>

                  <h3 className="mt-3.5 text-sm font-bold leading-snug text-foreground transition-colors group-hover:text-primary dark:group-hover:text-primary sm:text-base">
                    {displayTitle(test.title)}
                  </h3>

                  <div className="mt-2">{statusBadge(status, test)}</div>

                  <div className="mt-4 grid grid-cols-3 gap-2 rounded-2xl border border-border/60 bg-muted/30 p-2.5 text-center text-xs">
                    <div>
                      <span className="text-[11px] text-muted-foreground">Questions</span>
                      <p className="font-bold text-foreground">{test.total_questions}</p>
                    </div>
                    <div className="border-x border-border/60">
                      <span className="text-[11px] text-muted-foreground">Marks</span>
                      <p className="font-bold text-foreground">{test.total_marks} M</p>
                    </div>
                    <div>
                      <span className="text-[11px] text-muted-foreground">Duration</span>
                      <p className="font-bold text-foreground">{test.duration_minutes} Min</p>
                    </div>
                  </div>

                  {isCompleted && test.user_attempt && (
                    <div className="mt-3 flex items-center justify-between rounded-xl border border-emerald-500/20 bg-emerald-500/5 px-3 py-2 text-xs">
                      <span className="flex items-center gap-1 text-muted-foreground">
                        <Trophy className="h-3.5 w-3.5 text-emerald-500" />
                        Best Score
                      </span>
                      <span className="font-bold text-emerald-600 dark:text-emerald-400">
                        {test.user_attempt.score} / {test.total_marks}
                        {test.user_attempt.percentage != null &&
                          ` (${test.user_attempt.percentage.toFixed(1)}%)`}
                      </span>
                    </div>
                  )}
                </div>

                <div className="mt-5 border-t border-border/60 pt-3.5">
                  <button
                    id={`mock-test-btn-${test.id}`}
                    onClick={() => void handleStartTest(test)}
                    className={`flex w-full items-center justify-center gap-2 rounded-2xl py-2.5 text-xs font-bold transition-all ${
                      isLocked
                        ? 'border border-amber-500/40 bg-gradient-to-r from-amber-500/10 to-orange-500/10 text-amber-600 hover:border-amber-500 dark:text-amber-400'
                        : isSeriesLocked
                          ? 'cursor-not-allowed border border-border bg-muted/50 text-muted-foreground'
                          : isCompleted
                            ? 'bg-emerald-600 text-white shadow-sm hover:bg-emerald-700'
                            : isInProgress
                              ? 'bg-primary text-primary-foreground shadow-sm hover:bg-primary'
                              : 'bg-primary text-primary-foreground shadow-sm hover:bg-primary hover:shadow-md active:scale-[0.99]'
                    }`}
                  >
                    {isLocked ? (
                      <>
                        <Lock className="h-3.5 w-3.5" />
                        <span>Unlock with Pro</span>
                      </>
                    ) : isSeriesLocked ? (
                      <>
                        <Lock className="h-3.5 w-3.5" />
                        <span>
                          {test.module_number != null
                            ? `Finish ${moduleName(test.module_number - 1)} first`
                            : 'Locked'}
                        </span>
                      </>
                    ) : isCompleted ? (
                      <>
                        <Award className="h-3.5 w-3.5" />
                        <span>View Result & Analysis</span>
                      </>
                    ) : isInProgress ? (
                      <>
                        <RotateCcw className="h-3.5 w-3.5" />
                        <span>Continue</span>
                      </>
                    ) : (
                      <>
                        <Play className="h-3.5 w-3.5 fill-current" />
                        <span>Start</span>
                      </>
                    )}
                  </button>
                </div>
              </div>
            )
          })}
        </div>
      )}

      {/* ── Infinite scroll sentinel & tail state ── */}
      {!loading && !error && tests.length > 0 && (
        <div ref={sentinelRef} className="mt-8 flex flex-col items-center gap-3 py-4">
          {loadingMore && (
            <span className="inline-flex items-center gap-2 text-xs text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin text-primary" />
              Loading more modules…
            </span>
          )}

          {/* Explicit control as well as the observer — it covers a reader who
              prefers to click, and a browser that never fires the callback. */}
          {!loadingMore && hasMore && (
            <button
              onClick={loadNextBatch}
              className="rounded-full border border-border bg-card px-4 py-2 text-xs font-medium text-muted-foreground transition hover:text-foreground"
            >
              Load more modules
            </button>
          )}

          {!hasMore && (
            <span className="text-xs text-muted-foreground">
              Showing all {totalModules} module{totalModules === 1 ? '' : 's'}.
            </span>
          )}
        </div>
      )}
    </main>
  )
}

'use client'

import * as React from 'react'
import { Moon, Sun } from 'lucide-react'
import { useTheme } from 'next-themes'

export function ModeToggle() {
  const { resolvedTheme, setTheme } = useTheme()
  const [mounted, setMounted] = React.useState(false)

  React.useEffect(() => {
    setMounted(true)
  }, [])

  if (!mounted) {
    return (
      <div className="h-9 w-9 rounded-full border border-border bg-muted/40" />
    )
  }

  const isDark = resolvedTheme === 'dark'

  const toggleTheme = () => {
    setTheme(isDark ? 'light' : 'dark')
  }

  return (
    <button
      onClick={toggleTheme}
      aria-label="Toggle dark and light mode"
      title={isDark ? 'Switch to Light Mode' : 'Switch to Dark Mode'}
      className="relative flex h-9 w-9 items-center justify-center rounded-full border border-border bg-card text-foreground transition-all hover:bg-accent hover:text-accent-foreground focus:outline-none focus-visible:ring-2 focus-visible:ring-ring"
    >
      <Sun className="h-4 w-4 scale-100 rotate-0 transition-all duration-300 dark:scale-0 dark:-rotate-90 text-foreground" />
      <Moon className="absolute h-4 w-4 scale-0 rotate-90 transition-all duration-300 dark:scale-100 dark:rotate-0 text-foreground" />
      <span className="sr-only">Toggle theme</span>
    </button>
  )
}

// ============================================================
// lib/auth/db.ts — Database operations for auth (SERVER ONLY)
// ============================================================
// All DB access goes through the Supabase admin client.
// Uses service-role key to bypass RLS. Never call from client.
// ============================================================

import { randomBytes } from 'node:crypto'
import { supabaseAdmin } from '@/lib/supabase-admin'
import type {
  DbUser,
  DbSession,
  DbDevice,
  GoogleProfile,
  DeviceInfo,
  Platform,
  SecurityEventType,
  PublicDevice,
  LearningGoal,
  EducationMedium,
} from './types'
import { AuthError } from './errors'

// ---- Refresh token expiry -------------------------------------------

const REFRESH_TOKEN_EXPIRES_DAYS = 60

function refreshTokenExpiresAt(): string {
  const d = new Date()
  d.setDate(d.getDate() + REFRESH_TOKEN_EXPIRES_DAYS)
  return d.toISOString()
}

// ---- Users -----------------------------------------------------------

/**
 * Find an existing user by google_id, or create a new one.
 * Uses an upsert on google_id to prevent duplicate accounts.
 *
 * `resolveSupabaseUid` is a thunk rather than a value because obtaining the
 * Supabase UID costs a round trip to Supabase Auth (which in turn calls
 * Google). Only a brand-new row needs one — for everybody else the column is
 * already populated and re-deriving it just to write back the same value made
 * every single sign-in pay for it. It is awaited lazily, on the create path.
 */
export async function findOrCreateUser(
  profile: GoogleProfile,
  resolveSupabaseUid: () => Promise<string>
): Promise<DbUser> {
  // Try to find existing user by google_id first
  const { data: existing, error: selectErr } = await supabaseAdmin
    .from('users')
    .select('*')
    .eq('google_id', profile.googleId)
    .maybeSingle()

  if (selectErr) {
    console.error('[DB] findOrCreateUser select error:', selectErr)
    throw new AuthError('INTERNAL_ERROR', 500)
  }

  if (existing) {
    // Google rarely changes a name or a photo, so writing them back on every
    // sign-in was a round trip that almost always stored what was already
    // there. Skip it unless something actually differs.
    const row = existing as DbUser
    if (row.name === profile.name && row.avatar_url === profile.avatarUrl) {
      return row
    }

    const { data: updated, error: updateErr } = await supabaseAdmin
      .from('users')
      .update({
        name: profile.name,
        avatar_url: profile.avatarUrl,
      })
      .eq('id', row.id)
      .select('*')
      .single()

    if (updateErr) {
      console.error('[DB] findOrCreateUser update error:', updateErr)
      // Non-fatal: return existing data
      return row
    }
    return updated as DbUser
  }

  // Create new user
  const { data: created, error: insertErr } = await supabaseAdmin
    .from('users')
    .insert({
      supabase_uid: await resolveSupabaseUid(),
      google_id: profile.googleId,
      email: profile.email,
      name: profile.name,
      avatar_url: profile.avatarUrl,
      account_type: 'FREE',
      subscription_status: 'NONE',
      session_version: 1,
    })
    .select('*')
    .single()

  if (insertErr) {
    // Handle race condition: another request created the user
    if (insertErr.code === '23505') {
      const { data: race } = await supabaseAdmin
        .from('users')
        .select('*')
        .eq('google_id', profile.googleId)
        .single()
      if (race) return race as DbUser
    }
    console.error('[DB] findOrCreateUser insert error:', insertErr)
    throw new AuthError('INTERNAL_ERROR', 500)
  }

  return created as DbUser
}

/**
 * Fetch a user by their internal ID.
 */
export async function getUserById(userId: string): Promise<DbUser | null> {
  const { data, error } = await supabaseAdmin
    .from('users')
    .select('*')
    .eq('id', userId)
    .maybeSingle()

  if (error) {
    console.error('[DB] getUserById error:', error)
    return null
  }
  return data as DbUser | null
}

/**
 * Update onboarding fields and mark onboarding as completed.
 * Sets learning_goals, education_medium, and onboarding_completed = true atomically.
 */
export async function updateOnboarding(
  userId: string,
  learningGoals: LearningGoal[],
  educationMedium: EducationMedium
): Promise<DbUser> {
  const { data, error } = await supabaseAdmin
    .from('users')
    .update({
      learning_goals: learningGoals,
      education_medium: educationMedium,
      onboarding_completed: true,
    })
    .eq('id', userId)
    .select('*')
    .single()

  if (error) {
    console.error('[DB] updateOnboarding error:', error)
    throw new AuthError('INTERNAL_ERROR', 500, 'Failed to save onboarding data')
  }

  return data as DbUser
}

/**
 * Update the editable parts of a profile.
 *
 * Only the fields present on `patch` are written, so a caller changing just
 * the display name cannot accidentally blank out study preferences. Identity
 * fields (email, google_id, avatar) come from Google and are never writable
 * here; neither are role or subscription, which are not the user's to set.
 */
export async function updateUserProfile(
  userId: string,
  patch: {
    name?: string | null
    learningGoals?: LearningGoal[]
    educationMedium?: EducationMedium
  }
): Promise<DbUser> {
  const update: Record<string, unknown> = {}
  if ('name' in patch) update.name = patch.name
  if (patch.learningGoals) update.learning_goals = patch.learningGoals
  if (patch.educationMedium) update.education_medium = patch.educationMedium

  if (Object.keys(update).length === 0) {
    const existing = await getUserById(userId)
    if (!existing) throw new AuthError('INTERNAL_ERROR', 500, 'User not found')
    return existing
  }

  const { data, error } = await supabaseAdmin
    .from('users')
    .update(update)
    .eq('id', userId)
    .select('*')
    .single()

  if (error) {
    console.error('[DB] updateUserProfile error:', error)
    throw new AuthError('INTERNAL_ERROR', 500, 'Failed to save profile')
  }

  return data as DbUser
}

// ---- Devices ---------------------------------------------------------

/**
 * Upsert device record. Creates on first login; updates stats on subsequent logins.
 */
export async function upsertDevice(
  userId: string,
  deviceInfo: DeviceInfo,
  ipHash: string
): Promise<void> {
  const { error } = await supabaseAdmin.rpc('upsert_device', {
    p_user_id: userId,
    p_device_id: deviceInfo.deviceId,
    p_platform: deviceInfo.platform,
    p_user_agent: deviceInfo.userAgent,
    p_ip_hash: ipHash,
  })

  if (error) {
    // RPC not available — use manual upsert
    const { error: upsertErr } = await supabaseAdmin
      .from('devices')
      .upsert(
        {
          user_id: userId,
          device_id: deviceInfo.deviceId,
          platform: deviceInfo.platform,
          user_agent: deviceInfo.userAgent,
          ip_hash: ipHash,
          last_login_at: new Date().toISOString(),
        },
        {
          onConflict: 'user_id,device_id',
          ignoreDuplicates: false,
        }
      )

    if (upsertErr) {
      console.error('[DB] upsertDevice error:', upsertErr)
      // Non-fatal: continue login even if device tracking fails
    }
  }
}

/**
 * Get all known devices for a user, joined with their latest session status.
 */
export async function getUserDevices(userId: string): Promise<PublicDevice[]> {
  const { data, error } = await supabaseAdmin
    .from('devices')
    .select(`
      device_id,
      platform,
      first_login_at,
      last_login_at,
      login_count
    `)
    .eq('user_id', userId)
    .order('last_login_at', { ascending: false })

  if (error) {
    console.error('[DB] getUserDevices error:', error)
    return []
  }

  // Fetch latest session for each device to get status
  const devices = data as DbDevice[]
  const result: PublicDevice[] = await Promise.all(
    devices.map(async (device) => {
      const { data: sessionData } = await supabaseAdmin
        .from('sessions')
        .select('status, last_activity_at')
        .eq('user_id', userId)
        .eq('device_id', device.device_id)
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle()

      return {
        deviceId: device.device_id,
        platform: device.platform,
        firstLoginAt: device.first_login_at,
        lastLoginAt: device.last_login_at,
        loginCount: device.login_count,
        lastActivityAt: sessionData?.last_activity_at ?? null,
        currentSessionStatus: sessionData?.status ?? null,
      }
    })
  )

  return result
}

// ---- Sessions --------------------------------------------------------

/**
 * Revoke the current active session for a user.
 * Called inside a transaction before creating the new session.
 */
export async function revokeActiveSession(
  userId: string,
  reason: string
): Promise<void> {
  const { error } = await supabaseAdmin
    .from('sessions')
    .update({
      status: 'REVOKED',
      revoked_at: new Date().toISOString(),
      revocation_reason: reason,
    })
    .eq('user_id', userId)
    .eq('status', 'ACTIVE')

  if (error) {
    console.error('[DB] revokeActiveSession error:', error)
    throw new AuthError('INTERNAL_ERROR', 500)
  }
}

/**
 * Create a new ACTIVE session.
 * The partial unique index guarantees only one active session exists per user.
 */
export async function createSession(
  userId: string,
  deviceInfo: DeviceInfo,
  ipHash: string,
  refreshTokenHash: string,
  sessionVersion: number
): Promise<DbSession> {
  const { data, error } = await supabaseAdmin
    .from('sessions')
    .insert({
      user_id: userId,
      device_id: deviceInfo.deviceId,
      platform: deviceInfo.platform,
      user_agent: deviceInfo.userAgent,
      ip_hash: ipHash,
      refresh_token_hash: refreshTokenHash,
      session_version: sessionVersion,
      status: 'ACTIVE',
      last_activity_at: new Date().toISOString(),
      expires_at: refreshTokenExpiresAt(),
    })
    .select('*')
    .single()

  if (error) {
    console.error('[DB] createSession error:', error)
    // Unique constraint violation = two concurrent logins race
    if (error.code === '23505') {
      throw new AuthError('INTERNAL_ERROR', 409, 'Session conflict — please retry login')
    }
    throw new AuthError('INTERNAL_ERROR', 500)
  }

  return data as DbSession
}

/**
 * Find a session by its refresh token hash.
 * Used during token refresh. Returns null if not found.
 */
export async function findSessionByRefreshTokenHash(
  tokenHash: string
): Promise<(DbSession & { user: DbUser }) | null> {
  const { data, error } = await supabaseAdmin
    .from('sessions')
    .select(`*, user:users(*)`)
    .eq('refresh_token_hash', tokenHash)
    .maybeSingle()

  if (error) {
    console.error('[DB] findSessionByRefreshTokenHash error:', error)
    return null
  }

  return data as (DbSession & { user: DbUser }) | null
}

/**
 * Rotate the refresh token: replace the stored hash with a new one.
 * Atomically updates last_activity_at too.
 */
/**
 * Find the session whose PREVIOUS refresh token matches this hash.
 *
 * A hit means the caller presented a token that has already been rotated away
 * — the signature of refresh-token theft: whoever refreshed second is holding
 * a stale token, and one of the two parties is an attacker. Since we cannot
 * tell which, the safe response is to revoke the whole family.
 */
export async function findSessionByPreviousRefreshTokenHash(
  tokenHash: string
): Promise<(DbSession & { user: DbUser }) | null> {
  const { data, error } = await supabaseAdmin
    .from('sessions')
    .select(`*, user:users(*)`)
    .eq('previous_refresh_token_hash', tokenHash)
    .maybeSingle()

  if (error) {
    console.error('[DB] findSessionByPreviousRefreshTokenHash error:', error)
    return null
  }
  return data as (DbSession & { user: DbUser }) | null
}

/**
 * Contain a detected refresh-token reuse.
 *
 * Revokes every session for the user AND bumps session_version, which kills all
 * outstanding access tokens too (validateSession compares the token's `sv`
 * against users.session_version on every request). Both halves are required:
 * revoking sessions alone would leave an attacker's 30-day access token valid.
 */
export async function revokeSessionFamily(userId: string, reason: string): Promise<void> {
  // refresh_token_hash is NOT NULL, so the hash is overwritten with an
  // unguessable value rather than nulled — that both satisfies the constraint
  // and makes the stolen token unmatchable, instead of relying only on the
  // status check downstream.
  const deadHash = `revoked:${randomBytes(32).toString('hex')}`

  const { error } = await supabaseAdmin
    .from('sessions')
    .update({
      status: 'REVOKED',
      revoked_at: new Date().toISOString(),
      revocation_reason: reason,
      refresh_token_hash: deadHash,
      previous_refresh_token_hash: null,
    })
    .eq('user_id', userId)
    .neq('status', 'REVOKED')

  // Never fail silently here: this is the containment step. An earlier version
  // set refresh_token_hash to null, violated the NOT NULL constraint, and the
  // unchecked error meant sessions stayed ACTIVE while the caller believed the
  // family had been revoked.
  if (error) {
    console.error('[DB] revokeSessionFamily FAILED — sessions remain active:', error)
    throw new AuthError('INTERNAL_ERROR', 500)
  }

  await incrementSessionVersion(userId)
}

export async function rotateRefreshToken(
  sessionId: string,
  newTokenHash: string,
  previousTokenHash?: string
): Promise<DbSession> {
  const nowIso = new Date().toISOString()

  // The replaced hash is retained for ONE generation so that a later
  // presentation of the old token can still be attributed to this session.
  // Without it, reuse detection cannot identify a user and therefore cannot
  // revoke anything.
  const { data, error } = await supabaseAdmin
    .from('sessions')
    .update({
      refresh_token_hash: newTokenHash,
      previous_refresh_token_hash: previousTokenHash ?? null,
      rotated_at: nowIso,
      last_activity_at: nowIso,
    })
    .eq('id', sessionId)
    .select('*')
    .single()

  if (error) {
    console.error('[DB] rotateRefreshToken error:', error)
    throw new AuthError('INTERNAL_ERROR', 500)
  }

  return data as DbSession
}

/**
 * Revoke a specific session by ID.
 */
export async function revokeSession(
  sessionId: string,
  reason: string
): Promise<void> {
  const { error } = await supabaseAdmin
    .from('sessions')
    .update({
      status: 'REVOKED',
      revoked_at: new Date().toISOString(),
      revocation_reason: reason,
    })
    .eq('id', sessionId)

  if (error) {
    console.error('[DB] revokeSession error:', error)
    throw new AuthError('INTERNAL_ERROR', 500)
  }
}

/**
 * Revoke ALL active sessions for a user (logout-all).
 */
export async function revokeAllUserSessions(
  userId: string,
