import { supabaseAdmin } from '@/lib/supabase-admin'
import { isUserPremium } from '@/lib/auth/session'
import type { DbUser } from '@/lib/auth/types'
import type {
  PracticeMedium,
  PracticeMode,
  PracticeQuestion,
  PracticeFilterState,
  PracticeSession,
  PracticeResultSummary,
  TopicPerformance,
  WeakAreaRecommendation,
  UserAnswerRecord,
  PracticeHistoryItem,
} from '@/types/practice'
import { SEED_QUESTIONS } from './seed-questions'
import { loadCandidatePool, hydrateQuestions } from './question-loader'
import {
  filterQuestionPool,
  selectSmartQuestions,
  extractFilterOptions,
  type UserAttemptHistory,
} from './engine'
