  getAllSubjectProviders,
  getSubjectProvider,
} from './subjects'

// In-memory sessions cache for fallback and instant session continuity
const activeSessionsCache: Map<string, PracticeSession> = new Map()

/**
 * Strip the answer key from a session that is still in progress.
 *
 * The previous rule only masked when `feedback_mode === 'end'`, and the default
 * mode is 'instant' — so in the normal flow the client received
 * `correct_answer` and `explanation` for every question BEFORE answering any of
 * them. Anyone could read the whole answer key out of DevTools, and a Free user
 * could farm answers 25 at a time.
 *
 * Instant feedback does not need this: the client already receives per-question
 * feedback from POST /sessions/[id]/answer, which reveals the answer only for a
 * question the user has just submitted. Masking here removes the bulk leak
 * without changing what the exam UI can display.
 *
 * A completed session is returned unmasked — that is the review screen.
 */
export function maskSessionAnswers(session: PracticeSession): PracticeSession {
  if (session.status !== 'in_progress') return session

  return {
    ...session,
    user_answers: Object.fromEntries(Object.entries(session.user_answers).map(([id, answer]) => {
      if (session.feedback_mode === 'instant') return [id, answer]
      const { correct_answer, explanation, ...safe } = answer
      void correct_answer
      void explanation
      return [id, safe]
    })),
    questions: session.questions.map((q) => {
      const { correct_answer, explanation, ...rest } = q
      void correct_answer
      void explanation
      return rest as PracticeQuestion
    }),
  }
}

/**
 * Ownership guard for a practice session.
 *
 * A session belongs to exactly one user. Every accessor must prove ownership,
 * because a session id alone is not an authorisation token — it appears in the
 * URL, in browser history, in referrers and in logs.
 *
 * This guard exists specifically because `activeSessionsCache` is keyed by
 * session id only: a DB query can be scoped with `.eq('user_id', ...)`, but a
 * cache hit bypasses the database entirely and would re-introduce the IDOR.
 * Both paths therefore run through here.
 *
 * Returns null rather than throwing so callers surface a 404 and never confirm
 * that someone else's session exists.
 */
function ownedOrNull(
  session: PracticeSession | null | undefined,
  userId: string
): PracticeSession | null {
  if (!session) return null
  if (!userId) return null
  if (session.user_id !== userId) return null
  return session
}

/**
 * Fetch all available practice questions from database across subject providers.
 * Subject providers handle dedicated tables (e.g. english_subject_questions, telugu_subject_questions)
 * and unified dsc_practice_questions seamlessly.
 */
export async function getAllPracticeQuestions(
  medium?: PracticeMedium,
  subject?: string
): Promise<PracticeQuestion[]> {
  let questions: PracticeQuestion[] = []

  if (subject && subject !== 'All') {
    const provider = getSubjectProvider(subject)
    if (provider) {
      questions = await provider.fetchQuestions(medium)
    } else {
      // Fallback query by subject
      const providers = getAllSubjectProviders()
      const results = await Promise.all(providers.map((p) => p.fetchQuestions(medium)))
      questions = results.flat()
    }
  } else {
    // Fetch from all subject providers in parallel
    const providers = getAllSubjectProviders()
    const results = await Promise.all(providers.map((p) => p.fetchQuestions(medium)))
    questions = results.flat()
  }

  if (medium) {
    return questions.filter((q) => q.medium.toLowerCase() === medium.toLowerCase())
  }

  return questions
}

/**
 * Load user's attempt history for question scoring
 */
export async function getUserAttemptHistory(
  userId: string | null
): Promise<Record<string, UserAttemptHistory>> {
  if (!userId) return {}

  try {
    const { data, error } = await supabaseAdmin
      .from('question_progress')
      .select('*')
      .eq('user_id', userId)

    if (!error && data) {
      const history: Record<string, UserAttemptHistory> = {}
      data.forEach((row: any) => {
        const lastAt = row.last_attempted_at ? new Date(row.last_attempted_at).getTime() : 0
        const isRecent = Date.now() - lastAt < 24 * 60 * 60 * 1000 // Last 24 hours
        history[row.question_id] = {
          question_id: row.question_id,
          attempt_count: row.attempt_count || 0,
          correct_count: row.correct_count || 0,
          incorrect_count: row.incorrect_count || 0,
          last_attempted_at: row.last_attempted_at,
          is_recently_seen: isRecent,
        }
      })
      return history
    }
  } catch (err) {
    console.warn('[Practice DB] Error fetching question progress:', err)
  }

  return {}
}

/**
 * Calculate user weak topics (< 65% accuracy)
 */
export async function getUserWeakTopics(userId: string | null): Promise<Set<string>> {
  const weakSet = new Set<string>()
  if (!userId) return weakSet

  try {
    const { data, error } = await supabaseAdmin
      .from('question_progress')
      .select('topic, correct_count, attempt_count')
      .eq('user_id', userId)

    if (!error && data) {
      const topicStats: Record<string, { correct: number; total: number }> = {}
      data.forEach((row: any) => {
        const t = row.topic?.toLowerCase()
        if (t) {
          if (!topicStats[t]) topicStats[t] = { correct: 0, total: 0 }
          topicStats[t].correct += row.correct_count || 0
          topicStats[t].total += row.attempt_count || 0
        }
      })

      Object.entries(topicStats).forEach(([topic, stat]) => {
        if (stat.total >= 3 && stat.correct / stat.total < 0.65) {
          weakSet.add(topic)
        }
      })
    }
  } catch (err) {
    console.warn('[Practice DB] Error computing weak topics:', err)
  }

  return weakSet
}

/**
 * Create a new Practice Session
 */
export async function createPracticeSession(
  filter: PracticeFilterState,
  userId: string | null
): Promise<PracticeSession> {
  // Candidates come back light (six columns) and already narrowed in SQL.
  // filterQuestionPool still decides what matches — SQL only reduces how much
  // has to be fetched to ask it. See lib/practice/question-loader.ts.
  const { pool: candidates, alreadyHydrated } = await loadCandidatePool(filter)
  const pool = filterQuestionPool(candidates, filter)

  // Load user attempt history & weak areas
  const [history, weakTopics] = await Promise.all([
    getUserAttemptHistory(userId),
    getUserWeakTopics(userId),
  ])

  // Smart Question Selection
  const requestedCount = Math.min(filter.question_count, pool.length || filter.question_count)
  const chosen = selectSmartQuestions(
    pool.length > 0 ? pool : candidates,
    requestedCount,
    filter.mode,
    history,
    weakTopics
  )

  // Only now fetch stems, options and explanations, and only for these. The
  // single-subject path already returned complete rows, so it skips this.
  const selectedQuestions = alreadyHydrated ? chosen : await hydrateQuestions(chosen)

  const sessionId = crypto.randomUUID()
  const questionIds = selectedQuestions.map((q) => q.question_id || q.id)

  const session: PracticeSession = {
    id: sessionId,
    user_id: userId,
    medium: filter.medium,
    subject: filter.subject,
    class_levels: filter.class_levels,
    topics: filter.topics,
    subtopics: filter.subtopics,
    difficulty: filter.difficulty,
    mode: filter.mode,
    feedback_mode: filter.feedback_mode,
    has_timer: filter.has_timer,
    duration_seconds: filter.has_timer ? (filter.duration_minutes || 30) * 60 : 0,
    question_count: selectedQuestions.length,
    question_ids: questionIds,
    questions: selectedQuestions,
    user_answers: {},
    time_spent_seconds: 0,
    score: 0,
    accuracy_pct: 0,
    status: 'in_progress',
    started_at: new Date().toISOString(),
  }

  // Cache in-memory during active solving
  activeSessionsCache.set(sessionId, session)

  // Persist session record into Supabase immediately so free trial attempt is registered
  if (userId) {
    try {
      const { error } = await supabaseAdmin.from('practice_sessions').insert({
        id: session.id,
        user_id: session.user_id,
        medium: session.medium,
        subject: session.subject,
        class_levels: session.class_levels,
        topics: session.topics,
        subtopics: session.subtopics,
        difficulty: session.difficulty,
        mode: session.mode,
        feedback_mode: session.feedback_mode,
        has_timer: session.has_timer,
        duration_seconds: session.duration_seconds,
        question_count: session.question_count,
        question_ids: session.question_ids,
        user_answers: {},
        time_spent_seconds: 0,
        score: 0,
        accuracy_pct: 0,
        status: 'in_progress',
        started_at: session.started_at,
      })
      if (error) throw error
    } catch (err) {
      activeSessionsCache.delete(sessionId)
      throw new Error('Could not save practice session. Please try again.', { cause: err })
    }
  }

  // The in-memory cache keeps the FULL session because server-side grading
  // needs the answer key; only the value returned to the caller is masked.
  return maskSessionAnswers(session)
}

/**
 * Abandon a practice session.
 * For free users: marks the session as completed so the free trial is finished.
 * For pro users: discards without saving.
 */
export async function abandonPracticeSession(
  sessionId: string,
  userId: string
): Promise<boolean> {
  // Ownership first: this function COMPLETES a free user's one lifetime session
  // and HARD-DELETES a Pro user's. Previously it took only a session id, so
  // anyone holding an id could burn or destroy another user's session.
  const session = ownedOrNull(activeSessionsCache.get(sessionId), userId)

  if (!session) {
    const { data: dbSession } = await supabaseAdmin
      .from('practice_sessions')
      .select('id')
      .eq('id', sessionId)
      .eq('user_id', userId)
      .maybeSingle()

    // Not ours (or gone) — do nothing at all.
    if (!dbSession) return false
  }

  activeSessionsCache.delete(sessionId)

  {
    try {
      const { data: userRow } = await supabaseAdmin
        .from('users')
        .select('*')
        .eq('id', userId)
        .single()

      const isPro = isUserPremium(userRow)
      if (!isPro) {
        // Free user: exiting/abandoning completes and finishes the free trial session!
        if (session) {
          await supabaseAdmin
            .from('practice_sessions')
            .upsert({
              id: session.id,
              user_id: session.user_id,
              medium: session.medium,
              subject: session.subject,
              class_levels: session.class_levels,
              topics: session.topics,
              subtopics: session.subtopics,
              difficulty: session.difficulty,
              mode: session.mode,
              feedback_mode: session.feedback_mode,
              has_timer: session.has_timer,
              duration_seconds: session.duration_seconds,
              question_count: session.question_count,
              question_ids: session.question_ids,
              user_answers: session.user_answers || {},
              time_spent_seconds: session.time_spent_seconds || 0,
              score: session.score || 0,
              accuracy_pct: session.accuracy_pct || 0,
              status: 'completed',
              started_at: session.started_at,
              completed_at: new Date().toISOString(),
            })
        } else {
          await supabaseAdmin
            .from('practice_sessions')
            .update({
              status: 'completed',
              completed_at: new Date().toISOString(),
            })
            .eq('id', sessionId)
            .eq('user_id', userId)
        }
        return true
      }
    } catch (err) {
      console.warn('[Practice DB] Error finalizing free session in abandon:', err)
    }
  }

  // Pro users: purge — scoped to the owner so one user can never delete
  // another user's row.
  try {
    await supabaseAdmin
      .from('practice_sessions')
      .delete()
      .eq('id', sessionId)
      .eq('user_id', userId)
  } catch (err) {
    // Ignore cleanup errors
  }

  return true
}

/**
 * Get Practice Session by ID
 */
export async function getPracticeSessionById(
  sessionId: string,
  userId: string,
  maskAnswers = true
): Promise<PracticeSession | null> {
  // Cache hits must be ownership-checked too — see ownedOrNull.
  // Durable state is authoritative across serverless instances and mobile retries.
  let session: PracticeSession | undefined

  if (!session) {
    try {
      const { data, error } = await supabaseAdmin
        .from('practice_sessions')
        .select('*')
        .eq('id', sessionId)
        .eq('user_id', userId)
        .maybeSingle()

      if (!error && data) {
        // Re-attach questions
        const cached = ownedOrNull(activeSessionsCache.get(sessionId), userId)
        const allQuestions = cached?.questions ?? await getAllPracticeQuestions(data.medium, data.subject)
        const questionMap = new Map(allQuestions.map((q) => [q.question_id || q.id, q]))
        const loadedQuestions = (data.question_ids || [])
          .map((id: string) => questionMap.get(id))
          .filter(Boolean) as PracticeQuestion[]

        session = {
          ...data,
          questions: loadedQuestions,
        }
        activeSessionsCache.set(sessionId, session!)
      }
    } catch (err) {
      console.warn('[Practice DB] Error reading practice_session:', err)
    }
  }

  if (!session) return null

  // An in-progress session NEVER carries its answer key, whatever the feedback
  // mode. See maskSessionAnswers.
  return maskAnswers ? maskSessionAnswers(session) : session
}

/**
 * Record an answer durably before acknowledging it to web/mobile clients.
 */
export async function recordQuestionAnswer(
  sessionId: string,
  questionId: string,
  selectedAnswer: 'A' | 'B' | 'C' | 'D' | null,
  timeTakenSeconds = 0,
  markedForReview = false,
  userId: string
): Promise<{
  is_correct: boolean
  correct_answer: string
  explanation: string | null
  session: PracticeSession
}> {
  const session = await getPracticeSessionById(sessionId, userId, false)
  if (!session) {
    throw new Error('Practice session not found')
  }
  if (session.status !== 'in_progress') throw new Error('Practice session is no longer active')
  if (selectedAnswer !== null && !['A', 'B', 'C', 'D'].includes(selectedAnswer)) {
    throw new Error('Invalid selected answer')
  }

  const question = session.questions.find((q) => (q.question_id || q.id) === questionId)
  if (!question) {
    throw new Error('Question not found in session')
  }

  // Validate correctness
  const rawCorrect = (question.correct_answer || '').trim().toUpperCase()
  let isCorrect = false
  if (selectedAnswer) {
    if (rawCorrect === selectedAnswer) isCorrect = true
    else if (rawCorrect.endsWith(selectedAnswer)) isCorrect = true
    else {
      const optMap = {
        A: (question.option_a || '').trim().toLowerCase(),
        B: (question.option_b || '').trim().toLowerCase(),
        C: (question.option_c || '').trim().toLowerCase(),
        D: (question.option_d || '').trim().toLowerCase(),
      }
      if (rawCorrect.toLowerCase() === optMap[selectedAnswer]) isCorrect = true
    }
  }

  const previousTime = session.user_answers[questionId]?.time_taken_seconds ?? 0
  // Replacing the same answer is a retry, not another period of study time.
  session.user_answers[questionId] = {
    question_id: questionId,
    selected_answer: selectedAnswer,
    is_correct: isCorrect,
    time_taken_seconds: timeTakenSeconds,
    marked_for_review: markedForReview,
    answered_at: new Date().toISOString(),
    correct_answer: question.correct_answer,
    explanation: question.explanation,
  }

  // Recalculate score & accuracy
  let correctCount = 0
  let attemptedCount = 0
  Object.values(session.user_answers).forEach((ans) => {
    if (ans.selected_answer) {
      attemptedCount++
      if (ans.is_correct) correctCount++
    }
  })

  session.score = correctCount
  session.accuracy_pct = attemptedCount > 0 ? Math.round((correctCount / attemptedCount) * 100) : 0
  session.time_spent_seconds = Math.max(0, session.time_spent_seconds - previousTime + timeTakenSeconds)

  const { data: saved, error: saveError } = await supabaseAdmin
    .from('practice_sessions')
    .update({ user_answers: session.user_answers, score: session.score,
      accuracy_pct: session.accuracy_pct, time_spent_seconds: session.time_spent_seconds })
    .eq('id', sessionId).eq('user_id', userId).eq('status', 'in_progress')
    .select('id')
  if (saveError || !saved?.length) throw new Error('Could not save answer. Please try again.')

  activeSessionsCache.set(sessionId, session)

  return {
    is_correct: isCorrect,
    correct_answer: question.correct_answer || 'A',
    explanation: question.explanation || null,
    session,
  }
}

/**
 * Submit & complete practice session — ONLY AT THIS POINT IS DATA SAVED TO DB
 */
export async function submitPracticeSession(
  sessionId: string,
  totalTimeSpentSeconds: number,
  userId: string
): Promise<PracticeResultSummary> {
  const session = await getPracticeSessionById(sessionId, userId, false)
  if (!session) {
    throw new Error('Session not found')
  }

  const wasCompleted = session.status === 'completed'
  if (!wasCompleted && session.status !== 'in_progress') throw new Error('Session is no longer active')
  session.completed_at = session.completed_at || new Date().toISOString()
  if (!wasCompleted) session.time_spent_seconds = totalTimeSpentSeconds || session.time_spent_seconds

  const totalQuestions = session.questions.length
  let correctCount = 0
  let incorrectCount = 0
  let skippedCount = 0

  // Topic performance mapping
  const topicStats: Record<string, { total: number; attempted: number; correct: number; incorrect: number }> = {}

  session.questions.forEach((q) => {
    const qId = q.question_id || q.id
    const t = q.topic || 'General'

    if (!topicStats[t]) {
      topicStats[t] = { total: 0, attempted: 0, correct: 0, incorrect: 0 }
    }
    topicStats[t].total++

    const ans = session.user_answers[qId]
    if (!ans || !ans.selected_answer) {
      skippedCount++
    } else if (ans.is_correct) {
      correctCount++
      topicStats[t].attempted++
      topicStats[t].correct++
    } else {
      incorrectCount++
      topicStats[t].attempted++
      topicStats[t].incorrect++
    }
  })

  const attemptedCount = correctCount + incorrectCount
  const score = correctCount
  const accuracyPct = totalQuestions > 0 ? Math.round((score / totalQuestions) * 100) : 0
  const avgTime = totalQuestions > 0 ? Math.round(session.time_spent_seconds / totalQuestions) : 0

  session.score = score
  session.accuracy_pct = accuracyPct

  // Format topic performance
  const topic_breakdown: TopicPerformance[] = Object.entries(topicStats).map(([topic, stat]) => {
    const acc = stat.attempted > 0 ? Math.round((stat.correct / stat.total) * 100) : 0
    return {
      topic,
      total_questions: stat.total,
      attempted: stat.attempted,
      correct: stat.correct,
      incorrect: stat.incorrect,
      accuracy_pct: acc,
      is_weak: acc < 65,
      is_mastered: acc >= 85,
    }
  })

  // Format weak recommendations
  const weak_recommendations: WeakAreaRecommendation[] = topic_breakdown
    .filter((tp) => tp.is_weak || tp.incorrect > 0)
    .map((tp) => ({
      subject: session.subject,
      topic: tp.topic,
      total_attempted: tp.attempted,
      accuracy_pct: tp.accuracy_pct,
      incorrect_count: tp.incorrect,
      recommended_question_count: Math.min(25, Math.max(10, tp.incorrect * 5)),
      action_label: `Practice ${tp.topic} (${tp.accuracy_pct}%)`,
    }))

  // Format review questions
  const questions_review = session.questions.map((q) => {
    const qId = q.question_id || q.id
    const ans = session.user_answers[qId]
    return {
      ...q,
      user_answer: ans?.selected_answer || null,
      is_correct: ans?.is_correct || false,
      is_skipped: !ans?.selected_answer,
      is_marked: ans?.marked_for_review || false,
      correct_answer: q.correct_answer || 'A',
      explanation: q.explanation || null,
      time_taken_seconds: ans?.time_taken_seconds || 0,
    }
  })

  // Claim completion once; repeated results reads must not create new attempts.
  let newlyCompleted = false
  if (!wasCompleted) {
    const { data: claimed, error: completionError } = await supabaseAdmin
      .from('practice_sessions')
      .update({
        id: session.id,
        user_id: session.user_id,
        medium: session.medium,
        subject: session.subject,
        class_levels: session.class_levels,
        topics: session.topics,
        subtopics: session.subtopics,
        difficulty: session.difficulty,
        mode: session.mode,
        feedback_mode: session.feedback_mode,
        has_timer: session.has_timer,
        duration_seconds: session.duration_seconds,
        question_count: session.question_count,
        question_ids: session.question_ids,
        user_answers: session.user_answers,
        time_spent_seconds: session.time_spent_seconds,
        score: session.score,
        accuracy_pct: session.accuracy_pct,
        status: 'completed',
        started_at: session.started_at,
        completed_at: session.completed_at,
      })
      .eq('id', session.id).eq('user_id', userId).eq('status', 'in_progress')
      .select('id')
    if (completionError) throw new Error('Could not submit practice session. Retry safely.')
    newlyCompleted = Boolean(claimed?.length)
  }
  session.status = 'completed'

  // 2. Persist individual question attempts and update mastery progress for user
  if (session.user_id && newlyCompleted) {
    const answeredEntries = Object.values(session.user_answers).filter((a) => a.selected_answer)
    for (const ans of answeredEntries) {
      const q = session.questions.find((item) => (item.question_id || item.id) === ans.question_id)
      if (q) {
        saveAnswerProgressAsync(
          session.user_id,
          session.id,
          q,
          ans.selected_answer,
          ans.is_correct || false,
          ans.time_taken_seconds || 0
        ).catch(() => {})
      }
    }
  }

  activeSessionsCache.set(sessionId, session)

  return {
    session_id: sessionId,
    subject: session.subject,
    medium: session.medium,
    mode: session.mode,
    total_questions: totalQuestions,
    attempted_count: attemptedCount,
    correct_count: correctCount,
    incorrect_count: incorrectCount,
    skipped_count: skippedCount,
    score,
    accuracy_pct: accuracyPct,
    total_time_seconds: session.time_spent_seconds,
    avg_time_per_question_seconds: avgTime,
    topic_breakdown,
    weak_recommendations,
    questions_review,
  }
}

/**
 * Async helper to record attempt and update mastery progress in DB on SUBMIT ONLY
 */
async function saveAnswerProgressAsync(
  userId: string,
  sessionId: string,
  question: PracticeQuestion,
  selectedAnswer: string | null,
  isCorrect: boolean,
  timeTaken: number
) {
  try {
    const qId = question.question_id || question.id

    // 1. Record in question_attempts
    await supabaseAdmin.from('question_attempts').insert({
      session_id: sessionId,
      user_id: userId,
      question_id: qId,
      subject: question.subject,
      topic: question.topic,
      subtopic: question.subtopic,
      difficulty: question.difficulty,
      selected_answer: selectedAnswer,
      is_correct: isCorrect,
      time_taken_seconds: timeTaken,
    })

    // 2. Upsert progress in question_progress
    const { data: existing } = await supabaseAdmin
      .from('question_progress')
      .select('*')
      .eq('user_id', userId)
      .eq('question_id', qId)
      .single()

    if (existing) {
      const attempts = (existing.attempt_count || 0) + 1
      const corrects = (existing.correct_count || 0) + (isCorrect ? 1 : 0)
      const incorrects = (existing.incorrect_count || 0) + (isCorrect ? 0 : 1)
      const mastery = Math.round((corrects / attempts) * 100)

      await supabaseAdmin
        .from('question_progress')
        .update({
          attempt_count: attempts,
          correct_count: corrects,
          incorrect_count: incorrects,
          last_attempted_at: new Date().toISOString(),
          last_correct_at: isCorrect ? new Date().toISOString() : existing.last_correct_at,
          mastery_score: mastery,
        })
        .eq('id', existing.id)
    } else {
      await supabaseAdmin.from('question_progress').insert({
        user_id: userId,
        question_id: qId,
        subject: question.subject,
        topic: question.topic,
        subtopic: question.subtopic,
        attempt_count: 1,
        correct_count: isCorrect ? 1 : 0,
        incorrect_count: isCorrect ? 0 : 1,
        last_attempted_at: new Date().toISOString(),
        last_correct_at: isCorrect ? new Date().toISOString() : null,
        mastery_score: isCorrect ? 100 : 0,
      })
    }
  } catch (err) {
    console.warn('[Practice DB] Error recording attempt in DB:', err)
  }
}

/**
 * Fetch past practice sessions for user history — ONLY COMPLETED TESTS
 */
export async function getPracticeHistory(userId: string | null): Promise<PracticeHistoryItem[]> {
  if (!userId) {
    return Array.from(activeSessionsCache.values())
      .filter((s) => s.status === 'completed')
      .map((s) => ({
        id: s.id,
        medium: s.medium,
        subject: s.subject,
        mode: s.mode,
        topics: s.topics,
        question_count: s.question_count,
        score: s.score,
        accuracy_pct: s.accuracy_pct,
        time_spent_seconds: s.time_spent_seconds,
        started_at: s.started_at,
        completed_at: s.completed_at || null,
        status: s.status,
      }))
  }

  try {
    const { data, error } = await supabaseAdmin
      .from('practice_sessions')
      .select('*')
      .eq('user_id', userId)
      .eq('status', 'completed')
      .order('started_at', { ascending: false })
      .limit(30)

    if (!error && data && data.length > 0) {
      return data as PracticeHistoryItem[]
    }
  } catch (err) {
    console.warn('[Practice DB] Error fetching history:', err)
  }

  return Array.from(activeSessionsCache.values())
    .filter((s) => s.status === 'completed')
    .map((s) => ({
      id: s.id,
      medium: s.medium,
      subject: s.subject,
      mode: s.mode,
      topics: s.topics,
      question_count: s.question_count,
      score: s.score,
      accuracy_pct: s.accuracy_pct,
      time_spent_seconds: s.time_spent_seconds,
      started_at: s.started_at,
      completed_at: s.completed_at || null,
      status: s.status,
    }))
}

/**
 * Count completed or active practice sessions for a user (from database + in-memory cache).
 * For free accounts, once a test is started or completed, it counts as consumed.
 */
export async function getUserCompletedPracticeSessionCount(userId: string | null): Promise<number> {
  if (!userId) return 0

  let dbCount = 0
  try {
    const { count, error } = await supabaseAdmin
      .from('practice_sessions')
      .select('id', { count: 'exact', head: true })
      .eq('user_id', userId)

    if (!error && typeof count === 'number') {
      dbCount = count
    }
  } catch (err) {
    console.warn('[Practice DB] Error checking user practice sessions count:', err)
  }

  let memCount = 0
  for (const session of activeSessionsCache.values()) {
    if (session.user_id === userId) {
      memCount++
    }
  }

  return Math.max(dbCount, memCount)
}

export interface PracticeQuotaResult {
  allowed: boolean
  reason?: string
  isPremium: boolean
  completedSessions: number
  maxQuestions: number
}

/**
 * Determine if a user can create a practice session based on Pro subscription status.
 * Free tier accounts:
 *   - Only 1 practice session per account ever
 *   - Max 25 questions per session
 * Pro tier accounts:
 *   - Unlimited practice sessions
 *   - Unlimited questions
 */
export async function canUserCreatePracticeSession(
  user: DbUser | null | undefined
): Promise<PracticeQuotaResult> {
  if (!user) {
    return {
      allowed: false,
      reason: 'Please sign in to access your practice session.',
      isPremium: false,
      completedSessions: 0,
      maxQuestions: 25,
    }
  }

  const isPro = isUserPremium(user)
  if (isPro) {
    return {
      allowed: true,
      isPremium: true,
      completedSessions: 0,
      maxQuestions: 150,
    }
  }

  // Free Tier account: check completed sessions
  const completedSessions = await getUserCompletedPracticeSessionCount(user.id)
  if (completedSessions >= 1) {
    return {
      allowed: false,
      reason: 'Free practice limit reached: you can only take 1 practice session on the free plan. Upgrade to Pro for unlimited practice sessions across all subjects!',
      isPremium: false,
      completedSessions,
      maxQuestions: 25,
    }
  }

  return {
    allowed: true,
    isPremium: false,
    completedSessions,
    maxQuestions: 25,
  }
}

// ============================================================
// lib/practice/engine.ts — Smart Question Selection Engine
// ============================================================
// Implements intelligent filtering, dynamic priority scoring,
// topic & difficulty balancing, and fallbacks.
// ============================================================

import type {
  PracticeMedium,
  PracticeMode,
  PracticeQuestion,
  PracticeFilterState,
  DynamicFilterOptions,
} from '@/types/practice'
import { SEED_QUESTIONS } from './seed-questions'
import { getAllSubjectMetadata } from './subjects'

export interface QuestionCandidate extends PracticeQuestion {
  selection_score?: number
}

export interface UserAttemptHistory {
  question_id: string
  attempt_count: number
  correct_count: number
  incorrect_count: number
  last_attempted_at?: string
  is_recently_seen?: boolean
}

// Configurable scoring weights
export const PRIORITY_WEIGHTS = {
  never_attempted: 10,
  previously_incorrect: 8,
  weak_topic: 5,
  correct_once: 3,
  correct_repeatedly: 1,
  recently_attempted: -5,
  frequently_seen: -3,
}

/**
 * Filter pool of questions based on user filter parameters.
 */
export function filterQuestionPool(
  questions: PracticeQuestion[],
  filter: Partial<PracticeFilterState>
): PracticeQuestion[] {
  return questions.filter((q) => {
    // 1. Medium check (Strict separation)
    if (filter.medium && q.medium.toLowerCase() !== filter.medium.toLowerCase()) {
      return false
    }

    // 2. Subject check
    if (
      filter.subject &&
      filter.subject !== 'All' &&
      q.subject.toLowerCase() !== filter.subject.toLowerCase()
    ) {
      const isGKFilter =
        filter.subject.toLowerCase().includes('gk') ||
        filter.subject.toLowerCase().includes('general knowledge') ||
        filter.subject.toLowerCase().includes('current affairs')
      const isGKQuestion =
        q.subject.toLowerCase().includes('gk') ||
        q.subject.toLowerCase().includes('general knowledge') ||
        q.subject.toLowerCase().includes('current affairs')
      if (isGKFilter && isGKQuestion) {
        return true
      }

      const isPedFilter =
        filter.subject.toLowerCase().includes('pedagogy') ||
        filter.subject.toLowerCase().includes('educational psychology') ||
        filter.subject.toLowerCase().includes('perspectives in education') ||
        filter.subject.toLowerCase().includes('cdp')
      const isPedQuestion =
        q.subject.toLowerCase().includes('pedagogy') ||
        q.subject.toLowerCase().includes('educational psychology') ||
        q.subject.toLowerCase().includes('perspectives in education') ||
        q.subject.toLowerCase().includes('cdp')
      if (isPedFilter && isPedQuestion) {
        return true
      }

      return false
    }

    // 3. Class level check
    if (
      filter.class_levels &&
      filter.class_levels.length > 0 &&
      !filter.class_levels.includes('All') &&
      !filter.class_levels.includes('All Classes')
    ) {
      const matchesClass = filter.class_levels.some(
        (lvl) =>
          q.class_level.toLowerCase().includes(lvl.toLowerCase()) ||
          lvl.toLowerCase().includes(q.class_level.toLowerCase())
      )
      if (!matchesClass) return false
    }

    // 4. Topic check
    if (
      filter.topics &&
      filter.topics.length > 0 &&
      !filter.topics.includes('All') &&
      !filter.topics.includes('All Topics')
    ) {
      const matchesTopic = filter.topics.some(
        (t) =>
          q.topic.toLowerCase() === t.toLowerCase() ||
          q.topic.toLowerCase().includes(t.toLowerCase())
      )
      if (!matchesTopic) return false
    }

    // 5. Subtopic check
    if (
      filter.subtopics &&
      filter.subtopics.length > 0 &&
      !filter.subtopics.includes('All') &&
      !filter.subtopics.includes('All Subtopics')
    ) {
      if (!q.subtopic) return false
      const matchesSubtopic = filter.subtopics.some(
        (st) =>
          q.subtopic!.toLowerCase() === st.toLowerCase() ||
          q.subtopic!.toLowerCase().includes(st.toLowerCase())
      )
      if (!matchesSubtopic) return false
    }

    // 6. Difficulty check
    if (
      filter.difficulty &&
      filter.difficulty.length > 0 &&
      !filter.difficulty.includes('All')
    ) {
      const matchesDiff = filter.difficulty.some(
        (d) => q.difficulty.toLowerCase() === d.toLowerCase()
      )
      if (!matchesDiff) return false
    }

    return true
  })
}

/**
 * Calculate dynamic selection score for a question candidate
 */
export function calculateQuestionScore(
  q: PracticeQuestion,
  history: Record<string, UserAttemptHistory>,
  weakTopics: Set<string>,
  mode: PracticeMode
): number {
  let score = 0
  const qId = q.question_id || q.id
  const h = history[qId]

  if (mode === 'random') {
    return Math.random() * 10
  }

  if (!h || h.attempt_count === 0) {
    score += PRIORITY_WEIGHTS.never_attempted
    if (mode === 'new_questions') {
      score += 100 // Boost new questions drastically
    }
  } else {
    if (mode === 'new_questions') {
      return -100 // Exclude already attempted questions if possible
    }

    if (h.incorrect_count > 0 && h.correct_count === 0) {
      score += PRIORITY_WEIGHTS.previously_incorrect
      if (mode === 'previously_incorrect') {
        score += 80
      }
    } else if (h.incorrect_count > 0 && h.correct_count > 0) {
      score += Math.max(1, PRIORITY_WEIGHTS.previously_incorrect - h.correct_count * 2)
      if (mode === 'previously_incorrect') {
        score += 40
      }
    } else if (h.correct_count === 1) {
      score += PRIORITY_WEIGHTS.correct_once
    } else if (h.correct_count > 1) {
      score += PRIORITY_WEIGHTS.correct_repeatedly
    }

    if (h.is_recently_seen) {
      score += PRIORITY_WEIGHTS.recently_attempted
    }
    if (h.attempt_count > 3) {
      score += PRIORITY_WEIGHTS.frequently_seen
    }
  }

  // Weak topic boost
  if (weakTopics.has(q.topic.toLowerCase())) {
    score += PRIORITY_WEIGHTS.weak_topic
    if (mode === 'weak_areas') {
      score += 60
    }
  }

  // Small random jitter to break ties and ensure variety
  score += Math.random() * 2

  return score
}

/**
 * Intelligent Balanced Distribution Algorithm
 */
export function selectSmartQuestions(
  pool: PracticeQuestion[],
  count: number,
  mode: PracticeMode,
  history: Record<string, UserAttemptHistory> = {},
  weakTopics: Set<string> = new Set()
): PracticeQuestion[] {
  if (pool.length <= count) {
    // If pool is smaller than or equal to requested count, shuffle and return all
    return shuffleArray([...pool])
  }

  // Score each candidate
  const scored: QuestionCandidate[] = pool.map((q) => ({
    ...q,
    selection_score: calculateQuestionScore(q, history, weakTopics, mode),
  }))

  // Sort descending by priority score
  scored.sort((a, b) => (b.selection_score || 0) - (a.selection_score || 0))

  if (mode === 'random') {
    return shuffleArray(scored).slice(0, count)
  }

  if (mode === 'weak_areas' || mode === 'previously_incorrect' || mode === 'new_questions') {
    // Top scored questions with light shuffle in top bucket
    const topBucket = scored.slice(0, Math.min(scored.length, count * 2))
    return shuffleArray(topBucket).slice(0, count)
  }

  // BALANCED MODE: Group by topic to ensure fair topic distribution
  const byTopic: Record<string, QuestionCandidate[]> = {}
  scored.forEach((q) => {
    const t = q.topic || 'General'
    if (!byTopic[t]) byTopic[t] = []
    byTopic[t].push(q)
  })

  const topics = Object.keys(byTopic)
  const selected: QuestionCandidate[] = []
  const selectedIds = new Set<string>()

  // Round-robin selection across topics from highest scored items
  let round = 0
  while (selected.length < count && round < 50) {
    let addedInRound = false
    for (const t of topics) {
      if (selected.length >= count) break
      const topicList = byTopic[t]
      if (round < topicList.length) {
        const candidate = topicList[round]
        const cId = candidate.question_id || candidate.id
        if (!selectedIds.has(cId)) {
          selected.push(candidate)
          selectedIds.add(cId)
          addedInRound = true
        }
      }
    }
    round++
    if (!addedInRound) break
  }

  // If still need more, take remaining top items
  if (selected.length < count) {
    for (const q of scored) {
      const cId = q.question_id || q.id
      if (!selectedIds.has(cId)) {
        selected.push(q)
        selectedIds.add(cId)
        if (selected.length >= count) break
      }
    }
  }

  // Randomize the final generated session so questions don't appear in topic clumps
  return shuffleArray(selected)
}

/**
 * Fisher-Yates shuffle
 */
export function shuffleArray<T>(array: T[]): T[] {
  const shuffled = [...array]
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]]
  }
  return shuffled
}

/**
 * Extract dynamic filter options from question pool
 */
export function extractFilterOptions(
  allQuestions: PracticeQuestion[],
  currentFilter: Partial<PracticeFilterState>
): DynamicFilterOptions {
  const medium = currentFilter.medium || 'english'

  // Filter pool by medium first
  const mediumPool = allQuestions.filter(
    (q) => q.medium.toLowerCase() === medium.toLowerCase()
  )

  // Initialize subjects from subject metadata registry
  const allMetadata = getAllSubjectMetadata()
  const subjectsMap: Record<string, { count: number; code: string; teluguName: string }> = {}

  allMetadata.forEach((meta) => {
    subjectsMap[meta.name] = {
      count: 0,
      code: meta.code,
      teluguName: meta.teluguName,
    }
  })

  mediumPool.forEach((q) => {
    if (subjectsMap[q.subject]) {
      subjectsMap[q.subject].count++
    } else {
      subjectsMap[q.subject] = { count: 1, code: q.subject.slice(0, 3).toUpperCase(), teluguName: q.subject }
    }
  })

  const available_subjects = Object.entries(subjectsMap).map(([name, data]) => ({
    id: name,
    name,
    teluguName: data.teluguName,
    code: data.code,
    question_count: data.count,
  }))

  // Narrow pool by subject for topics / subtopics
  const subjectPool = currentFilter.subject && currentFilter.subject !== 'All'
    ? mediumPool.filter((q) => {
        if (q.subject.toLowerCase() === currentFilter.subject?.toLowerCase()) return true
        const isGKFilter =
          currentFilter.subject?.toLowerCase().includes('gk') ||
          currentFilter.subject?.toLowerCase().includes('general knowledge') ||
          currentFilter.subject?.toLowerCase().includes('current affairs')
        const isGKQuestion =
          q.subject.toLowerCase().includes('gk') ||
          q.subject.toLowerCase().includes('general knowledge') ||
          q.subject.toLowerCase().includes('current affairs')
        if (isGKFilter && isGKQuestion) return true

        const isPedFilter =
          currentFilter.subject?.toLowerCase().includes('pedagogy') ||
          currentFilter.subject?.toLowerCase().includes('educational psychology') ||
          currentFilter.subject?.toLowerCase().includes('perspectives in education') ||
          currentFilter.subject?.toLowerCase().includes('cdp')
        const isPedQuestion =
          q.subject.toLowerCase().includes('pedagogy') ||
          q.subject.toLowerCase().includes('educational psychology') ||
          q.subject.toLowerCase().includes('perspectives in education') ||
          q.subject.toLowerCase().includes('cdp')
        if (isPedFilter && isPedQuestion) return true

        return false
      })
    : mediumPool

  // Available classes
  const classesSet = new Set<string>()
  subjectPool.forEach((q) => {
    if (q.class_level) classesSet.add(q.class_level)
  })
  const available_classes = Array.from(classesSet).sort((a, b) => {
    const numA = parseInt(a.replace(/\D/g, ''), 10) || 0
    const numB = parseInt(b.replace(/\D/g, ''), 10) || 0
    return numA - numB
  })

  // Narrow pool by class for topics
  const classPool = currentFilter.class_levels &&
    currentFilter.class_levels.length > 0 &&
    !currentFilter.class_levels.includes('All') &&
    !currentFilter.class_levels.includes('All Classes')
    ? subjectPool.filter((q) =>
        currentFilter.class_levels!.some(
          (lvl) =>
            q.class_level.toLowerCase().includes(lvl.toLowerCase()) ||
            lvl.toLowerCase().includes(q.class_level.toLowerCase())
        )
      )
    : subjectPool

  // Topics and their subtopics
  const topicMap: Record<string, { count: number; subtopics: Set<string> }> = {}
  classPool.forEach((q) => {
    if (!topicMap[q.topic]) {
      topicMap[q.topic] = { count: 0, subtopics: new Set() }
    }
    topicMap[q.topic].count++
    if (q.subtopic) {
      topicMap[q.topic].subtopics.add(q.subtopic)
    }
  })

  const available_topics = Object.entries(topicMap).map(([name, data]) => ({
    name,
    count: data.count,
    subtopics: Array.from(data.subtopics),
  }))

  // Available difficulties with count
  const diffMap: Record<string, number> = { Easy: 0, Medium: 0, Hard: 0 }
  classPool.forEach((q) => {
    const diff = q.difficulty || 'Medium'
    diffMap[diff] = (diffMap[diff] || 0) + 1
  })
  const available_difficulties = Object.entries(diffMap).map(([name, count]) => ({
    name,
    count,
  }))

  // Total matching questions based on all active filters
  const matched = filterQuestionPool(allQuestions, currentFilter)

  return {
    medium,
    available_subjects,
    available_classes: available_classes.length > 0 ? available_classes : ['Class 3', 'Class 4', 'Class 5', 'Class 6', 'Class 7', 'Class 8', 'Class 9', 'Class 10'],
    available_topics,
    available_difficulties,
    total_matching_questions: matched.length,
  }
}

