   *  - English Medium (`gk_english_medium`)
   *  - Telugu Medium (`gk_telugu_medium`)
   */
  async fetchQuestions(medium?: PracticeMedium): Promise<PracticeQuestion[]> {
    if (medium) {
      return fetchGKQuestionsByMedium(medium)
