    return data.map((row) => mapRowToPracticeQuestion(row, 'telugu', 'telugu_medium_math'))
  } catch (err) {
    console.error('[Telugu Math Fetch Algorithm] Execution error:', err)
    return fallbackToUnifiedMathQuestions('telugu', filter)
  }
