    }

    // 8. Pagination
    if (filter.limit) {
      const from = filter.offset || 0
      const to = from + filter.limit - 1
      query = query.range(from, to)
    }

    const { data, error } = await query

    if (error) {
      console.warn('[Telugu Science Fetch Algorithm] Table query error, falling back:', error.message)
