    return data.map((row) => mapRowToPracticeQuestion(row, 'telugu', 'telugu_medium_science'))
  } catch (err) {
    console.error('[Telugu Science Fetch Algorithm] Execution error:', err)
    return fallbackToUnifiedScienceQuestions('telugu', filter)
  }
