    literaturePct?: number  // సాహిత్యం (కవులు, కావ్యాలు, ప్రబంధాలు)
    vocabularyPct?: number  // భాషాంశాలు (పర్యాయపదాలు, నానార్థాలు, జాతీయాలు)
    pedagogyPct?: number    // బోధనా పద్ధతులు (Telugu Pedagogy)
